window.CURSO = [{"number":1,"title":"Las grandes ideas económicas","items":[{"id":"1.0","title":"Introducción","ideas":["Una definición clásica pregunta cómo asignar medios escasos entre fines alternativos. Expresa un problema de elección incluso cuando los medios y objetivos ya están dados. El profesor observa que tratarlo como un problema de optimización puede sugerir que alguien conoce toda la información necesaria para planificar la asignación.","El curso adopta una perspectiva de ciencia social. Estudia cómo las acciones individuales y los intercambios voluntarios generan procesos de mercado, cooperación y riqueza, y qué instituciones permiten esos procesos. El profesor vincula la microeconomía con las relaciones de mercado y la macroeconomía con la respuesta de la actividad a las políticas públicas, y advierte que la frontera es difusa."],"source":"1–2, 11","page":2,"questions":[{"id":"1.0-c1","type":"comprension","prompt":"¿Qué elementos exige la definición de economía como asignación?","options":["Medios ilimitados, fines conocidos y una regla para fijar un precio común.","Debe haber medios escasos, fines alternativos y una elección sobre qué fines atender con los medios disponibles.","Un medio escaso, un único uso posible y la ausencia de elección."]},{"id":"1.0-c2","type":"comprension","prompt":"¿Por qué utiliza el profesor la comparación con un ingeniero?","options":["Para defender que el economista debe fijar físicamente las cantidades que necesita cada familia.","Para mostrar que la optimización de unos datos dados puede hacer parecer que toda la economía admite un diseño planificado.","Para identificar el coste de oportunidad con la dificultad técnica de fabricar una máquina."]},{"id":"1.0-c3","type":"comprension","prompt":"¿Qué estudia la segunda definición?","options":["La contabilización de cobros y pagos como objeto exclusivo de la ciencia económica.","La determinación del plan técnico que maximiza una producción previamente fijada.","Las interacciones humanas, en particular las relaciones libres de intercambio y los procesos sociales mediante los que las personas crean riqueza."]},{"id":"1.0-c4","type":"comprension","prompt":"¿Por qué cuentan las instituciones en esta segunda perspectiva?","options":["Porque las reglas bajo las que se actúa condicionan la posibilidad de contratar, intercambiar y coordinar planes individuales.","Porque una institución determina qué utilidad ha de sentir cada comprador.","Porque sustituyen la necesidad de coordinar a personas cuyos planes son diferentes."]},{"id":"1.0-c5","type":"comprension","prompt":"¿Qué distinción entre micro y macro propone la clase?","options":["Acerca la primera al estudio de las relaciones de intercambio y la segunda a la respuesta económica a las políticas públicas. Presenta la distinción como aproximada.","La microeconomía estudiaría las políticas públicas agregadas y la macroeconomía las decisiones de intercambio individual.","La microeconomía sería el estudio de países pequeños y la macroeconomía el de países grandes."]},{"id":"1.0-d","type":"desarrollo","prompt":"Explica cómo cambiaría el análisis de un mercado de alquileres al pasar de la primera definición de economía a la segunda."}]},{"id":"1.1","title":"Los incentivos importan: interés personal y cooperación","ideas":["El interés personal es el fin que persigue quien actúa. Puede consistir en pagar estudios a sus hijos, ayudar a alguien, disfrutar del afecto o lograr reconocimiento. Un incentivo es aquello que, dadas las circunstancias, mueve al actor a elegir una conducta. La motivación económica incluye fines sin recompensa monetaria.","El pescadero necesita que alguien quiera su producto a su precio. Servir a clientes que eligen libremente es el medio para alcanzar sus propios fines. Adam Smith ilustró esta cooperación con el carnicero, el cervecero y el panadero en La riqueza de las naciones (1776). El profesor la reconoce en el supermercado que ofrece café colombiano y pasta italiana, en la ropa de diseño asequible de Amancio Ortega y en el sistema operativo que asocia a Bill Gates."],"source":"2–3, 11","page":3,"questions":[{"id":"1.1-c1","type":"comprension","prompt":"¿Qué diferencia hay entre el fin del pescadero y el servicio que presta?","options":["Su fin es el de sus compradores, de modo que debe preferir el pescado al uso del ingreso.","El servicio consiste en financiar los estudios de los compradores en vez de venderles productos.","Puede querer financiar los estudios de sus hijos. Para obtener ingresos ofrece pescado en condiciones que interesan a quienes compran."]},{"id":"1.1-c2","type":"comprension","prompt":"¿Cómo interpreta la clase una donación anónima?","options":["Ayudar puede ser un fin propio. La satisfacción de hacerlo cuenta como incentivo aunque no haya pago ni reconocimiento público.","Solo es explicable si el receptor ha prometido devolver el importe con intereses.","La falta de reconocimiento impide que la donación pueda servir a un fin del donante."]},{"id":"1.1-c3","type":"comprension","prompt":"¿Qué explica el ejemplo de Smith sobre la cena?","options":["Que obtener una cena exige que el proveedor adopte personalmente los fines de cada comensal.","La provisión continuada de alimentos puede descansar en que quienes los proveen buscan su sustento vendiendo algo que otros desean.","Que el interés en ganarse la vida impide prestar un servicio valioso a desconocidos."]},{"id":"1.1-c4","type":"comprension","prompt":"¿Qué enseña la presencia de café colombiano y pasta italiana en un supermercado?","options":["Que los alimentos importados proceden necesariamente de una sola empresa con un plan común.","Que numerosas personas pueden coordinarse para servir a consumidores distantes sin conocerlos personalmente.","Que el consumidor ha tenido que negociar directamente con cada productor extranjero."]},{"id":"1.1-c5","type":"comprension","prompt":"¿Por qué importa la calidad del pescado para el ingreso del vendedor?","options":["La calidad fija por sí sola el ingreso total, independientemente del precio y las ventas.","Los compradores pueden acudir a otro puesto. Ofrecer pescado fresco a un precio aceptable hace posible la relación comercial.","Una vez pescado el producto, el ingreso depende solo del coste incurrido en capturarlo."]},{"id":"1.1-d","type":"desarrollo","prompt":"Explica por qué perseguir un fin personal puede llevar a cooperar con personas que uno ni siquiera conoce."}]},{"id":"1.2","title":"Las buenas instituciones alinean el interés personal con el interés social","ideas":["El efecto del interés personal depende de las reglas sobre quién puede usar un recurso y quién soporta las consecuencias de agotarlo. Un precio elevado de la carne o el aceite de ballena atrae cazadores incluso donde existe prohibición. Capturar primero reporta un beneficio individual mientras el daño futuro se reparte.","En el ejemplo andaluz, el dueño de un coto vende derechos de caza y conserva interés en futuras temporadas. Ajusta las capturas tanto al riesgo de exterminio como al alimento disponible en invierno. Extender ese principio a las ballenas es una propuesta del profesor. Propiedad privada, libertad contractual, competencia e imperio de la ley integran su marco institucional."],"source":"3–4, 12","page":4,"questions":[{"id":"1.2-c1","type":"comprension","prompt":"¿Qué incentivo conserva el cazador furtivo de ballenas?","options":["La rentabilidad de vender carne y aceite desaparece mientras otras personas también puedan cazar.","Los ingresos por carne y aceite pueden compensarle individualmente mientras solo soporta una parte de la pérdida futura de la especie.","Cada captura le obliga a asumir por sí solo todo el daño futuro que cause a la especie."]},{"id":"1.2-c2","type":"comprension","prompt":"¿Por qué interesa al dueño del coto que queden ciervos?","options":["Porque evitar cualquier caza, incluso a largo plazo, es la única forma de obtener ingresos por permisos.","Porque el precio del derecho de caza solo depende del número de piezas abatidas hoy.","La población que conserve sostiene los derechos de caza que podrá vender en próximas temporadas."]},{"id":"1.2-c3","type":"comprension","prompt":"¿Por qué tampoco conviene maximizar la población de ciervos?","options":["Porque aumentar el número de animales reduce siempre el número de permisos que se pueden vender.","Si excede el alimento disponible, especialmente en invierno, peligran los animales y el valor futuro del coto.","Porque la capacidad del coto está fijada por el precio de los permisos y no por su alimento disponible."]},{"id":"1.2-c4","type":"comprension","prompt":"¿Qué diferencia hay entre los ejemplos de ciervos y ballenas?","options":["El de las ballenas describe la práctica documentada y el de los ciervos es únicamente una propuesta hipotética.","El primero ilustra un mecanismo descrito en cotos andaluces. El segundo propone trasladar ese mecanismo a la conservación de las ballenas.","Los dos ejemplos describen un mismo sistema de derechos privados ya implantado y evaluado en ambas especies."]},{"id":"1.2-c5","type":"comprension","prompt":"¿Qué reglas adicionales a la propiedad menciona la clase?","options":["La libertad de contratar, la libre competencia y el imperio de la ley.","La fijación administrativa de precios, los permisos exclusivos y las cuotas obligatorias de compra.","La prohibición de competir, la intervención discrecional de contratos y los límites generales a la entrada."]},{"id":"1.2-d","type":"desarrollo","prompt":"Explica cómo dos cazadores interesados en ganar dinero pueden tener incentivos opuestos respecto de la conservación de una especie."}]},{"id":"1.2.1","title":"Foro 1: Los incentivos importan","note":"Sin contenido en los archivos adjuntos."},{"id":"1.2.2","title":"Respuesta al foro: Los incentivos importan","note":"Sin contenido en los archivos adjuntos."},{"id":"1.3","title":"Los costes de oportunidad","ideas":["El coste de oportunidad es el valor de la mejor alternativa viable a la que se renuncia al elegir. Puede existir sin desembolso. Importa la valoración del actor, incluido el uso alternativo de su tiempo. Saber cultivar plátanos muy bien no obliga a elegir esa actividad si construir automóviles ofrece una alternativa más valiosa.","En la calle Serrano, la tienda de bicicletas rinde 40.000 euros anuales y el local podría alquilarse por 120.000. El alquiler sacrificado asciende a 120.000 euros. Si las cifras anuales son comparables, operar la tienda supone una diferencia monetaria desfavorable de 80.000 euros. Conviene distinguir estas dos cantidades."],"source":"4–5, 12–13","page":5,"questions":[{"id":"1.3-c1","type":"comprension","prompt":"¿Qué uso del local se sacrifica al mantener la tienda?","options":["Arrendarlo al precio de mercado, con un ingreso alternativo de 120.000 euros al año.","El ingreso de 40.000 euros que genera la tienda al continuar abierta.","Un salario alternativo de 80.000 euros por administrar el local para otro comerciante."]},{"id":"1.3-c2","type":"comprension","prompt":"¿Cuál es la diferencia entre alquiler sacrificado y desventaja monetaria neta?","options":["El primero es 120.000 euros. Tras considerar los 40.000 euros que produce la tienda, la diferencia entre ambas opciones es 80.000 euros.","El alquiler sacrificado es 120.000 euros y la diferencia neta asciende a 160.000 euros.","El alquiler sacrificado es 80.000 euros y la diferencia neta es 120.000 euros."]},{"id":"1.3-c3","type":"comprension","prompt":"¿Por qué tener el local en propiedad no elimina el coste?","options":["Porque usarlo directamente impide cobrar el alquiler que otro pagaría. La renuncia existe aunque no se pague una factura.","Porque el coste de oportunidad de un local siempre es su precio histórico de compra.","Porque aunque sea propietario está obligado a pagarse a sí mismo un alquiler efectivo."]},{"id":"1.3-c4","type":"comprension","prompt":"¿Qué indica el ejemplo de los plátanos sobre las aptitudes?","options":["Que debe cultivarlos quien logre la mayor producción por hora, con independencia de lo que deje de hacer.","La aptitud para una tarea no determina por sí sola su elección. Hay que considerar qué se deja de conseguir en otras tareas.","Que una persona muy cualificada en educación no puede ser productiva en agricultura."]},{"id":"1.3-c5","type":"comprension","prompt":"¿Se suman los valores de todas las alternativas incompatibles?","options":["Se promedian sus rendimientos para estimar el valor que habría tenido renunciar a la decisión.","Sí, porque todas las opciones descartadas dejan de ser realizables al mismo tiempo.","Se considera la mejor alternativa efectivamente sacrificada, pues el actor tampoco habría podido realizar a la vez los demás usos incompatibles."]},{"id":"1.3-d","type":"desarrollo","prompt":"Analiza la decisión del propietario de la tienda de bicicletas y explica qué información falta para anticipar su elección."}],"figure":{"src":"assets/figuras/1.3.svg","alt":"Abrir la tienda o alquilar el local Rendimiento anual en el ejemplo de la calle Serrano Tienda de bicicletas 40.000 € Alquiler del local 120.000 € Al elegir la tienda se renuncia al alquiler de 120.000 €. La diferencia entre rendimientos es 80.000 €."}},{"id":"1.3.1","title":"Cine: Los costes de oportunidad","note":"Sin contenido en los archivos adjuntos."},{"id":"1.3.2","title":"Foro 2: Coste de oportunidad","note":"Sin contenido en los archivos adjuntos."},{"id":"1.3.3","title":"Respuesta al foro: Los costes de oportunidad","note":"Sin contenido en los archivos adjuntos."},{"id":"1.4","title":"Mundo marginal","ideas":["El análisis marginal identifica la unidad que se añade o se sacrifica en una decisión concreta. En el bar, pagar un euro por un refresco enfrenta el beneficio esperado de esa bebida con el mejor uso del euro. La situación y la disponibilidad de ambos recursos influyen en la elección.","Comparar «toda el agua» con «todos los diamantes», o «educación» con «medio ambiente», omite las cantidades que cambian y lo que se obtendría con ellas. Una pregunta evaluable indica quién decide, cuánto recurso reasignaría, en qué circunstancias y con qué uso alternativo."],"source":"5, 13","page":6,"questions":[{"id":"1.4-c1","type":"comprension","prompt":"¿Qué se compara al decidir si se compra el refresco del ejemplo?","options":["El valor de un refresco adicional con el valor del euro que se entregaría en ese momento.","La utilidad de todos los refrescos consumidos durante el año con el saldo total de la cuenta.","La productividad media de la fábrica con el valor nutricional total del refresco."]},{"id":"1.4-c2","type":"comprension","prompt":"¿Qué haría quien prefiere conservar ese euro?","options":["Compraría la bebida, porque disponer físicamente de un euro prueba que le conviene gastarlo.","La compraría siempre que su coste de fabricación fuera inferior al euro, con independencia de sus preferencias.","Renunciaría a comprar esa unidad, pues estima mayor el beneficio de conservar el dinero para otro uso."]},{"id":"1.4-c3","type":"comprension","prompt":"¿Qué es un beneficio marginal?","options":["La suma de todos los beneficios obtenidos por las unidades consumidas hasta hoy.","El beneficio esperado del cambio concreto considerado, por ejemplo el de beber un vaso adicional.","El beneficio total de todas las unidades dividido entre la cantidad consumida."]},{"id":"1.4-c4","type":"comprension","prompt":"¿Qué dato falta al preguntar si es más importante la educación o el medio ambiente?","options":["El número de personas que trabaja en cada sector, sin especificar qué decisión se está valorando.","Qué mejora concreta de una finalidad podría obtenerse y qué mejora de la otra se sacrificaría con los mismos recursos.","El sector que cuenta hoy con el presupuesto total más alto, con independencia de los proyectos."]},{"id":"1.4-c5","type":"comprension","prompt":"¿Cómo puede la sed cambiar la decisión a igual precio?","options":["La sed altera el gasto total anterior, pero no la valoración del siguiente refresco.","Una sed mayor obliga al vendedor a elevar el precio antes de que pueda cambiar la elección.","Una persona sedienta puede atribuir mayor utilidad al mismo refresco, alterando su comparación con el uso alternativo del euro."]},{"id":"1.4-d","type":"desarrollo","prompt":"Reformula una comparación entre agua y diamantes para explicar cómo se toma realmente una decisión marginal."}]},{"id":"1.5","title":"El poder del intercambio","ideas":["Un intercambio voluntario se apoya en valoraciones inversas. El comprador prefiere el pescado al dinero entregado y el pescadero prefiere el dinero al pescado vendido. Ambos anticipan una mejora, aunque sus fines y valoraciones sean diferentes.","Poder vender excedentes hace viable concentrar el esfuerzo en una actividad. Así aparecen productores especializados que consumen bienes muy variados. El habitante de una ciudad dispone de bienes fabricados por otros, mientras que Robinson Crusoe necesita producir por sí mismo lo que consume. Las trabas al intercambio reducen el alcance de esta cooperación."],"source":"6, 14","page":7,"questions":[{"id":"1.5-c1","type":"comprension","prompt":"¿Qué condición de valoración permite la venta del pescado?","options":["Que cada parte prefiera lo que recibe a lo que entrega para esa transacción concreta.","Que ambos prefieran conservar lo que ya tienen antes que aceptar la propuesta.","Que comprador y vendedor atribuyan exactamente la misma prioridad al pescado y al dinero."]},{"id":"1.5-c2","type":"comprension","prompt":"¿Necesita el pescadero valorar poco todo el pescado?","options":["Basta con que valore la suma ofrecida más que la unidad que vende.","Sí, vender una unidad revela necesariamente que para él el resto del pescado carece de utilidad.","Sí, debe preferir cualquier cantidad de dinero a toda la pesca de la jornada."]},{"id":"1.5-c3","type":"comprension","prompt":"¿Qué hace viable producir mucho de un solo bien?","options":["Poder intercambiar el excedente por otros bienes que el productor necesita o desea.","Que disponer de más unidades del mismo bien elimine la necesidad de adquirir otros bienes.","Que el productor tenga que consumir personalmente todas las unidades que fabrica."]},{"id":"1.5-c4","type":"comprension","prompt":"¿Qué significa ser consumidor generalista?","options":["Comprar exclusivamente el bien en cuya producción se ha especializado el trabajador.","Repartir las horas de trabajo entre todos los sectores en los que se desea consumir.","Acceder a una cesta diversa de bienes y servicios aunque el propio trabajo esté concentrado en una actividad."]},{"id":"1.5-c5","type":"comprension","prompt":"¿Qué pierde Robinson Crusoe con el aislamiento?","options":["La posibilidad de aprovechar el trabajo especializado y los excedentes de otras personas.","La posibilidad de elegir entre los fines a los que dedica su propio tiempo.","La capacidad de fabricar o consumir cualquier bien mediante su propio trabajo."]},{"id":"1.5-d","type":"desarrollo","prompt":"Explica cómo un intercambio que no altera la cantidad física de pescado puede beneficiar a ambos y, con el tiempo, ampliar la producción."}]},{"id":"1.6","title":"Riqueza y crecimiento económico","ideas":["El curso relaciona el aumento de la producción y de la renta con la capacidad de costear vacunas, saneamiento e higiene. Estos mecanismos ayudan a interpretar la correlación entre PIB por habitante, supervivencia infantil y satisfacción vital. Un promedio entre países no determina el resultado de cada persona.","Las cifras son históricas y corresponden a las series citadas en clase. Con el umbral del ejemplo, inferior a dos dólares diarios, la pobreza extrema mundial pasó de 1.850 millones (35 %) en 1990 a 767 millones (10,7 %) en 2013. La proporción estimada para 1820 superaba el 90 %. La mortalidad infantil de la serie pasa de más del 35 % en 1900 a menos del 5 % en el periodo final mostrado. La esperanza de vida mundial pasa de 33 a más de 70 años, y la europea de 43 a más de 80."],"source":"6–7, 14–15","page":8,"questions":[{"id":"1.6-c1","type":"comprension","prompt":"¿Qué dos indicadores de pobreza disminuyen entre 1990 y 2013?","options":["El número baja de 1.850 a 767 millones, mientras la proporción mundial se mantiene en el 35 %.","La tasa baja del 35 % al 10,7 %, mientras el número de personas permanece en 1.850 millones.","Tanto el número de personas, de 1.850 a 767 millones, como el porcentaje mundial, del 35 % al 10,7 % según las notas."]},{"id":"1.6-c2","type":"comprension","prompt":"¿Por qué interesa presentar también el porcentaje?","options":["Porque dividir por la población elimina el efecto de cualquier cambio en el umbral de pobreza.","Permite comparar la incidencia relativa cuando cambia la población mundial. La cifra absoluta indica cuántas personas hay en esa situación.","Porque los porcentajes indican directamente cuántas personas están bajo el umbral sin conocer la población."]},{"id":"1.6-c3","type":"comprension","prompt":"¿Cómo puede la riqueza reducir el riesgo de enfermedad?","options":["Elevar los ingresos nominales reduce el riesgo biológico aunque sigan idénticos los recursos sanitarios disponibles.","El aumento del PIB convierte automáticamente a cada individuo en inmune a las infecciones.","Al financiar saneamiento, vacunas e instalaciones higiénicas que reducen la exposición a determinados riesgos."]},{"id":"1.6-c4","type":"comprension","prompt":"¿Qué comparaciones de esperanza de vida ofrece la clase?","options":["Desde 1900, la mundial pasa de 43 a más de 80 años y la europea de 33 a más de 70.","Desde 1900, la mundial pasa de 33 a 43 años y la europea de más de 70 a más de 80.","Desde 1900, la mundial pasa de 33 a más de 70 años y la europea de 43 a más de 80 en las series presentadas."]},{"id":"1.6-c5","type":"comprension","prompt":"¿Cómo interpreta el curso la relación entre renta y satisfacción?","options":["La asociación entre países prueba que cualquier subida nominal de renta genera idéntica mejora de satisfacción en todos.","Los países con mayor renta por habitante tienden a presentar mayor satisfacción declarada. Es una asociación entre grupos, no una predicción individual.","La comparación permite ordenar la satisfacción de dos individuos cualesquiera con solo conocer sus ingresos."]},{"id":"1.6-d","type":"desarrollo","prompt":"Relaciona los cambios históricos de pobreza y salud con el argumento sobre el valor social del crecimiento."}],"figure":{"src":"assets/figuras/1.6.svg","alt":"Pobreza extrema mundial según el umbral utilizado en el curso Población mundial por debajo del umbral 0 % 10 % 20 % 30 % 40 % 1990 35 % 2013 10,7 % De 1990 a 2013 La proporción cayó 24,3 puntos porcentuales. El número de personas pasó de 1.850 a 767 millones. Datos históricos de la clase · Umbral empleado: menos de dos dólares diarios."}},{"id":"1.6.1","title":"Foro 3: Riqueza y crecimiento económico","note":"Sin contenido en los archivos adjuntos."},{"id":"1.6.2","title":"Respuesta al foro: Riqueza y crecimiento económico","note":"Sin contenido en los archivos adjuntos."},{"id":"1.7","title":"Las instituciones importan","ideas":["El profesor compara España y Cuba, con rentas próximas en 1930 y 1950, la trayectoria argentina y la diferencia de renta entre las dos Coreas. En los datos que presenta para 2021, España supera 30.000 dólares por habitante y Cuba queda por debajo de 10.000. La diferencia entre las Coreas se ilustra con un orden de magnitud de diez a uno.","Recursos naturales, capital físico y humano, iniciativa empresarial e inversión exterior contribuyen al crecimiento. Las instituciones inciden en si se acumulan o emplean productivamente. Propiedad protegida, contratos exigibles, dinero estable, competencia y libertad individual afectan a la recompensa esperada de formarse, invertir y emprender. El curso ilustra su tesis con la asociación entre libertad económica y renta."],"source":"7–8, 15–16","page":9,"questions":[{"id":"1.7-c1","type":"comprension","prompt":"¿Por qué Argentina sirve para examinar la hipótesis de los recursos naturales?","options":["Su abundancia de recursos y la evolución de su renta cuestionan que la dotación física baste para explicar la prosperidad.","Porque su evolución demuestra que la abundancia de recursos garantiza por sí sola la convergencia con los países ricos.","Porque Argentina carece de recursos naturales y el ejemplo atribuye a esa ausencia toda su trayectoria."]},{"id":"1.7-c2","type":"comprension","prompt":"¿Qué contraste plantea el curso entre España y Cuba?","options":["Para 2021 la clase sitúa a Cuba por encima de 30.000 dólares por habitante y a España por debajo de 10.000.","La clase sostiene que la similitud de rentas por habitante se mantuvo también en 2021.","Tras rentas comparables en décadas anteriores, la clase cita para 2021 más de 30.000 dólares por habitante en España y menos de 10.000 en Cuba."]},{"id":"1.7-c3","type":"comprension","prompt":"¿Qué incluye el capital humano en esta argumentación?","options":["La formación, el conocimiento y las capacidades que permiten producir, innovar y emprender.","La maquinaria propiedad de los trabajadores y los edificios donde se presta la formación.","El volumen de dinero mantenido en efectivo por los hogares para afrontar gastos laborales."]},{"id":"1.7-c4","type":"comprension","prompt":"¿Cómo puede un contrato exigible favorecer la inversión?","options":["Reduce la incertidumbre sobre el cumplimiento y facilita que las partes comprometan recursos presentes para obtener resultados futuros.","Porque elimina el riesgo de que el producto final se venda a un precio inferior al esperado.","Porque la exigibilidad garantiza que cualquier inversión arrojará un rendimiento superior al de sus alternativas."]},{"id":"1.7-c5","type":"comprension","prompt":"¿Qué observa el índice de libertad económica citado?","options":["Encuentra que una libertad económica mayor se asocia sistemáticamente a una renta por habitante menor en los datos citados.","Mide directamente cuántos dólares adicionales recibe cada hogar por cada reforma, aislando todas las demás causas.","Una asociación entre mayor libertad económica y mayor renta por habitante. El índice por sí solo no aísla todos los factores explicativos."]},{"id":"1.7-d","type":"desarrollo","prompt":"Explica por qué las instituciones pueden afectar tanto al uso de los recursos existentes como a su acumulación."}]},{"id":"1.8","title":"Crisis y recesiones: ¿pueden ser evitadas?","ideas":["Los planes empresariales se elaboran para un futuro cambiante. Cuando la demanda cambia, una empresa puede quebrar. Si muchos planes se frustran a la vez, el ajuste puede convertirse en recesión. El curso distingue estos ajustes de los episodios que atribuye en parte a regulaciones o políticas fiscales y monetarias inadecuadas.","La Gran Depresión estadounidense y la crisis financiera de 2008 sirven en clase para discutir la posibilidad de que las decisiones públicas contribuyan a las fluctuaciones o las agraven. El profesor subraya los límites de las políticas de corrección, sin presentar una garantía de evitar todos los retrocesos."],"source":"8, 16","page":10,"questions":[{"id":"1.8-c1","type":"comprension","prompt":"¿Cómo puede un cambio de preferencias afectar a una empresa?","options":["Afecta únicamente a la proporción de impuestos pagados, porque la disposición a comprar ya estaba fijada al producir.","La empresa conserva sus ingresos previstos si mantiene su plan de producción, aunque los compradores se retiren.","Puede dejar sin compradores la producción planeada, reducir los ingresos y obligar a reorganizar o cerrar el negocio."]},{"id":"1.8-c2","type":"comprension","prompt":"¿Qué añade la simultaneidad de los errores empresariales?","options":["Solo cambia el nombre que recibe cada error, sin poder afectar a la magnitud del descenso agregado.","Al frustrarse numerosos planes al mismo tiempo, la caída puede extenderse al conjunto de la actividad.","La coincidencia temporal garantiza que los errores de unas empresas se compensen con los de otras."]},{"id":"1.8-c3","type":"comprension","prompt":"¿Qué dos orígenes de las fluctuaciones distingue la clase?","options":["La adaptación a condiciones económicas cambiantes y las perturbaciones ligadas a regulaciones y decisiones de política económica.","Las variaciones puramente estacionales, por un lado, y la corrección estadística de esas estaciones, por otro.","La coincidencia de fechas contables y el cambio de moneda en que se publican las cuentas."]},{"id":"1.8-c4","type":"comprension","prompt":"¿Qué episodios históricos ilustra el profesor?","options":["La crisis de las puntocom y la crisis de deuda latinoamericana de los años ochenta.","La Gran Depresión estadounidense y la crisis financiera de 2008.","La crisis del petróleo de 1973 y la crisis asiática de 1997."]},{"id":"1.8-c5","type":"comprension","prompt":"¿Por qué no se promete evitar toda recesión mediante políticas públicas?","options":["Porque el curso supone que todas las recesiones tienen idéntica causa y ya son perfectamente anticipables.","Porque las políticas fiscales y monetarias carecen por completo de efectos sobre la actividad.","Las condiciones cambian, los planes pueden fallar y la propia intervención fiscal o monetaria tiene límites y posibles efectos adversos."]},{"id":"1.8-d","type":"desarrollo","prompt":"Explica la diferencia entre el fracaso de una empresa y una recesión, y sitúa el argumento del profesor sobre la respuesta pública."}]},{"id":"1.9","title":"Inflación y gobiernos","ideas":["La inflación es una subida generalizada de precios que reduce el poder adquisitivo del dinero. Una variación aislada de un precio relativo no basta para diagnosticarla. La clase distingue una causa real, una contracción de oferta que se extiende al nivel general de precios, y una monetaria, un aumento de la cantidad de dinero superior al aumento proporcional de su demanda. El profesor presenta la causa monetaria como la más frecuente y la vincula con las políticas fiscales de los gobiernos y monetarias de los bancos centrales.","La incertidumbre sobre los costes futuros puede aplazar planes empresariales. Al hablar de «impuesto encubierto», el profesor recupera la crítica de Juan de Mariana (1609). Una inflación inesperada reduce el valor real de las obligaciones estatales nominales a tipo fijo y de los cobros de sus tenedores. El importe nominal que figura en el título puede seguir siendo el mismo."],"source":"9, 16–17","page":11,"questions":[{"id":"1.9-c1","type":"comprension","prompt":"¿Basta que suba el precio de un alimento para hablar de inflación?","options":["Sí, toda subida observada en cualquier artículo constituye inflación para el conjunto de la economía.","Sí, basta con que ese alimento tenga un precio mayor durante dos meses aunque el nivel general no varíe.","No. Hay que identificar un aumento generalizado de precios, aunque una perturbación concreta pueda propagarse."]},{"id":"1.9-c2","type":"comprension","prompt":"¿Qué condición añade la explicación monetaria a la creación de dinero?","options":["La oferta monetaria debe crecer más que la demanda de mantener dinero, en términos proporcionales.","Que ambas crezcan exactamente en la misma proporción, con independencia de cuánto dinero se desee mantener.","Que la demanda de saldos monetarios crezca más que la cantidad ofrecida."]},{"id":"1.9-c3","type":"comprension","prompt":"¿Cómo puede una perturbación real elevar el nivel de precios?","options":["Una mejora general de productividad encarece necesariamente el nivel general al aumentar la oferta disponible.","Una caída aislada de demanda de un producto eleva automáticamente el precio de todos los demás bienes.","Una contracción de oferta suficientemente amplia, o que se transmita a muchos bienes, puede encarecer de forma general la producción disponible."]},{"id":"1.9-c4","type":"comprension","prompt":"¿Por qué puede frenarse una inversión durante la inflación?","options":["Porque todos los proyectos conservan los mismos ingresos reales pero ven duplicarse siempre sus costes reales.","Porque la inflación convierte en pérdida contable toda inversión que genere cobros futuros.","La incertidumbre sobre el coste de los insumos y el valor real de los cobros dificulta evaluar si el proyecto compensará."]},{"id":"1.9-c5","type":"comprension","prompt":"¿Quién pierde poder adquisitivo si se devuelve una deuda nominal fija tras una inflación inesperada?","options":["El acreedor recibe el importe pactado en una moneda de menor poder adquisitivo. La carga real del deudor disminuye.","El deudor, porque necesita entregar más unidades monetarias que las pactadas aunque la cifra nominal esté fijada.","Ninguna de las partes, porque una cuantía nominal fija garantiza el mismo poder adquisitivo en el cobro."]},{"id":"1.9-d","type":"desarrollo","prompt":"Relaciona el «impuesto encubierto» de la clase con la incertidumbre que afronta una empresa durante la inflación."}]},{"id":"1.9.1","title":"Foro 4: Inflación y gobiernos","note":"Sin contenido en los archivos adjuntos."},{"id":"1.9.2","title":"Respuesta al foro: Inflación y gobiernos","note":"Sin contenido en los archivos adjuntos."},{"id":"1.10","title":"Bancos centrales","ideas":["Los bancos centrales influyen en la cantidad de dinero en circulación y fijan los tipos de sus operaciones con bancos comerciales. En la explicación del curso, una expansión excesiva puede alimentar inflación, mientras que una restricción demasiado intensa puede reducir el crecimiento o contribuir a una recesión.","El BCE y la Reserva Federal ilustran la dificultad del juicio monetario. La medida adecuada depende de las condiciones económicas y de la demanda de dinero. La capacidad de influir sobre la economía también implica la posibilidad de consecuencias no deseadas."],"source":"9–10, 17","page":12,"questions":[{"id":"1.10-c1","type":"comprension","prompt":"¿Qué dos variables vincula directamente la clase con el banco central?","options":["El salario real de cada trabajador y el precio de los alimentos de primera necesidad.","El tipo del impuesto sobre la renta y la cuantía del gasto público presupuestado.","La cantidad de dinero en circulación y el tipo de interés de sus operaciones con la banca comercial."]},{"id":"1.10-c2","type":"comprension","prompt":"¿A qué relación bancaria alude el tipo de interés mencionado?","options":["Al interés de todas las hipotecas de los hogares, fijado individualmente por el banco central.","A la financiación entre el banco central y los bancos comerciales. Los tipos de otros contratos pueden verse influidos por esa referencia.","A la comisión que cada comercio paga cuando un consumidor utiliza una tarjeta de débito."]},{"id":"1.10-c3","type":"comprension","prompt":"¿Qué riesgo implica una expansión monetaria excesiva?","options":["Que los precios generales deban caer en proporción al dinero creado aunque la demanda de saldos no cambie.","Que la moneda gane necesariamente poder de compra porque hay más unidades disponibles.","Si supera el aumento de la demanda de dinero, puede reducir su poder adquisitivo y generar inflación."]},{"id":"1.10-c4","type":"comprension","prompt":"¿Qué riesgo implica una restricción demasiado intensa?","options":["Puede desacelerar la actividad y el crecimiento o contribuir a una recesión.","Que se elimine toda fluctuación económica al mantenerse constante el dinero que ya existía.","Que la oferta de crédito y el gasto se expandan automáticamente por encima de sus niveles iniciales."]},{"id":"1.10-c5","type":"comprension","prompt":"¿Qué organismos utiliza la clase para ilustrar el dilema?","options":["El Banco Central Europeo y la Reserva Federal de Estados Unidos.","La Comisión Europea y el Departamento del Tesoro estadounidense.","El Banco Mundial y el Fondo Monetario Internacional."]},{"id":"1.10-d","type":"desarrollo","prompt":"Explica por qué la capacidad de un banco central para influir en el dinero y la financiación exige evaluar riesgos en ambas direcciones."}]},{"id":"1.11","title":"La ciencia económica es divertida","ideas":["El cierre presenta la economía como orientación para decisiones cotidianas. Comprar una vivienda, mudarse, endeudarse, estudiar o trabajar exige ordenar fines, comparar usos de tiempo y dinero y considerar qué cambiaría con inflación o recesión. Los gráficos y los conceptos sirven cuando permiten formular mejor la decisión.","El profesor relata que empezó a estudiar economía a los 25 años, en 2004. Encontrar explicaciones a preguntas que antes no sabía abordar ilustra la utilidad que atribuye al aprendizaje, también para quien no trabaja como empresario o economista."],"source":"10, 18","page":13,"questions":[{"id":"1.11-c1","type":"comprension","prompt":"¿Qué clase de utilidad atribuye el profesor a la economía cotidiana?","options":["Ayuda a interpretar el contexto y a comparar alternativas de acuerdo con los fines y recursos de cada persona.","Garantiza acertar las decisiones personales conociendo únicamente el ingreso monetario actual.","Permite ordenar objetivamente los fines de todas las personas con una sola escala universal."]},{"id":"1.11-c2","type":"comprension","prompt":"¿Qué recurso se compromete al elegir entre trabajar y estudiar?","options":["Solo el sueldo ya cobrado por trabajos anteriores, que deja de existir al decidir estudiar.","Además del dinero, el tiempo que solo puede dedicarse a una de las actividades durante el periodo considerado.","Solo la matrícula, porque las horas invertidas en estudiar pueden reutilizarse simultáneamente en trabajar."]},{"id":"1.11-c3","type":"comprension","prompt":"¿Qué pregunta concreta puede formularse antes de comprar una vivienda?","options":["Cómo cambiarían los pagos de una hipoteca a tipo variable y qué otros usos del ahorro quedarían desplazados.","Basta preguntar por el precio anunciado, pues el tipo variable no altera los pagos futuros.","La única pregunta pertinente es cuánto costó construir la vivienda, porque así se conocen exactamente las cuotas futuras."]},{"id":"1.11-c4","type":"comprension","prompt":"¿Qué contexto económico puede importar para una mudanza laboral?","options":["Una recesión puede alterar las oportunidades de empleo y el ingreso esperado en cada ubicación.","Solo el salario de la ciudad de origen, ya que la situación del mercado laboral de destino no influye en la elección.","El nivel de precios del país basta para deducir con certeza el empleo que obtendrá la persona en cualquier ciudad."]},{"id":"1.11-c5","type":"comprension","prompt":"¿Qué ilustra el testimonio sobre empezar economía a los 25 años?","options":["Que el interés por la disciplina puede surgir al descubrir aplicaciones a preguntas reales de la propia vida.","Que a partir de los 25 años se vuelve necesario empezar una carrera de economía para poder trabajar.","Que el interés por la economía depende de alcanzar una edad fija y no de las preguntas personales."]},{"id":"1.11-d","type":"desarrollo","prompt":"Muestra cómo dos ideas de la sesión ayudarían a una persona que duda entre estudiar y aceptar un trabajo."}]}]},{"number":2,"title":"La acción humana aislada y en sociedad","items":[{"id":"2.0","title":"Introducción","ideas":["El curso llama acción humana a una conducta deliberada, voluntaria y consciente que persigue un fin. Un hábito, como cepillarse los dientes, puede seguir siendo deliberado aunque se repita con poca reflexión. La creatividad permite imaginar futuros a partir de experiencias anteriores. Lo que no se observa directamente es el proceso mental por el que el actor elige.","La economía del curso estudia las consecuencias lógicas de actuar. Si los hombres dejan de usar sombrero, cabe investigar qué ocurrirá con precios, fabricantes, empleo y usos alternativos de los recursos, aun desconociendo el motivo personal por el que cambió la moda."],"source":"19–20","page":14,"questions":[{"id":"2.0-c1","type":"comprension","prompt":"¿Qué distingue una acción deliberada de un movimiento reflejo?","options":["La acción se orienta conscientemente a un fin. Un reflejo no requiere esa elección.","La acción se distingue porque siempre logra el resultado perseguido, mientras que el reflejo puede fallar.","Se distingue por la duración del movimiento, ya que los movimientos rápidos son reflejos y los lentos son elecciones."]},{"id":"2.0-c2","type":"comprension","prompt":"¿Por qué lavarse los dientes puede contar como acción humana?","options":["Aunque sea habitual, la persona puede realizarlo voluntariamente para cuidar su higiene.","Porque solo los movimientos que tienen un precio de mercado cuentan como acciones humanas.","Porque todo movimiento repetido del cuerpo pasa a ser voluntario por el mero hecho de repetirse."]},{"id":"2.0-c3","type":"comprension","prompt":"¿Qué parte de la acción permanece sin observación directa?","options":["El proceso mental que lleva a elegir. Otros pueden observar la conducta y sus consecuencias.","El movimiento físico y sus efectos exteriores, que por definición solo conoce quien actúa.","La identidad del medio material, aunque esté claramente visible, pero no la intención, que otros pueden medir directamente."]},{"id":"2.0-c4","type":"comprension","prompt":"¿Qué aporta la creatividad a la acción?","options":["Permite conocer con certeza todos los estados futuros antes de escoger qué hacer.","La posibilidad de imaginar fines y situaciones futuras que todavía no existen utilizando experiencias y conocimientos previos.","Obliga a limitar los fines a situaciones ya vividas exactamente de la misma forma."]},{"id":"2.0-c5","type":"comprension","prompt":"¿Qué estudiaría el economista si desaparece la moda del sombrero?","options":["Buscaría el cambio de material del sombrero que necesariamente explica cualquier pérdida de popularidad.","Determinaría qué sombrero debe gustar más a cada comprador usando el coste de fabricarlo.","Cómo la menor disposición a comprar afecta a las ventas, la producción, los recursos empleados y otros mercados."]},{"id":"2.0-d","type":"desarrollo","prompt":"Explica con el ejemplo de los sombreros cómo puede analizarse una decisión cuyos motivos íntimos no se observan."}]},{"id":"2.1","title":"Los fines y los medios","ideas":["Los fines son los estados que el actor pretende alcanzar. Pueden multiplicarse y su importancia se ordena subjetivamente. Una persona puede desear tener hijos a los 19 y a los 26 años y, sin embargo, situar ese objetivo en posiciones diferentes de su escala.","Los medios son los recursos que cree útiles para sus fines, como tiempo, dinero o herramientas. Son escasos respecto de los usos posibles y su utilidad también depende de la persona. Un coche puede prestar un servicio distinto a quien trabaja a cinco minutos de casa y a quien viaja 80 km diarios. La pregunta económica es cómo se orientan los medios escasos hacia los fines más valorados de múltiples actores."],"source":"20–21","page":15,"questions":[{"id":"2.1-c1","type":"comprension","prompt":"¿Qué convierte un resultado posible en un fin para el actor?","options":["Que sea el resultado más fácil de medir en dinero aunque no motive ninguna acción.","Que sea técnicamente realizable aunque la persona no desee alcanzarlo.","Que lo desee y dirija su acción a alcanzarlo."]},{"id":"2.1-c2","type":"comprension","prompt":"¿Qué significa que los fines sean ilimitados?","options":["Que cada persona quiere una cantidad infinita de todos y cada uno de los bienes disponibles.","Que todos los fines se pueden realizar simultáneamente porque no hay límites a los deseos.","Que pueden surgir nuevos fines sin que exista un inventario final que agote todos los deseos posibles."]},{"id":"2.1-c3","type":"comprension","prompt":"¿Cómo puede el mismo fin cambiar sin desaparecer?","options":["Puede subir o bajar en la escala de preferencias cuando cambian la edad, los proyectos o las circunstancias.","Mantiene una prioridad fija porque conservar el nombre del fin implica que su importancia no cambia.","Solo puede cambiar si se modifica el precio del objeto, con independencia de los planes de la persona."]},{"id":"2.1-c4","type":"comprension","prompt":"¿Por qué el mismo automóvil puede tener utilidades distintas?","options":["Sus servicios atienden fines diferentes. Ahorrar un viaje diario de 80 km puede importar más que recorrer una distancia muy corta.","Porque la utilidad depende únicamente del coste de fabricación y cambia con el precio contable asignado.","Porque el automóvil adquiere automáticamente mayor potencia física al pertenecer a alguien que vive más lejos."]},{"id":"2.1-c5","type":"comprension","prompt":"¿Qué enseña la varita que crea un huevo frito?","options":["Si obtenerlo no exigiera medios escasos, desaparecería la necesidad de economizar los recursos que hoy requiere producirlo y distribuirlo.","Que producir un huevo sin recursos escasos aumentaría el coste de oportunidad de cada huevo adicional.","Que bastaría poder crear un huevo sin coste para eliminar la escasez de todos los bienes de la sociedad."]},{"id":"2.1-d","type":"desarrollo","prompt":"Explica cómo se relacionan la escasez de medios y el carácter subjetivo de los fines usando la decisión de tener un coche."}]},{"id":"2.2","title":"El tiempo","ideas":["El tiempo es un medio económico porque es limitado y útil para fines incompatibles. El reloj mide una duración objetiva, mientras que el coste de esperar depende de la situación del actor. La preferencia temporal expresa que, manteniendo las demás circunstancias, se prefiere alcanzar un mismo fin antes.","Una preferencia temporal alta exige una compensación futura relativamente grande para renunciar a un bien presente. Una baja permite aceptar la espera por un incremento menor. La comparación entre un niño impaciente y un adulto más paciente es ilustrativa. Una persona puede ahorrar pese a preferir el presente si espera un beneficio futuro que compense la espera."],"source":"21–22","page":16,"questions":[{"id":"2.2-c1","type":"comprension","prompt":"¿Por qué hay que economizar una hora?","options":["Porque dedicar una hora a una tarea permite guardarla y emplearla además en otra tarea incompatible.","Solo puede emplearse una vez y puede servir para varios fines que compiten entre sí.","Porque toda hora tiene exactamente el mismo precio de mercado para cualquier persona."]},{"id":"2.2-c2","type":"comprension","prompt":"¿Qué diferencia hay entre duración objetiva y valoración subjetiva de la espera?","options":["El reloj mide el mismo intervalo para todos, pero cada persona aprecia de forma distinta el retraso de su fin.","Ambas son medidas objetivas que se obtienen contando minutos, sin atender al fin que se retrasa.","La duración del reloj depende de la impaciencia y la valoración de la espera es idéntica para todos."]},{"id":"2.2-c3","type":"comprension","prompt":"¿Cómo se compara el mismo bien hoy y mañana en el principio de preferencia temporal?","options":["Se prefiere el de mañana por el mero hecho de estar más alejado en el tiempo.","La fecha carece de relevancia para quien valora el bien si su cantidad y calidad son idénticas.","Si todo lo demás permanece constante, se prefiere disponer de él antes."]},{"id":"2.2-c4","type":"comprension","prompt":"¿Qué compensación exigirá, en general, quien tiene alta preferencia temporal?","options":["Ninguna compensación, porque alta preferencia temporal significa alta preferencia por posponer el uso.","Una recompensa futura mayor para renunciar al beneficio inmediato.","Una recompensa futura menor que la que necesitaría alguien con poca urgencia por consumir hoy."]},{"id":"2.2-c5","type":"comprension","prompt":"¿Es compatible ahorrar con la preferencia por el presente?","options":["No, ahorrar exige atribuir siempre más valor al mismo bien futuro que al presente.","Sí. Un bien futuro más valorado puede compensar la espera y justificar el ahorro.","Sí, pero únicamente si la espera carece de valor para el ahorrador en todas sus decisiones."]},{"id":"2.2-d","type":"desarrollo","prompt":"Compara a dos personas que reciben la misma oferta de aplazar un consumo y explica por qué podrían decidir de manera diferente."}]},{"id":"2.3","title":"El cálculo económico","ideas":["Actuar supone planificar con medios presentes para alcanzar resultados futuros inciertos. El cálculo económico, en el sentido de la clase, compara la satisfacción subjetiva esperada de un fin con el valor de la mejor alternativa sacrificada. El beneficio psíquico expresa una preferencia y no exige medir el bienestar en unidades numéricas.","Ex ante se decide si el proyecto parece preferible a sus alternativas. Ex post se compara su resultado real con lo que se habría podido lograr utilizando los mismos medios. Comprar suelo, construir una vivienda y venderla puede dejar un beneficio monetario positivo y aun así resultar menos atractivo que otro proyecto si los costes de construcción superan lo previsto."],"source":"22–23","page":17,"questions":[{"id":"2.3-c1","type":"comprension","prompt":"¿Qué hace inevitable la incertidumbre?","options":["Los efectos de una acción se completan en el futuro y el actor no controla ni conoce todas las circunstancias que entonces existirán.","Que el agente se equivoque siempre en su previsión aunque conozca de antemano todas las circunstancias.","Que todos los resultados de una acción sean incognoscibles incluso después de haberse producido."]},{"id":"2.3-c2","type":"comprension","prompt":"¿Qué términos contrapone el cálculo subjetivo?","options":["El valor del fin esperado y el valor de la alternativa menos atractiva que se pueda imaginar.","El valor del fin esperado y el valor de la mejor alternativa que se sacrificaría para obtenerlo.","El coste contable de la acción y la suma de los precios históricos de todos los bienes del actor."]},{"id":"2.3-c3","type":"comprension","prompt":"¿Qué función cumple el cálculo ex ante?","options":["Certifica que una alternativa tendrá éxito si su coste monetario previsto es positivo.","Determina el resultado realmente obtenido usando información que solo se conoció después.","Orienta la decisión de asumir o descartar una acción según las alternativas y expectativas disponibles al decidir."]},{"id":"2.3-c4","type":"comprension","prompt":"¿Qué información añade la evaluación ex post?","options":["Únicamente las intenciones iniciales, descartando el resultado observado por ser posterior a la decisión.","El resultado efectivamente logrado y las condiciones conocidas después, como costes superiores a los presupuestados.","El resultado cierto de todas las decisiones descartadas, aunque ninguna llegara a ejecutarse."]},{"id":"2.3-c5","type":"comprension","prompt":"¿Puede haber ingresos netos positivos y pérdida frente a la alternativa?","options":["Sí. Un proyecto puede dar beneficio contable y, sin embargo, rendir menos que el mejor uso alternativo de sus medios.","No, unos ingresos superiores a los gastos bastan para demostrar que se eligió el uso más valioso.","Sí, pero únicamente si la alternativa habría tenido pérdidas monetarias aún mayores que las del proyecto elegido."]},{"id":"2.3-d","type":"desarrollo","prompt":"Explica por qué construir una casa puede ser sensato antes de iniciar las obras y decepcionante tras venderla."}]},{"id":"2.4","title":"Intercambio y división del trabajo y del conocimiento: ventajas absolutas y ventajas comparativas","ideas":["El intercambio de excedentes permite dividir tanto el trabajo como el conocimiento. Quien produce huevos puede obtener leche o carne sin aprender todos los oficios. Ampliar el grupo abre más especializaciones, diversifica riesgos y eleva la producción agregada. El curso asocia las dificultades de intercambio en Argentina y Venezuela con una menor división del trabajo y cita descensos de renta por habitante en los periodos observados.","La ventaja absoluta consiste en producir más con los mismos recursos o lo mismo con menos. La ventaja comparativa se mide por el menor coste de oportunidad. En dos productos A y B, el coste de una unidad de A se expresa en unidades de B sacrificadas. La clase asocia el primer concepto a Smith y el segundo a Ricardo. Puede convenir intercambiar incluso si una persona es más productiva en ambas tareas.","El profesor sabe cultivar plátanos, pero hacerlo le apartaría de un proyecto educativo muy valorado. Las rosas cultivadas en Kenia ilustran el mismo principio a escala internacional. El dinero reduce los costes de transacción y el sistema de precios ayuda a coordinar las etapas de producción entre desconocidos."],"source":"23–26","page":18,"questions":[{"id":"2.4-c1","type":"comprension","prompt":"¿Qué gana el productor de huevos al poder intercambiar su excedente?","options":["Debe aprender por sí mismo a producir todos los bienes que quiera obtener a cambio.","Puede concentrar aprendizaje y esfuerzo en su actividad y adquirir leche, carne y otros bienes producidos por especialistas.","Al vender más huevos elimina la necesidad de adquirir cualquier bien distinto de los huevos."]},{"id":"2.4-c2","type":"comprension","prompt":"¿Qué se compara para detectar una ventaja absoluta?","options":["La producción con iguales recursos o los recursos necesarios para la misma producción en una tarea concreta.","Las unidades del otro bien sacrificadas por cada agente, aun sin saber quién produce más con los mismos recursos.","Los precios de venta de dos bienes, aunque los recursos y las cantidades producidas sean desconocidos."]},{"id":"2.4-c3","type":"comprension","prompt":"¿Cómo se calcula el coste comparativo de producir una unidad de A?","options":["Se dividen las unidades adicionales de A entre las unidades de B sacrificadas, expresando el resultado en A por B.","Se suman las unidades de A producidas y las de B sacrificadas y se divide por las horas totales trabajadas.","Dividiendo las unidades de B que se dejan de producir entre las unidades de A que se obtienen al reasignar los recursos."]},{"id":"2.4-c4","type":"comprension","prompt":"¿Por qué puede convenir al profesor abandonar el cultivo comercial de plátanos?","options":["Su tiempo tiene un uso educativo que valora mucho. Otros agricultores pueden producir plátanos sacrificando alternativas menos valiosas.","Porque para decidir basta comparar kilos de plátanos producidos por hora e ignorar el valor de enseñar.","Porque la ventaja comparativa exige que el profesor sea incapaz de cultivar plátanos con éxito."]},{"id":"2.4-c5","type":"comprension","prompt":"¿Qué dos dificultades de la especialización menciona la sesión y cómo se atienden?","options":["El dinero determina las preferencias de cada productor y los precios eliminan la necesidad de intercambiar.","El dinero reduce los costes del intercambio y los precios transmiten información para coordinar muchas decisiones de producción.","El dinero elimina la escasez de recursos y los precios garantizan que toda empresa especializada obtenga beneficios."]},{"id":"2.4-d","type":"desarrollo","prompt":"Explica por qué dos personas pueden beneficiarse de la especialización aunque una sea más rápida en las dos tareas."}]},{"id":"2.4.1","title":"Cine: El intercambio","note":"Sin contenido en los archivos adjuntos."},{"id":"2.4.2","title":"Cine: División del Trabajo","note":"Sin contenido en los archivos adjuntos."},{"id":"2.4.3","title":"Cine: Ventajas comparativas en 60\"","note":"Sin contenido en los archivos adjuntos."},{"id":"2.4.4","title":"Foro 5: Ventajas comparativas y ventajas absolutas","note":"Sin contenido en los archivos adjuntos."},{"id":"2.4.5","title":"Respuesta al foro: Ventajas comparativas y ventajas absolutas","note":"Sin contenido en los archivos adjuntos."},{"id":"2.5","title":"Los bienes económicos","ideas":["Según los criterios de Carl Menger expuestos en clase, para que una cosa sea un bien hacen falta una necesidad, una relación causal entre las propiedades de la cosa y su satisfacción, conocimiento de esa relación y dominio suficiente para aprovecharla. El petróleo inaccesible o el hielo de la Luna ilustran la falta de dominio.","Un bien libre es útil y tan abundante respecto de los usos que no hay que racionarlo en esas condiciones, como el aire ordinario. Un bien económico es útil, accesible y escaso respecto de los fines. Una técnica de extracción, una nueva utilidad o un cambio en abundancia pueden alterar la clasificación. Puede tratarse de objetos materiales o de actos y abstenciones humanas útiles.","El orden del bien depende de su relación con la necesidad. El pan o café listos para consumo son de primer orden. Amasar, disponer de harina o cultivar trigo intervienen en etapas sucesivamente más alejadas del consumo. Los bienes de orden superior sirven mediante esa cadena causal."],"source":"26–27","page":19,"questions":[{"id":"2.5-c1","type":"comprension","prompt":"¿Qué cuatro requisitos convierten una cosa en bien según el curso?","options":["Una necesidad, propiedades causalmente aptas para satisfacerla, conocimiento de esa relación y control suficiente para utilizar la cosa.","Una necesidad, un precio publicado, una marca reconocible y una transacción comercial ya realizada.","Escasez natural, un coste elevado, propiedad pública y la posibilidad de almacenar el objeto."]},{"id":"2.5-c2","type":"comprension","prompt":"¿Por qué el petróleo inaccesible es distinto del que ya se puede extraer?","options":["La inaccesibilidad transforma el petróleo en otra sustancia, de modo que deja de poseer propiedades aprovechables.","El yacimiento inaccesible ya presta los mismos servicios productivos que el extraíble por tener igual composición.","Falta dominio suficiente en el primer caso. Una mejora técnica puede convertir ese depósito en un recurso utilizable."]},{"id":"2.5-c3","type":"comprension","prompt":"¿Qué distingue el aire libre de un bien económico en una situación concreta?","options":["Que el aire carece de utilidad para el actor, mientras que todo bien útil tiene necesariamente un precio positivo.","La abundancia respecto de sus usos. Si atender una necesidad impide atender otra, aparece el problema de economizar.","Que el aire es natural, mientras que un bien solo cuenta como económico si ha sido fabricado por personas."]},{"id":"2.5-c4","type":"comprension","prompt":"¿Cómo puede un ordenador roto recuperar carácter económico?","options":["Solo puede recuperarlo si vuelve a ejecutar íntegramente sus funciones originales, sin que cuente su uso para piezas.","Basta conservar el precio de su factura original aunque nadie pueda darle ya ningún uso.","Si alguien descubre un uso, por ejemplo aprovechar piezas accesibles y escasas, puede servir a un fin de nuevo."]},{"id":"2.5-c5","type":"comprension","prompt":"¿Por qué el trigo tiene un orden superior al pan listo para comer?","options":["Porque el orden de los bienes se determina por su peso físico antes y después de ser procesados.","Entre el trigo y la satisfacción de la necesidad de alimentarse median más etapas de producción.","Porque la categoría superior indica que el trigo debe ser más caro que cada producto elaborado con él."]},{"id":"2.5-d","type":"desarrollo","prompt":"Sigue el recorrido de una materia hasta el consumo para mostrar cómo cambian su condición económica y su orden."}]},{"id":"2.6","title":"El valor económico","ideas":["El valor de un fin expresa su importancia subjetiva para quien actúa. El actor atribuye utilidad al medio porque espera alcanzar con él ese fin. En el enfoque de la clase, utilidad marginal y escasez económica determinan el valor de una unidad.","La rareza física se refiere a las unidades existentes. La escasez económica relaciona la disponibilidad con los usos deseados. Un alga única puede tener escasa importancia económica y millones de litros de petróleo pueden ser escasos para sus muchos usuarios. Un reloj averiado puede servir al nieto para recordar a su abuelo. Los relojes funcionales del mismo modelo no sustituyen necesariamente ese servicio."],"source":"27–29","page":20,"questions":[{"id":"2.6-c1","type":"comprension","prompt":"¿Cómo pasa la importancia de un fin al medio empleado?","options":["El actor valora el medio según la utilidad que cree que tendrá para alcanzar el fin.","Se transmite en proporción exclusiva al tiempo de trabajo que se empleó en fabricar el medio.","Se asigna según una utilidad fija del objeto que es independiente de los fines de quien actúa."]},{"id":"2.6-c2","type":"comprension","prompt":"¿Por qué un reloj averiado puede ser útil?","options":["Solo conserva utilidad si el fabricante garantiza que volverá a dar la hora.","Puede satisfacer un fin como recordar al abuelo, aunque ya no preste el servicio de indicar la hora.","Porque su precio de compra antiguo obliga a quienes lo hereden a darle la misma valoración."]},{"id":"2.6-c3","type":"comprension","prompt":"¿Qué muestra un alga única que nadie desea utilizar?","options":["Que un ejemplar raro adquiere el mismo valor para cualquier persona aun cuando ninguna le encuentre uso.","Que la rareza física por sí sola no determina un valor económico alto.","Que ser un ejemplar único lo convierte necesariamente en el bien económicamente más valioso."]},{"id":"2.6-c4","type":"comprension","prompt":"¿Por qué hay escasez económica de petróleo aunque existan grandes cantidades?","options":["Porque la escasez significa que prácticamente no existe petróleo en la naturaleza.","Porque basta que una empresa cobre por el petróleo para que los recursos sean escasos aun si todos los usos pudieran satisfacerse gratuitamente.","Porque diversas personas pretenden emplear la oferta accesible en numerosos usos que compiten."]},{"id":"2.6-c5","type":"comprension","prompt":"¿Puede inferirse el valor que el nieto asigna al reloj de la cotización de otro igual?","options":["No necesariamente. La pieza heredada puede prestar un servicio sentimental insustituible para él.","Sí, el precio de reposición mide por completo el recuerdo personal aunque la réplica no proceda del abuelo.","Sí, dos piezas de la misma marca y modelo tienen obligatoriamente idéntico valor subjetivo para el heredero."]},{"id":"2.6-d","type":"desarrollo","prompt":"Explica cómo pueden coexistir una valoración personal elevada de un objeto y un precio de reventa modesto."}]},{"id":"2.6 (Cine)","title":"Bien económico y valor económico","note":"Sin contenido en los archivos adjuntos."},{"id":"2.7","title":"La ley de utilidad marginal decreciente","ideas":["La escala de preferencias es ordinal. Expresa qué fines se sitúan por encima de otros y se revela al elegir. Las circunstancias de tiempo y lugar importan. Las unidades relevantes son homogéneas e intercambiables desde el punto de vista del actor. Al evaluar perder una de ellas se perderá el uso de menor prioridad que el conjunto permite satisfacer.","A medida que se añaden unidades, se atienden fines de menor prioridad y cae la utilidad marginal, manteniendo los demás factores. En el desierto, los fines ordenados son evitar la muerte por sed, evitar la insolación, saciar el hambre, reducir la sed y eliminarla. Tres vasos cubren el primer fin y los dos últimos, un sombrero el segundo y las uvas el tercero.","Perder cualquiera de los tres vasos sacrifica eliminar la sed. Quedando dos, perder otro sacrificaría reducirla. Quedando solo uno, perderlo comprometería la vida. Así, el sombrero supera a un vaso cuando hay tres, mientras que el agua pasa al primer puesto si solo queda un vaso. La paradoja agua-diamantes se comprende comparando unidades disponibles en situaciones concretas."],"source":"29–32","page":21,"questions":[{"id":"2.7-c1","type":"comprension","prompt":"¿Qué expresa una escala ordinal?","options":["El orden relativo de los fines. No permite afirmar que el primero produzca dos veces la satisfacción del segundo.","Una proporción de utilidades que permite comparar numéricamente el bienestar de personas distintas.","Una medida exacta de la distancia de satisfacción que separa cualquier par de fines."]},{"id":"2.7-c2","type":"comprension","prompt":"¿Qué condición deben cumplir los vasos para aplicar el ejemplo?","options":["Deben estar reservados de forma irreversible para fines específicos, sin posibilidad de sustituir un vaso por otro.","Deben haber costado precios distintos para que el consumidor sepa qué vaso valorar más.","Deben prestar el mismo servicio y ser intercambiables para quien decide, en las circunstancias consideradas."]},{"id":"2.7-c3","type":"comprension","prompt":"Con tres vasos en el desierto, ¿qué fin se sacrifica al perder uno?","options":["El de evitar morir de sed, porque el primer vaso adquirido tenía ese destino.","El de eliminar por completo la sed. Se preserva el agua para sobrevivir y para reducirla.","El de evitar la insolación, dado que el sombrero debe descartarse al escasear el agua."]},{"id":"2.7-c4","type":"comprension","prompt":"¿Por qué cambia el orden entre sombrero y vaso cuando solo queda un vaso?","options":["Porque el sol deja de producir riesgo de insolación desde el momento en que queda poca agua.","Ese único vaso atiende ahora la supervivencia, situada por encima de evitar la insolación.","Porque todo vaso adquiere más contenido material cuando es la última unidad disponible."]},{"id":"2.7-c5","type":"comprension","prompt":"¿Qué ocurre al añadir una cuarta unidad de agua?","options":["Atenderá un uso de menor prioridad, si lo hay. El valor de una unidad intercambiable se determinará por ese nuevo uso marginal.","La cuarta unidad adquiere automáticamente el valor del uso más importante que ya cubría la primera.","Se duplica el valor marginal de los tres vasos anteriores aunque no aparezca un uso de mayor prioridad."]},{"id":"2.7-d","type":"desarrollo","prompt":"Explica la paradoja agua-diamantes mediante el destino del último vaso disponible y la posibilidad de sustituir unos vasos por otros."}],"figure":{"src":"assets/figuras/2.7.svg","alt":"Cómo cambia el valor del último vaso de agua Disponibilidad de agua en el desierto 1 vaso Evitar morir de sed 2 vasos Reducir la sed 3 vasos Eliminar la sed Bajo cada cantidad figura el fin que se sacrificaría al perder un vaso. La escala ordena prioridades."}},{"id":"2.7.1","title":"Problemas: Utilidad marginal","note":"Sin contenido en los archivos adjuntos."},{"id":"2.8","title":"La conducta de los consumidores","ideas":["Ante un ingreso limitado, el consumidor compara el beneficio esperado de la siguiente unidad con el valor del mejor uso alternativo de los recursos que consumirla requiere. El precio afecta a lo que debe sacrificar, mientras que la utilidad depende del fin que atendería.","El primer consumo y el segundo pueden satisfacer fines de importancia diferente. Con circunstancias y preferencias constantes, a medida que se dispone de más unidades intercambiables, los usos pendientes tienen prioridad menor. Por eso la decisión puede cambiar entre dos unidades ofrecidas al mismo precio."],"source":"32","page":22,"questions":[{"id":"2.8-c1","type":"comprension","prompt":"¿Qué dos magnitudes compara el consumidor ante la siguiente unidad?","options":["La utilidad media de todas las unidades consumidas y el coste total de producirlas para el fabricante.","El gasto total pasado en ese bien y el número de unidades que conserva el vendedor.","Su beneficio subjetivo esperado y el coste de oportunidad marginal de destinarle recursos."]},{"id":"2.8-c2","type":"comprension","prompt":"¿Por qué hay coste aunque el consumidor tenga dinero suficiente?","options":["Porque el dinero tiene un coste de oportunidad solo cuando se compra mediante un préstamo.","Porque toda compra gasta necesariamente la totalidad del presupuesto disponible.","Porque al pagar ya no podrá usar ese importe para atender otro fin."]},{"id":"2.8-c3","type":"comprension","prompt":"¿Qué hace relevante la utilidad de la siguiente unidad?","options":["Esta indica el beneficio que aportaría la decisión que todavía puede tomarse.","Permite recuperar el precio que se pagó por todas las unidades anteriores al valorar la siguiente.","Permite conocer directamente el beneficio de todos los consumidores sin examinar sus preferencias."]},{"id":"2.8-c4","type":"comprension","prompt":"¿Por qué puede comprarse una bebida y rechazarse una segunda al mismo precio?","options":["La primera puede cubrir una necesidad más urgente. La segunda puede reportar menos valor que el uso alternativo del dinero.","Porque el vendedor está obligado a aumentar el precio de la segunda bebida aunque siga cobrando el mismo importe.","Porque la primera compra reduce necesariamente la cantidad de bebida que contiene la segunda unidad."]},{"id":"2.8-c5","type":"comprension","prompt":"¿Basta conocer cuántas unidades se han consumido para predecir la decisión?","options":["Sí, el número consumido determina por sí solo el orden de preferencias de cualquier persona.","Sí, dos consumidores con igual consumo anterior demandarán siempre la misma cantidad adicional.","También cuentan las preferencias, las circunstancias, el precio y la alternativa disponible."]},{"id":"2.8-d","type":"desarrollo","prompt":"Explica cómo puede decidir un consumidor cuándo dejar de comprar unidades adicionales de un mismo producto."}]},{"id":"2.9","title":"Las preferencias del consumidor","ideas":["Las preferencias ordenan bienes o combinaciones según la utilidad que un consumidor espera obtener dadas sus circunstancias. Preferir refresco a zumo o cine a una película en casa son elecciones entre usos del dinero y del tiempo. Una utilidad subjetiva y marginal permite entender que existan cestas diferentes con presupuestos iguales.","El consumidor compara cestas asequibles y trata de alcanzar la combinación que le reporte mayor satisfacción dentro de su presupuesto. Las decisiones de compra transmiten a través del mercado qué usos de recursos escasos interesa atender. Esta explicación no exige comparar cardinalmente el bienestar de dos individuos."],"source":"32–33","page":23,"questions":[{"id":"2.9-c1","type":"comprension","prompt":"¿Por qué dos consumidores con igual presupuesto pueden comprar bebidas distintas?","options":["Comprar bebidas diferentes indica necesariamente que uno de ellos ha calculado mal su presupuesto.","Sus gustos y prioridades pueden diferir y, por tanto, también la utilidad que esperan de cada bebida.","Un mismo presupuesto les obliga a obtener la misma utilidad de cada bebida aunque sus gustos difieran."]},{"id":"2.9-c2","type":"comprension","prompt":"¿Qué restringe las combinaciones de una cesta?","options":["El presupuesto disponible y los precios de los bienes que la integran.","La utilidad total por sí sola, que determina qué cestas se pueden pagar sin conocer ni precios ni renta.","El número de productos disponibles en la tienda, que garantiza la asequibilidad de cualquier combinación."]},{"id":"2.9-c3","type":"comprension","prompt":"¿Qué se mantiene constante al comparar dos cestas de igual coste?","options":["La cantidad física de cada producto, aunque las combinaciones elegidas sean distintas.","La utilidad que reportan, porque gastar lo mismo equivale siempre a obtener la misma satisfacción.","El desembolso. Se examina cuál de las dos combinaciones prefiere el consumidor."]},{"id":"2.9-c4","type":"comprension","prompt":"¿Cómo entra el tiempo en la elección entre cine y película en casa?","options":["El tiempo solo cuenta cuando el cine lo cobra expresamente como parte del precio de la entrada.","Cada opción puede requerir distinta duración o desplazamiento y sacrificar actividades distintas.","Si la película dura lo mismo, el coste temporal total debe ser idéntico aunque una opción requiera desplazarse."]},{"id":"2.9-c5","type":"comprension","prompt":"¿Cómo se conectan las cestas elegidas con las decisiones productivas?","options":["Las compras revelan qué bienes desean adquirir los consumidores y orientan a quienes deciden a qué dedicar recursos productivos.","Las compras pasadas garantizan la demanda futura y eliminan todo riesgo de producir la cesta equivocada.","Las decisiones de producción se toman sin atender a las ventas, porque estas dependen exclusivamente del presupuesto de cada empresa."]},{"id":"2.9-d","type":"desarrollo","prompt":"Explica cómo intervienen preferencias, utilidad marginal y presupuesto al llenar una cesta con varios productos."}]},{"id":"2.10","title":"La relación marginal de sustitución","ideas":["La relación marginal de sustitución (RMS) expresa cuántas unidades de Y se está dispuesto a ceder por una unidad adicional de X manteniendo constante la utilidad. Una curva de indiferencia reúne combinaciones que el consumidor considera igual de satisfactorias. Para un tramo, la RMS media en valor positivo es −ΔY/ΔX. Para cambios infinitesimales es el valor absoluto de la pendiente tangente.","Con peras en X y manzanas en Y, pasar de (1, 12) a (2, 8) da una RMS media de −(8 − 12)/(2 − 1) = 4 manzanas por pera. A medida que aumentan las peras y escasean las manzanas, se ceden menos manzanas por cada pera adicional. En la curva de la clase, la pendiente se hace menos negativa y la RMS puede pasar de más de uno a menos de uno."],"source":"33–34","page":24,"questions":[{"id":"2.10-c1","type":"comprension","prompt":"¿Qué permanece constante al moverse sobre una curva de indiferencia?","options":["El nivel de utilidad del consumidor. Cambia la composición de la cesta.","La cantidad de ambos bienes, que debe permanecer fija en todos los puntos de la curva.","El gasto total en dinero, que define por sí solo cualquier curva de indiferencia."]},{"id":"2.10-c2","type":"comprension","prompt":"¿Qué bien se entrega y cuál se obtiene si X son peras e Y son manzanas?","options":["Al avanzar a la derecha se entregan peras para conseguir manzanas adicionales.","Al avanzar a la derecha se renuncia simultáneamente a peras y manzanas para conservar la utilidad.","Se entregan manzanas para recibir peras adicionales al recorrer la curva hacia la derecha."]},{"id":"2.10-c3","type":"comprension","prompt":"¿Cuál es la RMS media entre una pera y doce manzanas y dos peras y ocho manzanas?","options":["Ocho manzanas por pera, tomando la cantidad de manzanas de la cesta final como la que se entrega.","Se ceden cuatro manzanas por una pera adicional. La RMS media es cuatro manzanas por pera.","Una cuarta parte de manzana por pera, al dividir la pera obtenida entre las cuatro manzanas cedidas."]},{"id":"2.10-c4","type":"comprension","prompt":"¿Por qué se antepone un signo menos al cociente ΔY/ΔX?","options":["Porque ΔX es negativa al pasar de una pera a dos y la cantidad de manzanas aumenta en esa dirección.","Para convertir el cociente en el precio monetario de las manzanas sin conocer los precios de mercado.","Porque ΔY es negativa al aumentar X sobre la curva descendente. El signo permite expresar como positiva la cantidad que se cede."]},{"id":"2.10-c5","type":"comprension","prompt":"¿Qué expresa una RMS inferior a uno en estos ejes?","options":["Que la pera tiene necesariamente un precio de mercado inferior a un euro, con independencia del precio de las manzanas.","Que se cede más de una manzana para recibir una pera adicional conservando la misma satisfacción.","Que por una pera adicional el consumidor está dispuesto a renunciar a menos de una manzana, manteniendo la utilidad."]},{"id":"2.10-d","type":"desarrollo","prompt":"Interpreta la forma de la curva de indiferencia de peras y manzanas en términos de escasez relativa y disposición a sustituir."}],"figure":{"src":"assets/figuras/2.10.svg","alt":"Dos cestas sobre una curva de indiferencia Manzanas (unidades) 1 2 3 4 4 8 12 A B A 1 pera y 12 manzanas B 2 peras y 8 manzanas El tramo A–B cambia una pera adicional por cuatro manzanas, a igual utilidad. Peras (unidades) Los puntos A y B proceden del curso. La línea ilustra la forma de la curva entre cestas."}},{"id":"2.12","title":"Ejercicio 1: Utilidad marginal","note":"Sin contenido en los archivos adjuntos."}]},{"number":3,"title":"Oferta y demanda","items":[{"id":"3.0","title":"Introducción","note":"La introducción (p. 35) enumera los temas de la sesión, que se desarrollan en los apartados siguientes."},{"id":"3.1","title":"La curva de la demanda","ideas":["La demanda relaciona cada precio posible con la cantidad que los compradores planean adquirir durante un periodo, dadas las demás condiciones. Vincula las unidades deseadas con el sacrificio monetario necesario y refleja las preferencias y el beneficio de las unidades marginales. La cantidad demandada es el plan correspondiente a un precio concreto.","La tabla reúne pares precio-cantidad. En el ejemplo del agua, a 0,04 por litro se demandan 40 millones de litros diarios y a 0,01 se demandan 160 millones. En el gráfico, la cantidad va en el eje horizontal y el precio en el vertical. Si el precio sube de 0,02 a 0,06, los consumidores economizan agua, empezando por los usos menos valorados."],"source":"35–36","page":25,"questions":[{"id":"3.1-c1","type":"comprension","prompt":"¿Qué diferencia hay entre demanda y cantidad demandada?","options":["La demanda es la relación completa entre precios y cantidades previstas. La cantidad demandada es lo que se planea adquirir a un precio determinado.","La demanda es solo la cifra vendida ayer y la cantidad demandada es toda la relación entre precios y cantidades.","La demanda es el total que guardan los productores y la cantidad demandada es la parte de esas existencias que ponen a la venta."]},{"id":"3.1-c2","type":"comprension","prompt":"¿Qué dos puntos de la tabla de agua proporciona el curso?","options":["A 0,04 por litro se demandan 40 millones de litros al mes y a 0,01 se demandan 160 millones al mes.","A 0,04 por litro, 40 millones de litros diarios. A 0,01, 160 millones de litros diarios.","A 0,04 por litro se demandan 160 millones de litros diarios y a 0,01 se demandan 40 millones."]},{"id":"3.1-c3","type":"comprension","prompt":"¿Cómo se ubica en el gráfico el punto del precio 0,04?","options":["En el eje horizontal se toma 40 millones de litros diarios y en el vertical se marca 0,04 por litro.","Se marca 0,04 en el eje horizontal y 40 millones de litros diarios en el vertical.","Se toma 160 millones de litros diarios en el eje horizontal y 0,04 por litro en el vertical."]},{"id":"3.1-c4","type":"comprension","prompt":"¿Por qué se especifica un periodo en la demanda de agua?","options":["Porque un flujo de litros por día representa un plan distinto del mismo número de litros por mes o por año.","Porque la demanda siempre se expresa por días y utilizar un mes haría imposible estudiar el consumo.","Porque la cantidad de agua es una existencia instantánea cuyo significado no depende de la duración del periodo."]},{"id":"3.1-c5","type":"comprension","prompt":"¿Qué usos tendería a reducir primero el consumidor si el agua se encarece?","options":["Los usos esenciales para la supervivencia, porque el consumidor elimina primero los fines que más valora.","Los usos marginales que menos valora y para los que el beneficio esperado ya no compensa el nuevo precio.","Los usos adquiridos en primer lugar, siguiendo el orden cronológico, aunque resulten más valiosos que los demás."]},{"id":"3.1-d","type":"desarrollo","prompt":"Explica qué datos contiene la curva de demanda de agua y cómo leerla al evaluar un cambio del precio por litro."}]},{"id":"3.2","title":"El excedente del consumidor","ideas":["El excedente del consumidor de una unidad es la diferencia entre su disposición máxima a pagar y el precio realmente pagado. Excedente por unidad = disposición a pagar − precio. Es una medida monetaria indirecta de la ganancia del comprador. La valoración máxima puede variar entre personas y entre unidades del mismo comprador.","Si alguien pagaría hasta 10 euros por una unidad de carne y la compra por 4, el excedente es 6 euros. Para varias unidades se suman las diferencias correspondientes a las unidades adquiridas. La suma para todos los compradores da el excedente agregado."],"source":"36","page":26,"questions":[{"id":"3.2-c1","type":"comprension","prompt":"¿Qué representa el importe máximo dispuesto a pagar?","options":["La valoración monetaria límite de esa unidad para el consumidor en esas circunstancias.","El precio al que se pagaron necesariamente todas las unidades anteriores.","El importe mínimo que el vendedor debe cobrar para aceptar vender esa unidad."]},{"id":"3.2-c2","type":"comprension","prompt":"¿Cuánto excedente genera una unidad valorada en 10 euros que cuesta 4?","options":["Seis euros, al restar el precio de la disposición máxima a pagar.","Catorce euros, sumando la valoración de diez euros al precio de cuatro.","Cuatro euros, porque todo el excedente del comprador coincide con lo desembolsado."]},{"id":"3.2-c3","type":"comprension","prompt":"Si quien pagaría 10 euros entrega exactamente 10, ¿cuál es su excedente monetario?","options":["Veinte euros, al sumar los diez euros de valoración a los diez entregados.","Cero euros para esa unidad. El precio coincide con su valoración límite.","Diez euros, porque esa es su valoración total de la unidad."]},{"id":"3.2-c4","type":"comprension","prompt":"¿Por qué el mismo precio puede generar excedentes diferentes?","options":["Porque el excedente depende del coste del productor y no de lo que cada comprador estaría dispuesto a pagar.","A igualdad de precio es imposible obtener excedentes diferentes, incluso si las valoraciones máximas difieren.","Porque los compradores pueden estar dispuestos a pagar máximos distintos por la misma unidad."]},{"id":"3.2-c5","type":"comprension","prompt":"¿Cómo se obtiene el excedente del consumidor agregado?","options":["Sumando todo el dinero gastado por los consumidores sin descontar los precios pagados de sus valoraciones.","Multiplicando el excedente de la última unidad por todas las ventas aunque las valoraciones de las unidades sean distintas.","Se suman los excedentes de las unidades adquiridas por cada consumidor y luego los de todos los consumidores del mercado."]},{"id":"3.2-d","type":"desarrollo","prompt":"Explica cómo se puede medir una ganancia para el comprador cuando en la caja solo se registra el importe pagado."}],"figure":{"src":"assets/figuras/3.2.svg","alt":"El excedente del consumidor Precio por unidad P Q Cantidad Área sombreada Por cada unidad comprada, la altura entre la demanda y el precio mide el ahorro respecto al máximo que el comprador habría pagado. Esquema del mercado. Ejemplo de clase para una unidad: valoración de 10 €, precio de 4 €, excedente de 6 €."}},{"id":"3.3","title":"La ley de demanda","ideas":["La ley de demanda describe una relación inversa, manteniendo constantes las demás circunstancias. Si sube el precio propio, se reduce la cantidad demandada. Si baja, aumenta. Las unidades marginales tienen usos menos prioritarios y por ello pueden abandonarse al encarecerse el bien.","En un gráfico con precio vertical y cantidad horizontal, una subida del precio propio lleva a otro punto de la misma curva, hacia arriba y a la izquierda. La condición ceteris paribus incluye gustos, renta, población, expectativas y precios relacionados. Un cambio en esas variables requiere un análisis distinto."],"source":"36–37","page":27,"questions":[{"id":"3.3-c1","type":"comprension","prompt":"¿Qué magnitud disminuye cuando sube el precio propio, según esta ley?","options":["La demanda a todos los precios, que se desplaza en bloque en vez de cambiar el punto elegido.","La oferta completa del productor, que debe desplazarse hacia la izquierda por la ley de demanda.","La cantidad demandada del bien en el periodo considerado."]},{"id":"3.3-c2","type":"comprension","prompt":"¿Qué significa la condición ceteris paribus?","options":["Que se mantienen fijos los demás determinantes al estudiar el efecto del precio propio.","Que todos los compradores poseen los mismos ingresos y preferencias entre sí.","Que el precio propio y los demás determinantes deben variar a la vez y en igual proporción."]},{"id":"3.3-c3","type":"comprension","prompt":"¿Cómo se recorre la curva cuando baja el precio?","options":["Hacia arriba y a la izquierda, hasta un precio menor con menos unidades demandadas.","Hacia abajo y a la derecha, hasta una cantidad demandada mayor.","La curva completa se desplaza hacia la derecha sin que se cambie el punto sobre ella."]},{"id":"3.3-c4","type":"comprension","prompt":"¿Por qué un encarecimiento elimina primero ciertos usos?","options":["Porque los usos con mayor beneficio marginal son los primeros que dejan de justificar pagar más.","Para los usos de menor valor marginal resulta menos probable que el beneficio compense el mayor sacrificio monetario.","Porque la subida obliga a suprimir la misma proporción de cada uso sin atender a su utilidad."]},{"id":"3.3-c5","type":"comprension","prompt":"¿Permiten dos observaciones con precio y población cambiantes medir directamente la ley?","options":["Sí, cualquier diferencia de cantidades entre ambos momentos se debe íntegramente al precio propio.","No bastan para aislar el efecto del precio, porque una población diferente puede cambiar la curva entera.","Sí, basta observar si la población sube o baja para conocer exactamente la variación debida al precio."]},{"id":"3.3-d","type":"desarrollo","prompt":"Corrige la frase «si el precio del agua sube, disminuye la demanda» y explica por qué la precisión importa."}]},{"id":"3.4","title":"¿Por qué cambia la curva de la demanda?","ideas":["Un cambio de demanda modifica la cantidad planeada al comparar el mismo precio propio. Más cantidad a cada precio desplaza la curva a la derecha y menos a la izquierda. Entre sus determinantes están el número de compradores, las preferencias, los ingresos, los precios de bienes relacionados y las expectativas sobre el precio futuro.","Una ciudad que gana población demandará más agua si los demás factores se mantienen. La moda puede reducir la demanda de sombreros. El efecto de una variación de renta depende del tipo de bien. Al encarecerse un sustituto como Coca-Cola, puede aumentar la demanda de Pepsi. Si se encarece un complemento, puede caer la demanda del bien que se usa con él. Esperar una subida del oro puede aumentar las compras presentes."],"source":"37–38","page":28,"questions":[{"id":"3.4-c1","type":"comprension","prompt":"¿Qué observación indica un desplazamiento a la derecha?","options":["Se compra una cantidad mayor solo porque el propio precio baja, manteniéndose la misma relación a cada precio.","Que a un mismo precio se planea adquirir una cantidad mayor que antes.","Al mismo precio se planea comprar menos unidades que antes."]},{"id":"3.4-c2","type":"comprension","prompt":"¿Qué diferencia hay entre el efecto de la población y el del precio propio en el agua?","options":["Los dos cambios recorren la misma curva sin modificar la cantidad prevista a un precio dado.","La población modifica la demanda a cada precio. Un cambio en el precio propio recorre la curva existente.","El precio propio desplaza toda la curva y la población cambia el punto elegido sobre la misma curva."]},{"id":"3.4-c3","type":"comprension","prompt":"¿Por qué puede disminuir la demanda de sombreros aunque permanezca su precio?","options":["Una bajada del precio propio reduce por sí sola la cantidad deseada al precio original.","Un cambio de moda puede reducir el número de personas interesadas en llevarlos.","Al mantenerse el precio, la demanda queda fijada y no puede cambiar aunque pasen de moda."]},{"id":"3.4-c4","type":"comprension","prompt":"¿Qué diferencia hay entre sustitutos y complementos ante un encarecimiento?","options":["El encarecimiento de cualquiera de los dos solo modifica la oferta del bien y deja intacta su demanda.","Al subir el precio de un sustituto puede aumentar la demanda del bien analizado. Al subir el precio de un complemento suele disminuir la demanda del bien usado conjuntamente.","Al encarecerse un sustituto cae la demanda del bien y al encarecerse un complemento aumenta."]},{"id":"3.4-c5","type":"comprension","prompt":"¿Cómo puede un anuncio sobre el oro modificar su demanda hoy?","options":["Las expectativas de un precio futuro carecen de efecto sobre la demanda hasta que cambie efectivamente el precio de hoy.","Si esperan una subida, pospondrán necesariamente toda compra hasta tener que pagar el precio superior.","Si los compradores esperan que se encarezca más adelante, pueden adelantar compras al precio actual."]},{"id":"3.4-d","type":"desarrollo","prompt":"Explica cómo aislarías un cambio de demanda al analizar el mercado de refrescos y aplica el criterio a un sustituto."}],"figure":{"src":"assets/figuras/3.4.svg","alt":"Desplazamiento de la demanda y nuevo equilibrio Precio Cantidad D O E₀ E₁ De E₀ a E₁ Al mismo precio hay más compradores o desean comprar más. La curva D se desplaza a la derecha (trazo discontinuo). Aumentan el precio y la cantidad de equilibrio. Esquema · D: demanda · O: oferta"}},{"id":"3.4.1","title":"Foro 6: Demanda","note":"Sin contenido en los archivos adjuntos."},{"id":"3.4.2","title":"Respuesta al foro: Demanda","note":"Sin contenido en los archivos adjuntos."},{"id":"3.5","title":"La curva de la oferta","ideas":["La oferta asocia cada precio con la cantidad que los vendedores están dispuestos a llevar al mercado en un periodo. Producir otra unidad exige cubrir su coste marginal, incluido el valor de emplear los recursos en alternativas. Los costes de oportunidad son de quien decide, se refieren a la elección marginal y a opciones que aún puede tomar.","Una recesión puede reducir el salario al que se renuncia al hacer un posgrado. También puede ser menor el coste de ingresar en el ejército en una región de renta baja que para quien tiene acceso a un empleo financiero bien remunerado. La misma lógica de comparar usos alternativos se aplica al productor.","Se representa precio en vertical y cantidad en horizontal. Con maíz a 1,20 €/kg se ofrecen 3 kg y a 1,60 €/kg, 7 kg. En La Gomera se ofrecen 12 conos de helado a 0,50 € y 36 a 1,50 €. La oferta de mercado suma horizontalmente las ofertas individuales al mismo precio. A 1,50 €, David ofrece 15 y Ana 21."],"source":"38–40","page":29,"questions":[{"id":"3.5-c1","type":"comprension","prompt":"¿Qué información contiene la tabla de oferta?","options":["Las cantidades que se planea vender en el periodo a cada posible precio, dadas las demás circunstancias.","Las cantidades que los compradores desean consumir a cada nivel de renta.","Los costes fijos contables pagados en el ejercicio, sin información sobre precios ni cantidades previstas."]},{"id":"3.5-c2","type":"comprension","prompt":"¿Qué indica el coste marginal al decidir si producir una unidad adicional?","options":["El valor medio que los compradores atribuyen al conjunto de unidades ya vendidas.","El sacrificio de recursos y usos alternativos que esa unidad exige cubrir.","La suma de todos los costes históricos en que se incurrió antes de considerar esa unidad."]},{"id":"3.5-c3","type":"comprension","prompt":"¿Por qué podría aumentar el atractivo de estudiar durante una recesión?","options":["Porque una reducción de salarios aumenta el sueldo al que se renuncia por estudiar en lugar de trabajar.","Una menor disponibilidad de empleo o salarios inferiores reducen el valor de la alternativa laboral sacrificada.","Porque en recesión desaparece todo coste de oportunidad del tiempo para cualquier persona que estudie."]},{"id":"3.5-c4","type":"comprension","prompt":"¿Cuál es la cantidad ofrecida de mercado a 1,50 € por cono?","options":["Dieciocho conos, el promedio entre las ofertas de David y Ana.","Seis conos, la diferencia entre los que desea vender Ana y los que desea vender David.","Treinta y seis conos, la suma de los 15 de David y los 21 de Ana a ese precio."]},{"id":"3.5-c5","type":"comprension","prompt":"¿Cómo se usan los ejes para representar los datos del maíz?","options":["Los precios de 1,20 y 1,60 €/kg se sitúan en horizontal y los 3 y 7 kg en vertical.","Se sitúan las cantidades en horizontal, asociando 3 kg a 1,60 €/kg y 7 kg a 1,20 €/kg.","Se marcan las cantidades de 3 y 7 kg en horizontal y sus respectivos precios de 1,20 y 1,60 €/kg en vertical."]},{"id":"3.5-d","type":"desarrollo","prompt":"Explica cómo se pasa de la decisión marginal de cada vendedor a la curva de oferta de un mercado usando el ejemplo del helado."}]},{"id":"3.6","title":"El excedente del productor","ideas":["El excedente del productor de una unidad compara el precio que obtiene con el mínimo que estaba dispuesto a aceptar por venderla. Excedente por unidad = precio recibido − precio mínimo aceptable. El mínimo refleja el sacrificio marginal de ofrecer la unidad. Es una medida indirecta en dinero de la ganancia del vendedor.","En el ejemplo de la carne, alguien dispuesto a vender por 1 € recibe 4 € y obtiene 3 € de excedente. El ingreso bruto de la transacción es 4 €. Para hallar el excedente agregado se suman las diferencias correspondientes a todas las unidades vendidas por todos los productores."],"source":"40–41","page":30,"questions":[{"id":"3.6-c1","type":"comprension","prompt":"¿Qué términos compara el excedente del productor?","options":["La disposición máxima a pagar del consumidor menos el precio efectivamente desembolsado.","El precio mínimo aceptable menos el precio recibido, de modo que vender por encima del mínimo daría excedente negativo.","El precio efectivamente recibido y el precio mínimo aceptable para la unidad, restando el segundo del primero."]},{"id":"3.6-c2","type":"comprension","prompt":"¿Qué excedente obtiene quien acepta desde 1 € y vende por 4 €?","options":["Cinco euros de excedente, tras añadir el precio mínimo al cobro.","Tres euros de excedente por la unidad vendida.","Cuatro euros de excedente, porque se cuenta todo el ingreso de la venta."]},{"id":"3.6-c3","type":"comprension","prompt":"¿Qué distingue el ingreso bruto de la ganancia aquí medida?","options":["El ingreso bruto es todo el pago recibido. El excedente descuenta el mínimo que hacía aceptable vender la unidad.","La ganancia medida y el ingreso bruto siempre coinciden, también cuando el vendedor exige una compensación mínima positiva.","El ingreso bruto descuenta el mínimo aceptable, mientras que el excedente equivale a la totalidad del pago."]},{"id":"3.6-c4","type":"comprension","prompt":"Si dos vendedores cobran lo mismo, ¿cuándo obtiene más excedente uno de ellos?","options":["Siempre obtienen idéntico excedente por unidad porque han cobrado el mismo precio, sin importar sus mínimos.","Cuando su mínimo aceptable es mayor y por tanto queda más cerca del precio de venta.","Cuando su mínimo aceptable para la unidad vendida es menor."]},{"id":"3.6-c5","type":"comprension","prompt":"¿Cómo se calcula la medida agregada para un mercado?","options":["Sumando los ingresos íntegros de las ventas y omitiendo los mínimos aceptables.","Sumando los excedentes de cada unidad vendida por todos los productores al precio que efectivamente reciben.","Restando al ingreso total un único mínimo, el del último vendedor, aunque hayan vendido unidades muchos productores."]},{"id":"3.6-d","type":"desarrollo","prompt":"Compara los excedentes del vendedor y del comprador de una unidad de carne y explica de dónde sale la ganancia conjunta."}],"figure":{"src":"assets/figuras/3.6.svg","alt":"El excedente del productor Precio por unidad P Q Cantidad Área sombreada Por cada unidad vendida, la altura entre el precio y la oferta mide el margen sobre el mínimo que el vendedor habría aceptado. Esquema del mercado. Ejemplo de clase para una unidad: precio de 4 €, mínimo de 1 €, excedente de 3 €."}},{"id":"3.7","title":"La ley de oferta del mercado","ideas":["La ley de oferta describe una relación positiva entre precio propio y cantidad ofrecida, constantes los restantes determinantes. Una subida permite cubrir los costes marginales de más unidades, mientras que una bajada puede hacer que algunas dejen de compensar.","Con el precio en el eje vertical, el encarecimiento lleva hacia arriba y a la derecha por la misma curva. El abaratamiento lleva hacia abajo y a la izquierda. La predicción se refiere al plan de venta a ese precio. Cambios simultáneos en costes, técnicas o número de vendedores pueden alterar la oferta entera."],"source":"41","page":31,"questions":[{"id":"3.7-c1","type":"comprension","prompt":"¿Qué cambia si aumenta el precio propio manteniendo todo lo demás constante?","options":["Disminuye la cantidad ofrecida del bien, siguiendo la pendiente negativa de la curva de demanda.","La oferta se desplaza en bloque a la derecha porque cambia el precio propio, aunque los costes no varíen.","Aumenta la cantidad ofrecida del bien."]},{"id":"3.7-c2","type":"comprension","prompt":"¿Qué sucede al bajar el precio en las mismas condiciones?","options":["Disminuye la cantidad que los productores planean vender.","La oferta entera se desplaza a la izquierda sin producirse un movimiento sobre la curva.","Aumenta la cantidad que se desea vender porque los compradores pueden adquirir más al nuevo precio."]},{"id":"3.7-c3","type":"comprension","prompt":"¿Cómo se representa una subida del precio propio en el gráfico?","options":["Como un desplazamiento paralelo de toda la curva de oferta manteniendo fija la cantidad ofrecida al precio original.","Como un desplazamiento del punto elegido hacia arriba y a la derecha sobre la misma curva.","Como un movimiento hacia arriba y a la izquierda sobre la curva de demanda del consumidor."]},{"id":"3.7-c4","type":"comprension","prompt":"¿Por qué puede compensar producir más cuando el precio sube?","options":["Porque un precio mayor garantiza que cualquier cantidad adicional será rentable, cualquiera que sea su coste marginal.","Porque elevar el precio de venta reduce por definición el coste tecnológico de fabricar la siguiente unidad.","Un precio mayor puede cubrir el coste marginal de unidades que resultaban poco atractivas al precio anterior."]},{"id":"3.7-c5","type":"comprension","prompt":"¿Describe la ley por sí sola el efecto de una subida de precio acompañada de un impuesto nuevo por unidad?","options":["Sí, la cantidad ofrecida siempre aumenta al subir el precio bruto, aunque el impuesto reduzca más el precio neto.","Sí, el importe ingresado en Hacienda nunca altera lo que el vendedor conserva por unidad.","No. El impuesto modifica los costes o el precio neto a cada precio de venta y puede alterar la curva de oferta."]},{"id":"3.7-d","type":"desarrollo","prompt":"Utiliza la oferta de maíz para explicar el sentido de la ley y la condición que permite interpretarla correctamente."}]},{"id":"3.8","title":"¿Por qué cambia la curva de la oferta?","ideas":["La curva se desplaza si al mismo precio propio los productores ofrecen una cantidad distinta. Un mayor número de oferentes, menores precios de los factores, mejoras técnicas o un subsidio a la producción tienden a aumentarla. Factores más caros e impuestos por unidad tienden a reducirla. La clase incluye el grado de competencia y los precios relativos de productos alternativos, cuyo efecto depende de la relación productiva.","Las expectativas pueden cambiar el momento de la venta. Si se espera un precio mayor dentro de seis meses y el bien puede almacenarse, el productor puede retener existencias hoy. En el gráfico, cuando cae la cantidad ofrecida al comparar el mismo precio, la curva se desplaza a la izquierda. Un aumento se representa a la derecha."],"source":"42","page":32,"questions":[{"id":"3.8-c1","type":"comprension","prompt":"¿Qué pasa con la oferta de mercado si entran nuevos vendedores con oferta positiva?","options":["Aumenta la cantidad ofrecida al mismo precio, dando lugar a un desplazamiento de la oferta hacia la derecha.","Solo se recorre la oferta original hasta un precio mayor, sin cambiar la cantidad agregada al mismo precio.","La curva agregada se desplaza hacia la izquierda porque cada vendedor tiene más competidores."]},{"id":"3.8-c2","type":"comprension","prompt":"¿Cómo incide el encarecimiento de un factor de producción?","options":["Desplaza exclusivamente la demanda del bien final, sin cambiar el coste que afrontan los productores.","Eleva los costes. Algunas unidades dejan de compensar al precio anterior y la oferta puede desplazarse a la izquierda.","Reduce los costes marginales de producción y aumenta la oferta a cada precio."]},{"id":"3.8-c3","type":"comprension","prompt":"¿Qué efectos opuestos suelen tener un impuesto y un subsidio por unidad producida?","options":["El primero reduce el incentivo neto a ofrecer al precio dado. El segundo lo eleva y puede aumentar la cantidad ofrecida a ese mismo precio.","El impuesto aumenta el incentivo neto y el subsidio lo reduce para una misma unidad vendida.","Ambos elevan el precio neto que recibe el productor por cada unidad si el comprador paga lo mismo."]},{"id":"3.8-c4","type":"comprension","prompt":"¿Por qué una expectativa de precios mayores puede reducir las ventas ofrecidas hoy?","options":["Porque esperar un precio mayor equivale a recibir un pago hoy por cada unidad vendida al precio actual.","Porque una expectativa futura reduce inmediatamente la cantidad física ya disponible para la venta.","Si almacenar es viable, se pueden reservar unidades para venderlas más adelante al precio esperado."]},{"id":"3.8-c5","type":"comprension","prompt":"¿Cómo puede influir el precio de otro producto en la oferta del primero?","options":["Los precios de otros productos solo pueden modificar la demanda y nunca la asignación de recursos por parte del productor.","Puede cambiar la rentabilidad relativa de los usos de los recursos. Si ambos compiten por el mismo insumo, hacerlo más rentable en el otro producto puede reducir la oferta del primero.","Si el otro producto compite por el mismo insumo, hacer más rentable ese otro uso libera automáticamente insumos para el primero."]},{"id":"3.8-d","type":"desarrollo","prompt":"Distingue un cambio de oferta de una respuesta al precio propio considerando un avance técnico y una expectativa de encarecimiento futuro."}],"figure":{"src":"assets/figuras/3.8.svg","alt":"Desplazamiento de la oferta y nuevo equilibrio Precio Cantidad D O E₀ E₁ De E₀ a E₁ Al mismo precio se ofrecen más unidades. La curva O se desplaza a la derecha (trazo discontinuo). La cantidad de equilibrio aumenta y el precio disminuye. Esquema · D: demanda · O: oferta"}},{"id":"3.8.1","title":"Foro 7: Oferta","note":"Sin contenido en los archivos adjuntos."},{"id":"3.8.2","title":"Respuesta al foro: Oferta","note":"Sin contenido en los archivos adjuntos."},{"id":"3.9","title":"Cine: Oferta y demanda a través de la especulación en The Office","note":"Sin contenido en los archivos adjuntos."}]},{"number":4,"title":"La formación de los precios","items":[{"id":"4.0","title":"Introducción","note":"La presentación (p. 43) anuncia las preguntas sobre intercambio y formación de precios. Los conceptos se desarrollan desde 4.1."},{"id":"4.1","title":"¿Por qué se producen intercambios?","ideas":["Una persona intercambia cuando, antes de actuar, valora más lo que espera obtener que aquello a lo que renuncia. La regla se aplica al que entrega dinero y al que entrega un bien. Si tiene varias opciones disponibles, prefiere la que le proporciona mayor ventaja según sus fines.","El ejemplo de las vacaciones mantiene el desembolso constante para aislar la preferencia por el destino. Una misma playa o vivienda puede ocupar lugares distintos en las preferencias de dos personas. El acuerdo revela compatibilidad entre sus decisiones, aunque sus valoraciones sean diferentes."],"source":"43–44","page":33,"questions":[{"id":"4.1-c1","type":"comprension","prompt":"¿Por qué acepta el comprador entregar dinero por pan?","options":["Porque el valor del pan coincide exactamente con el valor de todos sus otros usos del dinero.","Prefiere el pan al siguiente uso que habría dado a ese dinero en ese momento.","Porque el comprador siempre prefiere conservar el dinero a recibir la unidad de pan."]},{"id":"4.1-c2","type":"comprension","prompt":"¿Qué gana quien vende el pan?","options":["Obtiene una suma cuyo uso valora más que conservar esa unidad de pan.","Gana la utilidad que el comprador asigna al pan, sin importar lo que pueda hacer con el dinero.","Gana únicamente si conservar el pan le parecía preferible a recibir el pago."]},{"id":"4.1-c3","type":"comprension","prompt":"¿En qué momento se evalúa la ventaja?","options":["Al elegir, según las expectativas y alternativas disponibles en ese momento.","Se evalúa exclusivamente después de consumir el bien, cuando ya se conoce el resultado.","Se evalúa cuando se fijó el coste histórico de producción, con independencia del momento de elegir."]},{"id":"4.1-c4","type":"comprension","prompt":"¿Qué ilustra elegir entre dos playas al mismo precio?","options":["Que solo existe una elección económicamente razonable entre destinos que cuestan lo mismo.","Que la ventaja depende del fin personal que mejor satisface cada destino.","Que destinos con el mismo precio satisfacen necesariamente por igual a cada persona."]},{"id":"4.1-c5","type":"comprension","prompt":"¿Basta saber el coste monetario de dos vacaciones para anticipar la elección?","options":["También se necesita conocer cómo ordena esa persona las alternativas.","Sí, basta ordenar ambas por su precio y elegir siempre la más barata.","Sí, porque dos opciones con igual precio tienen siempre el mismo valor subjetivo."]},{"id":"4.1-d","type":"desarrollo","prompt":"Explica por qué un intercambio voluntario puede beneficiar a dos personas con preferencias diferentes."}]},{"id":"4.2","title":"¿Qué es un precio?","ideas":["El precio expresa la relación efectiva a la que se intercambian dos bienes, habitualmente como dinero por unidad. Puede observarse en el trato. El valor es subjetivo y depende de la utilidad marginal que atribuye cada persona al bien y de su escasez en relación con los usos posibles.","Los máximos que aceptan pagar los compradores y los mínimos que aceptan recibir los vendedores delimitan los precios posibles. El profesor analiza cuatro configuraciones según el número de participantes en cada lado del mercado."],"source":"44","page":34,"questions":[{"id":"4.2-c1","type":"comprension","prompt":"¿Qué expresa un precio en euros por kilo?","options":["La cantidad de dinero intercambiada por cada kilo del bien.","El excedente total que obtiene el productor por todos los kilos vendidos.","La cantidad de kilos que pueden obtenerse entregando un solo euro."]},{"id":"4.2-c2","type":"comprension","prompt":"¿Qué valoración limita la puja de un comprador?","options":["La menor suma a la que el vendedor aceptaría desprenderse del bien, aunque supere la valoración del comprador.","La máxima suma que está dispuesto a entregar dadas sus alternativas.","El importe promedio que pagaron compradores anteriores, independientemente de sus propias opciones."]},{"id":"4.2-c3","type":"comprension","prompt":"¿Qué valoración limita la oferta de un vendedor?","options":["La mínima suma por la que acepta desprenderse de la unidad.","La mayor suma que cualquier comprador esté dispuesto a pagar.","El precio máximo permitido por la valoración del vendedor, por encima del cual se negaría a vender."]},{"id":"4.2-c4","type":"comprension","prompt":"¿De qué depende en último término la valoración de un bien de consumo?","options":["Únicamente del trabajo que se invirtió en producirlo, con independencia de las preferencias.","Del coste medio contable en la fábrica, aunque cambien los fines y la disponibilidad del bien.","De la utilidad marginal subjetiva y de la escasez relativa."]},{"id":"4.2-c5","type":"comprension","prompt":"¿Qué cuatro configuraciones distingue la clase?","options":["Mercado de productos, mercado de trabajo, mercado financiero y mercado exterior.","Intercambio aislado, competencia entre compradores, competencia entre vendedores y competencia bilateral.","Subasta ascendente, subasta descendente, precio fijo y venta a plazos."]},{"id":"4.2-d","type":"desarrollo","prompt":"Relaciona precio, utilidad marginal y escasez sin confundir el precio observado con las valoraciones de las partes."}]},{"id":"4.3","title":"La formación de los precios en un intercambio aislado","ideas":["En el intercambio aislado hay un comprador y un vendedor. Si el comprador ofrece como máximo B y el vendedor exige como mínimo V, pueden acordar un precio P con V ≤ P ≤ B. Si B < V no existe un precio mutuamente aceptable. En los extremos una parte queda indiferente según la valoración indicada.","La vivienda del curso tiene V = 180.000 € y B = 300.000 €. Tanto 182.000 como 298.000 € caben en el intervalo. La habilidad negociadora influye en el reparto del margen y los dos límites, por sí solos, no seleccionan una cifra."],"source":"44–45","page":35,"questions":[{"id":"4.3-c1","type":"comprension","prompt":"¿Qué condición sobre B y V hace posible un acuerdo?","options":["El mínimo del vendedor debe superar el máximo del comprador.","El máximo del comprador y el mínimo del vendedor deben coincidir exactamente para que haya acuerdo.","El máximo del comprador debe alcanzar al menos el mínimo del vendedor."]},{"id":"4.3-c2","type":"comprension","prompt":"¿Por qué se rechazaría un precio de 170.000 € en el ejemplo?","options":["Queda por debajo de la reserva del vendedor de 180.000 €.","Porque cualquier oferta inferior a 300.000 € supera el presupuesto del comprador.","Porque supera el máximo que el comprador asigna a la vivienda."]},{"id":"4.3-c3","type":"comprension","prompt":"¿Por qué no se pagarán 305.000 €?","options":["Porque la reserva de 180.000 € del vendedor le impide aceptar un precio superior a esa cifra.","Porque 305.000 € dejan un excedente negativo al vendedor con reserva de 180.000 €.","El comprador valora más los usos alternativos del dinero por encima de 300.000 €."]},{"id":"4.3-c4","type":"comprension","prompt":"¿Cómo se repartiría el margen a un precio de 220.000 €?","options":["El comprador retiene 80.000 € respecto a su máximo y el vendedor obtiene 40.000 € sobre su mínimo.","40.000 € de ventaja para el comprador y 80.000 € para el vendedor.","60.000 € para cada parte, ya que todo precio dentro del intervalo divide la ganancia por igual."]},{"id":"4.3-c5","type":"comprension","prompt":"¿Qué informa un cambio de precio dentro del intervalo si se mantienen ambas reservas?","options":["Que aumenta la ventaja conjunta en la misma cuantía en que sube el precio.","Que se modifican necesariamente las valoraciones de reserva de los dos participantes.","Que cambia el reparto de la ventaja del acuerdo sin alterar el margen conjunto de 120.000 €."]},{"id":"4.3-d","type":"desarrollo","prompt":"Analiza la negociación aislada de una casa y explica qué puede deducirse antes de conocer el precio final."}]},{"id":"4.3.1","title":"Cine: Just Go with It","note":"Sin contenido en los archivos adjuntos."},{"id":"4.4","title":"La formación de los precios con una competencia unilateral de compradores","ideas":["Un vendedor ofrece una vivienda con reserva de 180.000 €. Seis candidatos pueden pagar hasta 380.000, 300.000, 280.000, 240.000, 200.000 y 190.000 €. Con una sola unidad disponible, las pujas crecen mientras varios compradores sigan interesados. A 195.000 € quedan cinco y a 285.000 € quedan dos.","El candidato con mayor máximo puede superar al segundo. En este caso, para ganar en solitario ofrece más de 300.000 € y no más de 380.000 €. En general también hay que respetar el mínimo del vendedor. Si se iguala la segunda puja máxima, el resultado depende del desempate."],"source":"45","page":36,"questions":[{"id":"4.4-c1","type":"comprension","prompt":"¿De qué lado compiten los agentes?","options":["Del lado vendedor, porque varias viviendas se disputan un único comprador.","Del lado comprador, por la única vivienda de un vendedor.","De ambos lados, pues hay varios vendedores y varios compradores activos."]},{"id":"4.4-c2","type":"comprension","prompt":"¿Cuántos interesados quedan a 195.000 €?","options":["Cinco, pues únicamente queda excluido el que admite hasta 190.000 €.","Cuatro, porque se excluyen dos candidatos a ese precio.","Seis, porque la reserva mínima de 190.000 € no excluye a ningún comprador."]},{"id":"4.4-c3","type":"comprension","prompt":"¿Quiénes siguen a 285.000 €?","options":["También sigue el candidato cuyo tope es inferior a 285.000 €, además de los dos de mayor valoración.","Solo el candidato que admite hasta 380.000 €.","Quienes admiten hasta 300.000 y 380.000 €."]},{"id":"4.4-c4","type":"comprension","prompt":"¿Por qué 300.001 € puede ganar la subasta del ejemplo?","options":["Porque coincide con el precio mínimo del vendedor y todos los compradores pueden igualarlo.","Supera la capacidad del segundo comprador y respeta tanto la reserva del vendedor como el máximo del primero.","Porque iguala exactamente la valoración del comprador que ofrece hasta 380.000 €."]},{"id":"4.4-c5","type":"comprension","prompt":"¿Qué pasaría si el vendedor exigiese 390.000 €?","options":["Ninguna puja compatible con las valoraciones de los seis candidatos podría cerrar el trato.","El vendedor estaría obligado a cerrar la venta a 380.000 € pese a exigir 390.000 €.","El candidato de mayor valoración compraría a 390.000 €, ya que la última puja determina su valoración."]},{"id":"4.4-d","type":"desarrollo","prompt":"Explica por qué un comprador que pagaría 380.000 € puede adquirir la casa por mucho menos y qué determina hasta dónde puede bajar."}]},{"id":"4.4.1","title":"Ejercicio 2: Competencia unilateral de compradores","note":"Sin contenido en los archivos adjuntos."},{"id":"4.5","title":"La formación de los precios con una competencia unilateral de vendedores","ideas":["Un comprador acepta pagar hasta 400 €/kg por chocolate. Seis proveedores admiten como mínimos 380, 300, 280, 240, 200 y 190 €/kg. A 280 aún pueden vender cuatro de ellos, a 240 quedan tres. Como el comprador solo precisa una oferta, los proveedores tienen incentivo para rebajar sus pretensiones.","El vendedor con reserva de 190 puede ofrecer menos de 200 y seguir cubriendo su mínimo. El precio compatible con la venta en solitario está entre 190 inclusive y 200 exclusivo, respetando el máximo del comprador. En el límite superior empataría con otro vendedor."],"source":"46","page":37,"questions":[{"id":"4.5-c1","type":"comprension","prompt":"¿Cuál es la reserva del comprador del chocolate?","options":["190 euros por kilo.","280 euros por kilo.","400 euros por kilo."]},{"id":"4.5-c2","type":"comprension","prompt":"¿Cuántos proveedores pueden aceptar 280 €/kg?","options":["Cuatro, con reservas de 280, 240, 200 y 190 €/kg.","Dos, únicamente los que exigen más de 280 €/kg.","Cinco, contando también a un proveedor cuyo mínimo supera 280 €/kg."]},{"id":"4.5-c3","type":"comprension","prompt":"¿Por qué bajan las ofertas mientras hay varios proveedores?","options":["Cada proveedor busca pagar un precio menor por el chocolate que compra al cliente.","El precio baja porque varios compradores compiten entre sí por un único proveedor.","Cada uno intenta atraer al único comprador ofreciendo mejores condiciones."]},{"id":"4.5-c4","type":"comprension","prompt":"¿Qué proveedor puede aceptar 195 €/kg?","options":["Todos los proveedores con reserva superior a 195 €/kg.","Solo el de reserva de 190 €/kg.","El de reserva de 200 €/kg, porque recibiría 5 € menos que su mínimo."]},{"id":"4.5-c5","type":"comprension","prompt":"¿Qué papel desempeña el proveedor de reserva de 200 €/kg?","options":["Es el único proveedor capaz de vender por menos de 200 €/kg.","Es el competidor excluido más próximo y limita por arriba la oferta ganadora.","Fija por abajo el precio ganador en 200 €/kg y excluye ofertas inferiores."]},{"id":"4.5-d","type":"desarrollo","prompt":"Compara una puja entre vendedores de chocolate con una subasta entre compradores de una vivienda."}]},{"id":"4.6","title":"La formación de los precios en una competencia bilateral","ideas":["En competencia bilateral se ordenan los máximos compradores de mayor a menor y los mínimos vendedores de menor a mayor. Para cada P se cuentan los compradores cuyo máximo alcanza P y los vendedores cuyo mínimo no supera P. La última pareja que entra y los primeros excluidos delimitan el intervalo de coordinación. El techo es el menor del máximo del último comprador admitido y el mínimo del primer vendedor excluido. El suelo es el mayor del mínimo del último vendedor admitido y el máximo del primer comprador excluido.","Con ocho casas idénticas y diez compradores, a 125.000 € hay diez compradores frente a dos vendedores. A 175.000 hay ocho frente a cuatro, a 200.000 siete frente a cinco y a 270.000 dos frente a ocho. A 210.000 todavía hay seis frente a cinco. Entre 210.000 y 215.000, sin incluir estos extremos en el recuento de clase, coinciden cinco y cinco. A 215.000 entra un sexto vendedor."],"source":"47–49","page":38,"questions":[{"id":"4.6-c1","type":"comprension","prompt":"¿En qué orden se colocan las dos escalas de valoraciones?","options":["Ambas escalas de mayor a menor, empezando por el vendedor más caro.","Máximos compradores de menor a mayor y mínimos vendedores de mayor a menor.","Máximos compradores de mayor a menor y mínimos vendedores de menor a mayor."]},{"id":"4.6-c2","type":"comprension","prompt":"¿Por qué 200.000 € no coordina el ejemplo?","options":["Cinco compradores y cinco vendedores negocian, pero la igualdad de cantidades impide coordinar.","Siete compradores compiten por las cinco viviendas ofrecidas a ese importe.","Cinco compradores desean siete viviendas, de modo que sobran dos."]},{"id":"4.6-c3","type":"comprension","prompt":"¿Qué presión se produce a 270.000 €?","options":["Dos vendedores atienden a ocho compradores y empujan el precio al alza.","Ocho vendedores encuentran dos compradores, lo que favorece rebajas.","Ocho vendedores encuentran ocho compradores y desaparece toda presión sobre el precio."]},{"id":"4.6-c4","type":"comprension","prompt":"¿Qué ocurre al pasar de 214.000 a 215.000 €?","options":["Se pasa de cinco compradores y cinco vendedores a un vendedor adicional y exceso de oferta.","Entra un comprador adicional y se mantienen cinco vendedores.","Un vendedor abandona el mercado y quedan cuatro vendedores frente a cinco compradores."]},{"id":"4.6-c5","type":"comprension","prompt":"¿Por qué varios precios coordinan a los mismos participantes?","options":["Porque es obligatorio que todos los participantes tengan idéntico precio de reserva.","Porque cualquier precio, incluso por encima del máximo de todos los compradores, coordina la misma cantidad.","Dentro del intervalo ninguna valoración marginal cambia de lado al variar ligeramente el precio."]},{"id":"4.6-d","type":"desarrollo","prompt":"Reconstruye el intervalo de coordinación de las casas y explica por qué promediar las valoraciones no lo identifica."}],"figure":{"src":"assets/figuras/4.6.svg","alt":"El intervalo que coordina cinco compraventas Mercado de viviendas · precio por vivienda en miles de euros 209 210 211 212 213 214 215 216 5 compradores · 5 vendedores A 210.000 € hay 6 compradores y 5 vendedores. A 215.000 € entra el sexto vendedor. Los círculos abiertos excluyen los precios de los extremos. El intercambio admite varios precios."}},{"id":"4.6.1","title":"Cine: The Hudsucker Proxy (1994)","note":"Sin contenido en los archivos adjuntos."},{"id":"4.6.2","title":"Ejercicio 3: Competencia bilateral","note":"Sin contenido en los archivos adjuntos."},{"id":"4.7","title":"El proceso básico de coordinación: el equilibrio en un mercado competitivo","ideas":["El equilibrio competitivo identifica un precio o intervalo para el que cantidad demandada y cantidad ofrecida son iguales. Representar demanda y oferta juntas permite ver qué planes son compatibles. Con las demás condiciones constantes, un precio más alto reduce la cantidad demandada y aumenta la ofrecida.","Si se ofrece más de lo que se compra, existe un excedente físico y los vendedores tienen incentivo para reducir el precio. Si se quiere comprar más de lo que se ofrece, hay exceso de demanda y presión compradora al alza. El equilibrio describe una tendencia del proceso de ajuste."],"source":"49–50","page":39,"questions":[{"id":"4.7-c1","type":"comprension","prompt":"¿Qué igualdad caracteriza el equilibrio?","options":["El número de compradores es igual al de vendedores, cualquiera que sea la cantidad que intercambie cada uno.","El coste total de producción es igual a los ingresos totales de todas las empresas.","Cantidad demandada igual a cantidad ofrecida al mismo precio."]},{"id":"4.7-c2","type":"comprension","prompt":"¿Qué revela un excedente de unidades sin vender?","options":["Que al precio considerado la cantidad ofrecida supera a la demandada.","Que la cantidad demandada excede a la ofrecida al precio vigente.","Que el precio está necesariamente por debajo del de equilibrio."]},{"id":"4.7-c3","type":"comprension","prompt":"¿Por qué un exceso de demanda presiona el precio al alza?","options":["Porque hay unidades sobrantes que obligan a cada vendedor a pedir más por ellas.","Los compradores compiten por las unidades disponibles y pueden mejorar las ofertas.","Porque los productores compiten entre sí para reducir el precio del bien escaso."]},{"id":"4.7-c4","type":"comprension","prompt":"¿Cómo reacciona la cantidad ofrecida a una bajada de precio, todo lo demás constante?","options":["Se mantiene porque todo cambio de precio propio desplaza la curva sin afectar a la cantidad ofrecida.","Disminuye a lo largo de la curva de oferta.","Aumenta a lo largo de la misma curva de oferta creciente."]},{"id":"4.7-c5","type":"comprension","prompt":"¿Exige la coordinación un precio numérico único?","options":["Sí, el único precio compatible es siempre el punto medio entre el mayor máximo y el menor mínimo.","Sí, incluso con unidades indivisibles cualquier diferencia de un céntimo altera necesariamente el número de compradores y vendedores.","Con unidades discretas puede haber un intervalo que mantenga iguales ambas cantidades."]},{"id":"4.7-d","type":"desarrollo","prompt":"Describe cómo los planes de compradores y vendedores pueden aproximarse al equilibrio desde precios iniciales distintos."}],"figure":{"src":"assets/figuras/4.7.svg","alt":"Cómo se ajusta un precio fuera del equilibrio Precio Cantidad D O E Por encima de E Se ofrecen más unidades de las que se compran. Hay presión a la baja sobre el precio. Por debajo de E Los compradores desean más de lo que se ofrece. Hay presión al alza. Esquema · D: demanda · O: oferta"}},{"id":"4.8","title":"La ganancia del intercambio: un mercado libre maximiza la ganancia de los consumidores y productores","ideas":["El excedente del consumidor mide la diferencia entre su disposición a pagar y el precio pagado. El del productor mide la diferencia entre el precio recibido y el coste de oportunidad. En el mercado competitivo de la clase, la cantidad de equilibrio maximiza la suma de ambos. Los compradores y vendedores que quedarían fuera a ese precio no obtendrían ventaja al entrar.","En el ejemplo, a 20 € se coordinan 50 unidades. Para la unidad 25, la disposición a pagar es de 60 € y el coste es de 10 €. Impedirla sacrifica 50 € de ganancia conjunta. En la unidad 75 el coste es 60 € y la valoración solo 10 €; producirla destruye 50 € de excedente."],"source":"50–51","page":40,"questions":[{"id":"4.8-c1","type":"comprension","prompt":"¿Cómo se calcula el excedente individual del comprador?","options":["Multiplicando su disposición máxima a pagar por el precio de venta.","Restando el precio pagado a su disposición máxima a pagar.","Restando su disposición máxima a pagar al precio efectivamente pagado."]},{"id":"4.8-c2","type":"comprension","prompt":"¿Cómo se calcula el excedente individual del vendedor?","options":["Restando el precio pagado a la disposición máxima del comprador.","Restando el precio de venta a su coste de oportunidad.","Restando el coste de oportunidad de la unidad al precio que recibe."]},{"id":"4.8-c3","type":"comprension","prompt":"¿Cuánto gana el conjunto por la unidad 25?","options":["60 € de valoración menos 10 € de coste, es decir, 50 €.","10 €, porque la ganancia conjunta coincide con el coste de la unidad.","70 €, porque se suman los 60 € de valoración a los 10 € de coste."]},{"id":"4.8-c4","type":"comprension","prompt":"¿Por qué producir la unidad 75 desperdiciaría recursos?","options":["Porque el comprador le asigna 60 € y cuesta 10 € producirla.","Su coste de 60 € supera en 50 € la valoración de 10 € del comprador.","Porque su coste y su valoración son iguales a 50 € y toda igualdad supone desperdicio."]},{"id":"4.8-c5","type":"comprension","prompt":"¿Qué condición cumple la cantidad eficiente en este modelo?","options":["Agota los intercambios con ganancia conjunta y evita producir unidades que cuestan más de lo que valen al comprador.","Iguala siempre las ganancias individuales de cada comprador y vendedor.","Maximiza el número de unidades sin tener en cuenta el coste de las últimas."]},{"id":"4.8-d","type":"desarrollo","prompt":"Utiliza las unidades 25 y 75 para explicar por qué producir más o menos que la cantidad de equilibrio puede reducir el excedente total."}],"figure":{"src":"assets/figuras/4.8.svg","alt":"Cuándo una unidad adicional aumenta el excedente Valoración y coste de la unidad marginal, en euros 0 10 20 40 60 Unidad 25 Ganancia de 50 € Unidad 50 Valor y coste iguales Unidad 75 Pérdida de 50 € Cada flecha parte del coste y termina en la valoración del comprador. El equilibrio se alcanza en 50 unidades."}},{"id":"4.9","title":"El proceso de mercado: cambios en la demanda y la oferta","ideas":["Desplazar la demanda a la derecha aumenta precio y cantidad de equilibrio con oferta creciente fija. Hacia la izquierda ocurre lo contrario. Una oferta más elástica absorbe el cambio principalmente ampliando o reduciendo la cantidad. Con oferta inelástica, el precio debe ajustarse más.","Al desplazarse la oferta a la derecha aumenta la cantidad y baja el precio con demanda decreciente fija; al desplazarse a la izquierda disminuye la cantidad y sube el precio. La elasticidad de la demanda determina el reparto del ajuste entre precio y cantidad. Conviene identificar primero qué curva se desplaza y sobre cuál se produce el movimiento."],"source":"51–52","page":41,"questions":[{"id":"4.9-c1","type":"comprension","prompt":"¿Qué significa un desplazamiento de demanda hacia la derecha a cantidad dada?","options":["Que los productores aceptarían menos dinero por esa cantidad, aunque las preferencias de los compradores no cambien.","Que los consumidores están dispuestos a pagar más por esa cantidad.","Que los consumidores pagarían menos por esa misma cantidad."]},{"id":"4.9-c2","type":"comprension","prompt":"¿Qué ocurre con P y Q si aumenta la demanda y la oferta es creciente?","options":["Disminuyen tanto el precio como la cantidad de equilibrio.","Sube el precio y disminuye la cantidad intercambiada.","Aumentan el precio y la cantidad de equilibrio."]},{"id":"4.9-c3","type":"comprension","prompt":"¿Cómo modifica ese ajuste una oferta poco elástica?","options":["Mantiene el precio prácticamente fijo aunque la cantidad ofrecida apenas pueda variar.","La cantidad varía poco y el precio cambia más que con una oferta muy elástica.","Amplifica el aumento de la cantidad y amortigua el aumento del precio."]},{"id":"4.9-c4","type":"comprension","prompt":"¿Qué ocurre si los productores reducen la oferta a cada precio?","options":["La curva se desplaza a la izquierda, sube el precio y cae la cantidad de equilibrio.","La demanda se desplaza a la izquierda, bajan el precio y la cantidad.","La oferta se desplaza a la derecha, baja el precio y aumenta la cantidad."]},{"id":"4.9-c5","type":"comprension","prompt":"¿Qué elasticidad importa al evaluar una mejora de la oferta?","options":["La elasticidad de la demanda, pues el nuevo equilibrio se alcanza desplazándose sobre ella.","La elasticidad renta, porque todo aumento de la oferta modifica necesariamente la renta real en la misma proporción.","Solo la elasticidad de la oferta, porque el nuevo equilibrio mantiene fija la cantidad demandada a cualquier precio."]},{"id":"4.9-d","type":"desarrollo","prompt":"Compara dos mercados ante el mismo aumento de demanda cuando uno puede ampliar rápidamente su producción y el otro apenas puede hacerlo."}]},{"id":"4.9.1","title":"Cine: Sample sale","note":"Sin contenido en los archivos adjuntos."},{"id":"4.9.2","title":"Foro 8: El proceso de mercado","note":"Sin contenido en los archivos adjuntos."},{"id":"4.9.3","title":"Respuesta al foro: El proceso de mercado","note":"Sin contenido en los archivos adjuntos."},{"id":"4.10","title":"La oferta y demanda de los medios de producción","ideas":["Los factores de producción son bienes y servicios económicos utilizados para obtener otros productos. Los ofrecen trabajadores, propietarios de medios productivos y aportantes de capital. Los demandan quienes fabrican bienes finales o intermedios. Su demanda deriva de los bienes que ayudan a producir.","Una empresa que fabrica hormigón compra cemento y vende hormigón a quienes construyen casas. El mismo agente ocupa lados distintos de dos mercados. La oferta y la demanda de factores pueden estudiarse con el esquema de competencia bilateral."],"source":"52","page":42,"questions":[{"id":"4.10-c1","type":"comprension","prompt":"¿Quién demanda un bien de consumo final?","options":["El fabricante que lo vende en la última etapa, por el hecho de ponerlo a la venta.","El consumidor que quiere usarlo para satisfacer un fin.","Quien adquiere el bien exclusivamente para incorporarlo como insumo en otra producción."]},{"id":"4.10-c2","type":"comprension","prompt":"¿Quién demanda un factor productivo?","options":["El productor que prevé utilizarlo para elaborar bienes finales u otros factores.","El propietario que lo pone a disposición de otros a cambio de una renta.","La persona que adquiere el producto exclusivamente para consumirlo de manera directa."]},{"id":"4.10-c3","type":"comprension","prompt":"¿Quién ofrece trabajo en este mercado?","options":["Las empresas que publican vacantes, porque en el modelo ofrecen las horas que comprarán.","Los trabajadores ofrecen servicios u horas de trabajo.","Los consumidores finales, porque compran los bienes producidos con esas horas."]},{"id":"4.10-c4","type":"comprension","prompt":"¿Qué doble papel tiene la empresa de hormigón?","options":["Compra cemento en el mercado de ese factor y ofrece hormigón en el mercado de otro factor.","Demanda cemento y hormigón como bienes finales de consumo y no ofrece ninguno.","Vende cemento a sus proveedores y compra hormigón a las constructoras."]},{"id":"4.10-c5","type":"comprension","prompt":"¿Por qué importa la demanda de casas para el cemento?","options":["Porque las familias que demandan viviendas ofrecen automáticamente cemento al mismo precio.","La construcción requiere hormigón cuya fabricación utiliza cemento, de modo que la demanda se transmite hacia las etapas previas.","Porque las viviendas y el cemento satisfacen directamente el mismo fin del consumidor y son sustitutos finales."]},{"id":"4.10-d","type":"desarrollo","prompt":"Sigue la cadena cemento, hormigón y vivienda para identificar qué se intercambia y quién demanda cada producto."}]},{"id":"4.11","title":"La formación de los precios de los medios de producción en competencia bilateral","ideas":["Con muchos compradores y vendedores de un factor se confrontan los máximos que los primeros pagarán con los mínimos que los segundos aceptarán. En el ejemplo los máximos son 200, 180, 160, 140 y 120 €, y los mínimos son 100, 110, 160, 170 y 180 €. A 160 € tres interesados de cada lado pueden intercambiar.","A 159 € hay tres compradores para dos vendedores y a 161 €, dos compradores para tres vendedores. La pareja marginal delimita aquí un precio único. El máximo del productor depende del valor de la contribución marginal esperada del factor al producto y de su escasez relativa."],"source":"53","page":43,"questions":[{"id":"4.11-c1","type":"comprension","prompt":"¿Cuántos compradores admiten 159 €?","options":["Uno, porque solo la valoración máxima de 200 € permite comprar.","Dos, porque el comprador dispuesto a pagar 160 € queda excluido a 159 €.","Tres, los de máximos 200, 180 y 160 €."]},{"id":"4.11-c2","type":"comprension","prompt":"¿Cuántos vendedores aceptan 159 €?","options":["Dos, con mínimos de 100 y 110 €.","Uno, porque el vendedor de mínimo 110 € queda excluido a 159 €.","Tres, incluyendo al vendedor que exige al menos 160 €."]},{"id":"4.11-c3","type":"comprension","prompt":"¿Cómo cambia el recuento a 161 €?","options":["Pasan a ser tres compradores y tres vendedores.","Dos compradores y tres vendedores.","Se mantienen tres compradores y dos vendedores."]},{"id":"4.11-c4","type":"comprension","prompt":"¿A qué precio coinciden las cantidades?","options":["A 159 €, con tres participantes en cada lado.","A 160 €, donde pueden participar tres compradores y tres vendedores.","A 161 €, con dos participantes en cada lado."]},{"id":"4.11-c5","type":"comprension","prompt":"¿Qué fundamenta la valoración de un factor desde el lado comprador?","options":["El valor esperado de lo que permitirá producir en el margen, teniendo en cuenta su escasez.","Solo lo que pagó el propietario actual cuando lo adquirió.","El valor íntegro de toda la producción de la empresa, aunque se obtuviera también sin ese factor."]},{"id":"4.11-d","type":"desarrollo","prompt":"Explica la coordinación del mercado de factores a 160 € y compárala con la valoración de un bien de consumo."}]},{"id":"4.12","title":"El concepto de productividad marginal","ideas":["La productividad marginal física mide cuánto aumenta la producción al emplear una unidad más de un factor manteniendo los demás constantes. En el tramo de rendimientos decrecientes, las unidades sucesivas del factor variable aportan incrementos cada vez menores.","La productividad marginal económica valora monetariamente el incremento físico. Al precio de producto supuesto constante en la clase, valor del producto marginal = productividad marginal física × precio del producto. Veinte televisores adicionales al mes a 100 € por unidad aportan 2.000 €/mes. Esta cifra delimita lo que compensa pagar por ese trabajador, antes de considerar el plazo del cobro."],"source":"53–54","page":44,"questions":[{"id":"4.12-c1","type":"comprension","prompt":"¿Qué se mantiene fijo al medir la productividad marginal física?","options":["El volumen total de producto, al variar simultáneamente todos los factores.","Los demás factores de producción.","El número de unidades del propio factor añadido, mientras se amplía el resto."]},{"id":"4.12-c2","type":"comprension","prompt":"¿En qué unidades se mide el producto marginal físico del ejemplo?","options":["En trabajadores necesarios por euro de ingreso.","En televisores adicionales por trabajador y por mes.","En euros de ventas totales por mes."]},{"id":"4.12-c3","type":"comprension","prompt":"¿Cómo se obtiene el valor económico de esos veinte televisores?","options":["Sumando el precio de 100 € a las veinte unidades, lo que da 120 € al mes.","Multiplicando 20 por 100 €, lo que da 2.000 € al mes.","Dividiendo 100 € entre veinte televisores, lo que da 5 € al mes."]},{"id":"4.12-c4","type":"comprension","prompt":"¿Qué implican los rendimientos marginales decrecientes?","options":["Que, con los otros factores fijos, la producción adicional aportada por nuevas unidades del factor va disminuyendo.","Que cada nueva unidad del factor produce exactamente lo mismo que la anterior con los restantes factores fijos.","Que la producción total cae desde la primera unidad adicional, aunque todos los productos marginales sigan siendo positivos."]},{"id":"4.12-c5","type":"comprension","prompt":"¿Cambiaría el límite salarial si el precio del televisor bajara a 80 €?","options":["No, el límite monetario seguiría en 2.000 € porque el trabajador produce veinte unidades.","Sí, subiría a 2.500 € porque el menor precio aumenta por sí solo el valor de cada televisor.","Sí. Con el mismo rendimiento físico, el valor adicional sería 20 × 80 = 1.600 € al mes."]},{"id":"4.12-d","type":"desarrollo","prompt":"Explica por qué saber cuántos televisores produce un trabajador adicional es insuficiente para valorar su contratación."}]},{"id":"4.13","title":"La oferta y demanda del mercado laboral","ideas":["En el mercado laboral se intercambian horas de trabajo y el salario es el precio por unidad de tiempo. Las empresas demandan horas según su productividad marginal esperada. Con lo demás constante, a una tasa mayor menos horas cubren su coste salarial.","Los trabajadores comparan la remuneración de una hora más con la desutilidad de trabajarla, incluido el ocio perdido. La oferta suele crecer con el salario, aunque puede curvarse hacia atrás. En el margen, la tasa de equilibrio coordina el valor de una hora adicional para la empresa y el sacrificio de quien la ofrece."],"source":"54","page":45,"questions":[{"id":"4.13-c1","type":"comprension","prompt":"¿Qué cantidad se intercambia en el mercado laboral del modelo?","options":["El número de unidades de producto que vende el empresario al público.","Horas de trabajo.","El importe total en euros pagado por los consumidores de la empresa."]},{"id":"4.13-c2","type":"comprension","prompt":"¿Qué variable explica la disposición empresarial a contratar una hora más?","options":["El salario de subsistencia de la población, con independencia del valor producido por esa hora.","Su productividad marginal esperada en términos monetarios.","El producto total histórico de la empresa, sin comparar cuánto añade la nueva hora."]},{"id":"4.13-c3","type":"comprension","prompt":"¿Qué coste sopesa quien decide trabajar una hora extra?","options":["Los ingresos que obtiene por trabajar esa hora, considerados íntegramente un coste.","El valor monetario de toda la producción del empresario en el mes.","La desutilidad marginal de trabajarla, incluido el valor del ocio al que renuncia."]},{"id":"4.13-c4","type":"comprension","prompt":"¿Por qué una subida salarial reduce las horas demandadas, con lo demás constante?","options":["Algunas horas aportan un valor inferior al nuevo coste salarial.","Porque el aumento salarial desplaza necesariamente la demanda final de los consumidores hacia la izquierda.","Porque disminuye la productividad física de todas las horas en la misma proporción en que sube el salario."]},{"id":"4.13-c5","type":"comprension","prompt":"¿Qué matiz introduce el profesor sobre la oferta laboral?","options":["Que necesariamente crece en todos sus tramos, incluso si aumenta mucho el valor atribuido al ocio.","Puede curvarse hacia atrás, de modo que salarios más altos no siempre generan más horas ofrecidas.","Que siempre es horizontal y admite cualquier cantidad de horas al mismo salario."]},{"id":"4.13-d","type":"desarrollo","prompt":"Reconstruye una decisión marginal de contratación y otra de oferta de trabajo que puedan coincidir al mismo salario."}]},{"id":"4.14","title":"Por qué la ley de hierro de los salarios es falsa","ideas":["La ley de hierro sostenía que los salarios tenderían al mínimo de subsistencia. La clase identifica dos supuestos problemáticos: que las empresas podrían pagar siempre el mínimo sin perder trabajadores y que habría una oferta de trabajo perfectamente elástica a esa tasa.","Los empleadores compiten entre sí por las horas disponibles. Si la productividad marginal esperada es alta, un rival puede ofrecer un salario superior y seguir beneficiándose de la contratación. Al ser limitada la oferta, el salario resulta de la competencia a ambos lados del mercado."],"source":"55","page":46,"questions":[{"id":"4.14-c1","type":"comprension","prompt":"¿Qué predice la ley de hierro?","options":["Que los salarios tenderían a igualar el valor total de la producción de cada empresa.","Que el salario tendería al mínimo necesario para la subsistencia.","Que el salario siempre se situaría por encima del nivel de subsistencia en una proporción fija."]},{"id":"4.14-c2","type":"comprension","prompt":"¿Qué supondría una oferta perfectamente elástica a ese salario?","options":["Que se podrían obtener horas adicionales al mismo salario sin necesidad de elevarlo.","Que las horas disponibles serían fijas y no cambiarían ni siquiera al elevar mucho el salario.","Que habría que pagar un salario mayor por cada hora adicional, por pequeña que fuera la contratación."]},{"id":"4.14-c3","type":"comprension","prompt":"¿Por qué un empresario puede ofrecer más que la subsistencia?","options":["Porque espera obtener de la contratación una aportación superior al salario ofertado.","Porque pagar más que la subsistencia reduce por sí solo todos los costes productivos de forma equivalente.","Porque el mínimo de subsistencia determina también el máximo que aporta cualquier trabajador."]},{"id":"4.14-c4","type":"comprension","prompt":"¿Qué riesgo afronta una empresa que mantiene sueldos bajos si el trabajo es escaso?","options":["Que todo trabajador tenga prohibido cambiar de empresa por una oferta mejor.","Que la oferta de horas sea ilimitada al salario vigente y ninguna empresa pueda atraer a empleados de otra.","Que otros empleadores atraigan a los trabajadores con ofertas superiores."]},{"id":"4.14-c5","type":"comprension","prompt":"¿Qué dos factores ayudan a explicar salarios por encima del mínimo?","options":["La necesidad biológica de subsistencia y la obligación de pagar siempre exactamente ese mínimo.","La productividad marginal esperada y la oferta limitada de trabajadores frente a la demanda.","La oferta ilimitada de horas al mínimo y la ausencia total de competencia entre empresas."]},{"id":"4.14-d","type":"desarrollo","prompt":"Explica la crítica del profesor a la ley de hierro incorporando el comportamiento de los empleadores competidores."}]},{"id":"4.15","title":"Los sindicatos no pueden incrementar los salarios","ideas":["En el modelo competitivo de la clase, el crecimiento de la productividad puede elevar la remuneración sostenible del trabajo. La otra vía estudiada consiste en restringir la oferta efectiva o negociar una tasa superior al equilibrio. La negociación por sí sola no eleva el valor producido por hora.","Al salario superior, aumenta la cantidad de trabajo que se desea ofrecer y se reduce la contratada. Quienes retienen empleos pueden cobrar más y otros, como jóvenes de baja productividad inicial, quedar excluidos o buscar empleo informal. La selección puede emplear a alguien con mayor coste de oportunidad y excluir a otro con menor coste. Con menos empleados, aumenta el producto marginal del último contratado bajo rendimientos decrecientes."],"source":"55–56","page":47,"questions":[{"id":"4.15-c1","type":"comprension","prompt":"¿Qué dos mecanismos de subida salarial distingue la clase?","options":["Una reducción del producto marginal y un aumento de la oferta laboral a cada salario.","Un descenso de la demanda de trabajo y la entrada simultánea de más oferentes de horas.","Un aumento de productividad marginal y una restricción de la oferta efectiva de trabajo."]},{"id":"4.15-c2","type":"comprension","prompt":"¿Qué diferencia hay entre salario por hora y acceso al empleo?","options":["Cobrar más por hora asegura que todas las personas que buscan empleo trabajen más horas.","Un salario horario mayor implica necesariamente más puestos disponibles, incluso si cae la demanda de horas.","Quienes conservan el puesto pueden cobrar más por hora aunque menos personas consigan trabajar."]},{"id":"4.15-c3","type":"comprension","prompt":"¿Por qué puede surgir desempleo a un salario superior al equilibrio?","options":["Más personas ofrecen trabajo mientras menos horas resultan rentables para las empresas.","Porque la subida salarial elimina automáticamente la diferencia entre oferta y demanda de horas.","Porque las empresas desean contratar más horas de las que ofrecen los trabajadores."]},{"id":"4.15-c4","type":"comprension","prompt":"¿Qué papel tendría el mercado informal en el razonamiento?","options":["Algunos excluidos y empleadores buscarían contratar en condiciones distintas de las exigidas formalmente.","Haría cumplir el salario formal en cada contrato y eliminaría la posibilidad de pactar otras condiciones.","Absorbería a todos los desempleados automáticamente al mismo salario formal."]},{"id":"4.15-c5","type":"comprension","prompt":"¿Por qué cambia el producto marginal del último empleado?","options":["Al reducirse el número de contratados, queda una unidad marginal de mayor productividad bajo rendimientos decrecientes.","La reducción del empleo obliga a que el producto marginal sea idéntico al producto medio.","Al contratar menos personas, la última unidad empleada pasa a ser la menos productiva de todas las que se han excluido."]},{"id":"4.15-d","type":"desarrollo","prompt":"Interpreta el título de este apartado distinguiendo los salarios de los afiliados empleados, el empleo y la productividad."}]},{"id":"4.16","title":"Diferencias en salarios","ideas":["Las diferencias salariales combinan demanda, determinada por el valor de la aportación marginal esperada, y oferta de trabajadores capaces y dispuestos a prestar ese servicio. La comparación entre una estrella del fútbol y un profesional sanitario exige considerar la escasez de sustitutos para el puesto y los ingresos adicionales que el empleador prevé obtener.","El profesor cita a Messi frente a un jugador normal y a Emma Stone en La La Land, película con 447 millones de dólares de recaudación según la clase. Esa cifra incluye el esfuerzo de muchas personas y no mide por sí sola el aporte de la actriz. Para el reparto a domicilio, la clase subraya la abundancia relativa de personas disponibles y relaciona la competencia global con el estancamiento de algunos salarios."],"source":"56–57","page":48,"questions":[{"id":"4.16-c1","type":"comprension","prompt":"¿De qué depende la demanda empresarial de un perfil profesional?","options":["Solo del número de personas que solicitan esa profesión, con independencia de lo que aporten.","Del valor total producido por el sector, atribuido íntegro a cada nuevo contratado.","Del valor monetario que el empleador espera de una contratación adicional."]},{"id":"4.16-c2","type":"comprension","prompt":"¿Qué efecto tiene una escasa oferta de sustitutos cercanos para una estrella?","options":["Intensifica la competencia por contratarla dada la demanda de sus servicios.","Reduce su poder de negociación porque cualquier empleador puede reemplazarla sin pérdida.","Hace que su salario se iguale al de profesionales que tienen muchos sustitutos equivalentes."]},{"id":"4.16-c3","type":"comprension","prompt":"¿Qué compara el ejemplo de Messi con un jugador corriente?","options":["Únicamente el número idéntico de minutos que dura un partido, al que se atribuye toda la diferencia salarial.","Solo el dinero gastado en sus entrenamientos pasados, que fija el salario de ambos independientemente de la demanda.","Su diferente contribución marginal esperada y la escasez de prestaciones equivalentes."]},{"id":"4.16-c4","type":"comprension","prompt":"¿Puede atribuirse toda la recaudación de una película a la actriz?","options":["No. Para valorar su contribución habría que comparar el resultado esperado con el de una alternativa.","Sí, porque firmar un contrato atribuye a la actriz la totalidad del ingreso de la película.","Sí, porque si otras personas colaboran, su aportación debe medirse únicamente por el coste contable de su salario."]},{"id":"4.16-c5","type":"comprension","prompt":"¿Por qué se menciona el reparto a domicilio?","options":["Ilustra una ocupación para la que hay más personas capaces y dispuestas a ofrecer servicios similares.","Para probar que todos los salarios deben ser idénticos si los trabajadores dedican las mismas horas.","Para mostrar una ocupación cuyos trabajadores son tan difíciles de sustituir como una estrella única."]},{"id":"4.16-d","type":"desarrollo","prompt":"Explica la diferencia entre el salario de una estrella y el de otros profesionales utilizando oferta y demanda."}]},{"id":"4.16.1","title":"Foro 9: Diferencias de salarios","note":"Sin contenido en los archivos adjuntos."},{"id":"4.16.2","title":"Respuesta al foro: Diferencia de salarios","note":"Sin contenido en los archivos adjuntos."},{"id":"4.17","title":"Determinación de los tipos de interés: la elección intertemporal","ideas":["Atesorar conserva la posibilidad de gastar cuando se desee. Invertir compromete recursos presentes para adquirir un flujo futuro esperado. Quien invierte asume un plazo, incertidumbre sobre los resultados y posible dificultad para recuperar dinero antes de tiempo. La clase identifica preferencia temporal, aversión al riesgo y preferencia por la liquidez como fuentes del descuento.","Para un flujo futuro VF a t periodos y una tasa por periodo i, VA = VF/(1 + i)^t. Pagar hoy 90 € por 100 € esperados dentro de un periodo implica i = 100/90 − 1 ≈ 11,11 %. Si una máquina aportará 1.000 € en un año y se exige un 10 %, el máximo actual ronda 909,09 €. La demanda de factores depende así de su productividad marginal descontada.","Una preferencia intensa por consumir hoy, un pago más lejano o un mayor riesgo reducen el valor presente, en igualdad de otras condiciones. Un activo líquido facilita revisar los planes. Para vender rápidamente un inmueble ilíquido puede ser necesario conceder un descuento. La clase compara la financiación de una empresa emergente con la de una industria madura, y la de un gobierno de solvencia dudosa con la de otro solvente. En igualdad de condiciones, un riesgo percibido mayor eleva la tasa exigida. Para la liquidez, compara la facilidad de vender acciones cotizadas con el tiempo de vender una vivienda."],"source":"57–59","page":49,"questions":[{"id":"4.17-c1","type":"comprension","prompt":"¿Qué diferencia temporal hay entre atesorar e invertir?","options":["El dinero atesorado exige esperar a que termine un proyecto y el invertido permanece siempre disponible de inmediato.","Atesorar e invertir inmovilizan necesariamente el dinero durante el mismo plazo y con el mismo riesgo.","El dinero atesorado queda disponible. La inversión vincula recursos a un plan que produce resultados futuros."]},{"id":"4.17-c2","type":"comprension","prompt":"¿Qué expresa la preferencia temporal?","options":["La mayor valoración de disponer de bienes antes frente a esperar por ellos, a igualdad de otras condiciones.","La indiferencia obligatoria entre recibir un bien hoy y recibirlo en cualquier fecha futura.","La preferencia por disponer del bien más tarde, incluso si fuera idéntico, gratuito y seguro disponer de él ahora."]},{"id":"4.17-c3","type":"comprension","prompt":"¿Cómo afectan riesgo e iliquidez al importe máximo que se pagaría hoy?","options":["Un flujo incierto o difícil de convertir pronto en dinero puede exigir más descuento y reducir el importe actual.","Elevan necesariamente el precio máximo actual porque cualquier flujo arriesgado vale más hoy.","Eliminan la necesidad de descontar ingresos futuros cuando la venta anticipada es difícil."]},{"id":"4.17-c4","type":"comprension","prompt":"¿Cuánto valen hoy 1.000 € esperados dentro de un año al 10 %?","options":["1.100 €, porque al cobro futuro se le añade un 10 %.","900 €, porque descontar un periodo equivale exactamente a restar el 10 % de la cifra futura.","1.000/1,10 = 909,09 € aproximadamente."]},{"id":"4.17-c5","type":"comprension","prompt":"¿Qué rentabilidad por periodo implica pagar 90 € por un cobro esperado de 100 €?","options":["90 %, porque la rentabilidad es el cociente entre los 90 € desembolsados y los 100 € recibidos.","La rentabilidad esperada es (100 − 90)/90 ≈ 11,11 %.","10 %, porque se divide la ganancia de 10 € por el cobro futuro de 100 €."]},{"id":"4.17-d","type":"desarrollo","prompt":"Relaciona la elección entre atesorar e invertir con el precio máximo que un empresario pagaría por una máquina."}],"figure":{"src":"assets/figuras/4.17.svg","alt":"Del ingreso futuro al precio máximo de hoy Máquina con un ingreso esperado de 1.000 € en un año · tasa exigida del 10 % Hoy 909,09 € Dentro de un año 1.000 € × 1,10 Para descontar en sentido inverso, se divide el ingreso esperado entre 1,10. Así se obtiene el valor actual."}},{"id":"4.17.1","title":"Cine: The Marshmallow Test","note":"Sin contenido en los archivos adjuntos."},{"id":"4.17.2","title":"Cine: The Office – $100 now or $5,000 a year from now?","note":"Sin contenido en los archivos adjuntos."},{"id":"4.17.3","title":"Foro 10: Tipos de interés","note":"Sin contenido en los archivos adjuntos."},{"id":"4.17.4","title":"Respuesta al foro: Tipos de interés","note":"Sin contenido en los archivos adjuntos."}]},{"number":5,"title":"La elasticidad","items":[{"id":"5.0","title":"Introducción","note":"La introducción presenta las cuestiones que se desarrollan en los apartados siguientes."},{"id":"5.1","title":"La elasticidad de la demanda","ideas":["Una elasticidad mide la sensibilidad de una variable ante otra mediante sus variaciones porcentuales. En la demanda hay tres preguntas distintas. La elasticidad precio estudia el efecto de variar el precio propio, la cruzada estudia el precio de otro bien y la elasticidad renta estudia la renta real del consumidor.","Para el precio propio, más sustitutos facilitan cambiar de bien. Una necesidad difícil de aplazar reduce la sensibilidad y una compra que absorbe gran parte del presupuesto suele aumentarla. El profesor cuestiona que una demanda pueda ser perfectamente vertical en todo el rango imaginable de precios. Una escasa respuesta en un tramo no demuestra insensibilidad absoluta."],"source":"60","page":50,"questions":[{"id":"5.1-c1","type":"comprension","prompt":"¿Qué cambio analiza la elasticidad precio de la demanda?","options":["El cambio absoluto del gasto cuando varía la renta del comprador.","La variación porcentual de la cantidad demandada cuando varía el precio del propio bien.","La variación porcentual de la cantidad ofrecida cuando sube el precio de un factor productivo."]},{"id":"5.1-c2","type":"comprension","prompt":"¿Qué variable cambia en la elasticidad cruzada?","options":["La renta real del consumidor.","El precio de otro bien, manteniendo las demás condiciones constantes.","Únicamente el precio del propio bien cuya cantidad demandada se analiza."]},{"id":"5.1-c3","type":"comprension","prompt":"¿Qué ingreso considera la elasticidad renta?","options":["El ingreso nominal del consumidor sin ajustar por cambios en el poder adquisitivo.","La facturación bruta del vendedor.","La renta real del consumidor."]},{"id":"5.1-c4","type":"comprension","prompt":"¿Por qué la disponibilidad de sustitutos eleva la sensibilidad al precio?","options":["Porque cada sustituto nuevo aumenta obligatoriamente la cantidad que se compra del bien encarecido.","Porque disponer de más sustitutos impide al comprador cambiar de producto si sube su precio.","El consumidor puede pasar a opciones que atienden un fin parecido cuando el bien se encarece."]},{"id":"5.1-c5","type":"comprension","prompt":"¿Qué distingue una demanda poco sensible en un tramo de una vertical en todo el dominio?","options":["Una demanda vertical permite grandes cambios de cantidad ante variaciones diminutas del precio.","Una respuesta pequeña en un tramo implica que la cantidad es fija para todos los precios.","La primera admite que la respuesta cambie en otros precios. La segunda supondría una cantidad fija a cualquier precio."]},{"id":"5.1-d","type":"desarrollo","prompt":"Explica por qué dos bienes pueden experimentar caídas de ventas muy distintas ante la misma subida porcentual de precio."}],"figure":{"src":"assets/figuras/5.1.svg","alt":"Una misma subida del precio, dos respuestas de compra Ejemplo didáctico Precio (u. monetarias por unidad) 9 10 11 12 80 95 100 70 Cantidad (unidades) Precio de 10 a 11 (+10 %) Demanda elástica De 100 a 80 unidades (−20 %). |E| = 2. Demanda inelástica De 100 a 95 unidades (−5 %). |E| = 0,5. Porcentajes sobre los valores iniciales."}},{"id":"5.1.1","title":"Cine: Elasticidad demanda precio (Elefante Simpsons)","note":"Sin contenido en los archivos adjuntos."},{"id":"5.1.2","title":"Cine: Inelasticidad de la demanda (Jingle All The Way: Elasticity of TurboMan)","note":"Sin contenido en los archivos adjuntos."},{"id":"5.2","title":"Calculando la elasticidad de la demanda","ideas":["Con bases iniciales, Eprecio = [(Q₁ − Q₀)/Q₀] / [(P₁ − P₀)/P₀]. Para demanda decreciente es negativa. Se clasifica por magnitud: mayor que uno, elástica; igual a uno, unitaria; menor que uno, inelástica. La elasticidad puede variar a lo largo de una misma curva, incluso recta.","Ingreso por ventas = P × Q. Una subida tiene un efecto positivo por el mayor precio unitario y otro negativo por la menor cantidad. Para variaciones pequeñas, si domina el efecto cantidad (demanda elástica) cae el ingreso, si domina el precio (inelástica) sube, y con elasticidad unitaria local ambos se compensan en el margen. En la tabla del curso Q = 10 − P, de modo que a P = 4, 5 y 6 los ingresos son 24, 25 y 24.","Erenta = %ΔQ / %Δrenta real. Si es negativa, el bien es inferior. Si es positiva, es normal. Dentro de estos, un valor entre cero y uno indica necesidad y uno superior a la unidad, lujo. Ecruzada = %ΔQ de A / %Δprecio de B. Un signo positivo indica sustitutos y uno negativo, complementarios."],"source":"61–63","page":51,"questions":[{"id":"5.2-c1","type":"comprension","prompt":"¿Qué valor tiene Eprecio si P sube un 5 % y Q cae un 10 %?","options":["+2, porque los cambios opuestos de precio y cantidad producen un cociente positivo.","−10 %/5 % = −2. Su magnitud es 2 y la demanda es elástica.","−0,5, correspondiente a una demanda inelástica."]},{"id":"5.2-c2","type":"comprension","prompt":"¿Por qué puede variar la elasticidad aunque la pendiente sea constante?","options":["Porque la elasticidad solo depende de la inclinación visual y cambia si giramos el papel.","Una misma diferencia absoluta representa porcentajes distintos al cambiar las bases de precio y cantidad.","Porque una recta tiene necesariamente una pendiente distinta en cada punto."]},{"id":"5.2-c3","type":"comprension","prompt":"¿Qué ingresos se obtienen en la tabla a P = 4 y a P = 5?","options":["16 y 25, porque el ingreso se obtiene elevando al cuadrado cada precio.","6 y 5, porque las unidades compradas son iguales al ingreso total.","Se venden seis unidades por cuatro y cinco por cinco, lo que da 24 y 25 respectivamente."]},{"id":"5.2-c4","type":"comprension","prompt":"¿Qué significa una elasticidad renta de 0,5 y qué significa una de −0,5?","options":["Ambos son bienes de lujo, porque basta con que la elasticidad tenga magnitud positiva.","El primero es un bien normal de necesidad. El segundo es inferior y su cantidad demandada cae al aumentar la renta.","El primero es inferior y el segundo normal, porque un signo negativo indica que el bien mejora al aumentar la renta."]},{"id":"5.2-c5","type":"comprension","prompt":"¿Qué significa que el precio de B suba un 4 % y la cantidad demandada de A caiga un 2 %?","options":["Es +0,5, indicativo de sustitución entre ambos bienes.","Ecruzada = −0,5, compatible con bienes complementarios.","Es −2, porque se divide la subida del precio de B por la caída de las compras de A."]},{"id":"5.2-d","type":"desarrollo","prompt":"Explica cómo se relaciona la elasticidad precio con la facturación utilizando la curva Q = 10 − P."}],"figure":{"src":"assets/figuras/5.2.svg","alt":"El ingreso alcanza un máximo a mitad de la demanda Q = 10 − P Ingreso total (u. monetarias) 0 4 5 6 10 25 Precio (u. m./unidad) Ingreso = P × (10 − P) P = 4 4 × 6 = 24 P = 5 5 × 5 = 25 P = 6 6 × 4 = 24 Al subir el precio, primero domina el mayor precio unitario y luego la caída de Q."}},{"id":"5.3","title":"Aplicaciones de la elasticidad de la demanda","ideas":["La clase plantea tres cuestiones para discusión: pérdida de empleo industrial, eficacia de prohibir las drogas y crecimiento del gasto sanitario. El PDF recoge las preguntas juntas, sin el debate ni las respuestas. Para trabajarlas hay que identificar el shock, la variable que responde y la elasticidad pertinente.","Como aplicaciones condicionales, una ganancia de productividad puede aumentar las unidades por hora más deprisa que las ventas; un encarecimiento reducirá poco la cantidad si la demanda es inelástica; y un gasto monetario creciente puede reflejar precios, cantidades o ambos. Estos mecanismos permiten contrastar hipótesis y no identifican empíricamente una causa en cada sector."],"source":"61–63","page":52,"questions":[{"id":"5.3-c1","type":"comprension","prompt":"¿Qué comparación ayuda a estudiar por qué cae el trabajo industrial?","options":["Comparar el crecimiento de la producción vendida con el de la producción por hora de trabajo.","Comparar el valor monetario total de las ventas con el número acumulado de fábricas, interpretando cualquier aumento como pérdida de empleo.","Comparar solo los precios de venta de dos productos sin medir ni las horas empleadas ni la producción."]},{"id":"5.3-c2","type":"comprension","prompt":"¿Cómo respondería una demanda poco elástica ante un encarecimiento?","options":["Caería proporcionalmente más que la subida del precio.","Aumentaría proporcionalmente al precio por tratarse de un tramo inelástico de demanda decreciente.","La cantidad demandada caería proporcionalmente menos de lo que sube el precio."]},{"id":"5.3-c3","type":"comprension","prompt":"¿Qué consecuencias tendría esto para el gasto total ante un pequeño aumento del precio?","options":["En un tramo inelástico, el gasto tendería a aumentar aunque se comprasen menos unidades.","El gasto caería, pues la cantidad baja en una proporción mayor que la subida del precio.","El gasto quedaría constante porque esa compensación exacta define una demanda inelástica."]},{"id":"5.3-c4","type":"comprension","prompt":"¿Qué dos magnitudes hay que separar al hablar de gasto sanitario?","options":["Los ingresos de médicos y hospitales, identificando la suma de ambos con la cantidad física de servicios utilizados.","El gasto del año anterior y el actual, suponiendo que la diferencia mide siempre solo más servicios.","El precio de los servicios y la cantidad utilizada, ya que gasto = precio × cantidad."]},{"id":"5.3-c5","type":"comprension","prompt":"¿Qué información de los casos está ausente en la transcripción?","options":["Falta toda referencia a la prohibición de drogas o al gasto sanitario.","Faltan los tres temas planteados para la discusión, pero sí se aportan estimaciones numéricas completas.","Datos de elasticidad y resultados que permitan cuantificar los efectos o identificar una causa concreta."]},{"id":"5.3-d","type":"desarrollo","prompt":"Utiliza el caso del gasto sanitario para mostrar cómo construir una explicación que se pueda contrastar con datos."}]},{"id":"5.3.1","title":"Foro 11: Aplicaciones de la elasticidad de la demanda I","note":"Las preguntas para los foros se presentan juntas en 5.3. El archivo no identifica un enunciado individual para este foro."},{"id":"5.3.1.1","title":"Respuesta al foro: Aplicaciones a la elasticidad de la demanda I","note":"Sin contenido en los archivos adjuntos."},{"id":"5.3.2","title":"Foro 12: Aplicaciones de la elasticidad de la demanda II","note":"Las preguntas para los foros se presentan juntas en 5.3. El archivo no identifica un enunciado individual para este foro."},{"id":"5.3.2.1","title":"Respuesta al foro: Aplicaciones a la elasticidad de la demanda II","note":"Sin contenido en los archivos adjuntos."},{"id":"5.3.3","title":"Foro 13: Aplicaciones de la elasticidad de la demanda III","note":"Las preguntas para los foros se presentan juntas en 5.3. El archivo no identifica un enunciado individual para este foro."},{"id":"5.3.3.1","title":"Respuesta al foro: Aplicaciones a la elasticidad de la demanda III","note":"Sin contenido en los archivos adjuntos."},{"id":"5.4","title":"La elasticidad de la oferta","ideas":["La elasticidad precio de la oferta mide la sensibilidad proporcional de la cantidad ofrecida ante un cambio en el precio. Inventarios abundantes permiten vender más de inmediato. Capacidad ociosa en el sector o en sus proveedores y factores que pueden trasladarse entre industrias facilitan ampliar la producción.","La respuesta depende del coste marginal de aumentar la producción. Si ampliar la oferta encarece poco la unidad adicional, basta una pequeña subida de precio para inducir una variación grande de cantidad. Un plazo más largo suele permitir ajustes de instalaciones y factores que son imposibles de inmediato."],"source":"63–64","page":53,"questions":[{"id":"5.4-c1","type":"comprension","prompt":"¿Qué compara la elasticidad precio de la oferta?","options":["El cambio porcentual de cantidad ofrecida con el cambio porcentual del precio propio.","El cambio porcentual de la cantidad demandada respecto al de la renta real.","El aumento absoluto del precio respecto al coste medio histórico de la fábrica."]},{"id":"5.4-c2","type":"comprension","prompt":"¿Por qué un inventario abundante facilita la respuesta inmediata?","options":["Porque convierte la capacidad de producción corriente en ilimitada.","Porque obliga a producir primero una nueva unidad por cada unidad que ya estaba almacenada.","Permite ofrecer unidades almacenadas sin esperar a que finalice nueva producción."]},{"id":"5.4-c3","type":"comprension","prompt":"¿Qué relevancia tiene la capacidad de los proveedores?","options":["Su capacidad solo determina la demanda de los consumidores y no afecta a la posibilidad de ampliar la producción.","Si pueden ampliar fácilmente sus entregas, la falta de insumos frena menos la expansión del sector.","Si los proveedores no pueden ampliar sus entregas, el sector puede expandirse con más facilidad por disponer de menos insumos."]},{"id":"5.4-c4","type":"comprension","prompt":"¿Cómo influye la movilidad de factores entre industrias?","options":["Hace la oferta perfectamente rígida en todos los plazos, aunque existan recursos transferibles.","Impide expandir la producción, porque cualquier factor desplazado deja de poder usarse en el nuevo sector.","Facilita trasladar recursos hacia el sector que se expande y aumenta su capacidad de respuesta."]},{"id":"5.4-c5","type":"comprension","prompt":"¿Qué relación hay entre coste marginal y elasticidad de la oferta?","options":["La elasticidad es siempre igual al coste marginal expresado en euros.","Cuanto menos se encarece obtener nuevas unidades, más puede ampliarse la cantidad ante una subida dada de precio.","Cuanto más rápidamente aumenta el coste marginal, más se expande la oferta ante una misma subida de precio."]},{"id":"5.4-d","type":"desarrollo","prompt":"Compara la respuesta inmediata y la de largo plazo de dos empresas con inventarios y capacidad distintos."}]},{"id":"5.5","title":"Calculando la elasticidad de la oferta","ideas":["Para el procedimiento de la clase se usan las cantidades y precios iniciales como denominadores. Eoferta = [(Q₁ − Q₀)/Q₀] / [(P₁ − P₀)/P₀] = %ΔQ ofrecida / %ΔP. Las unidades se cancelan. En una oferta creciente las dos variaciones tienen el mismo signo.","Eoferta > 1 indica respuesta más que proporcional, 0 ≤ Eoferta < 1 respuesta menos que proporcional y Eoferta = 1 cambios proporcionales iguales. Por ejemplo, si P pasa de 10 a 11 y Q de 100 a 120, Eoferta = 20 %/10 % = 2."],"source":"64","page":54,"questions":[{"id":"5.5-c1","type":"comprension","prompt":"¿Qué dato sirve de base para calcular el cambio porcentual de cantidad?","options":["La cantidad adicional ofrecida, usada a la vez como numerador y denominador.","La cantidad ofrecida inicial.","El precio final del bien, medido en euros."]},{"id":"5.5-c2","type":"comprension","prompt":"¿Qué se obtiene si la cantidad ofrecida sube un 3 % y el precio sube un 12 %?","options":["Eoferta = 0,25. La oferta es inelástica.","4, por lo que la oferta es elástica.","0,75, por lo que la oferta es inelástica."]},{"id":"5.5-c3","type":"comprension","prompt":"¿Cómo se clasifica una oferta que aumenta un 8 % ante un precio un 8 % mayor?","options":["Unitaria, ya que 8 %/8 % = 1.","Elástica, porque cualquier aumento de cantidad del 8 % supera el umbral del 1 %.","Inelástica, porque las dos variaciones se anulan al restarlas."]},{"id":"5.5-c4","type":"comprension","prompt":"¿Por qué no basta dividir unidades adicionales entre euros adicionales?","options":["Eso mide respuesta en unidades por euro. La elasticidad utiliza variaciones relativas comparables.","Porque es preciso dividir primero los euros entre las unidades; ese cociente absoluto ya es la elasticidad.","Porque deben sumarse directamente unidades y euros antes de comparar sus cambios."]},{"id":"5.5-c5","type":"comprension","prompt":"¿Qué signo resulta si el precio y la cantidad ofrecida disminuyen?","options":["Positivo, puesto que se dividen dos cambios negativos.","Cero, porque dos porcentajes con el mismo signo siempre se anulan.","Negativo, porque la cantidad ofrecida disminuye."]},{"id":"5.5-d","type":"desarrollo","prompt":"Calcula e interpreta la elasticidad de una oferta que pasa de 100 a 120 unidades al subir el precio de 10 a 11 euros."}]},{"id":"5.6","title":"Aplicaciones de la elasticidad de la oferta","ideas":["El profesor plantea dos preguntas para los foros: si la recompra pública reduce las armas en circulación y si comprar la libertad de personas esclavizadas en Sudán reduce la esclavitud. La transcripción recoge los enunciados, sin datos sobre resultados ni soluciones de los foros.","Como ejercicio de análisis económico, distinguir el resultado directo de cada compra de la reacción agregada de la oferta. El efecto neto depende de si aparecen nuevas unidades o aumenta la actividad de los proveedores ante la demanda añadida, así como del horizonte considerado. La elasticidad describe esa respuesta y por sí sola no acredita un resultado histórico."],"source":"64","page":55,"questions":[{"id":"5.6-c1","type":"comprension","prompt":"¿Qué cambio introduce un comprador adicional en un mercado?","options":["Reduce la demanda a cada precio por el mero hecho de que el número de compradores ha crecido.","Aumenta la demanda a un precio dado si sus compras se añaden a las previas.","Desplaza directamente la oferta del bien hacia la derecha aunque los vendedores no cambien sus planes."]},{"id":"5.6-c2","type":"comprension","prompt":"¿Qué mide el efecto directo en una campaña de recompra?","options":["La cantidad adicional que se fabricará en años futuros, se haya producido o no.","La reducción neta y permanente del total, que siempre coincide con las unidades compradas.","Las unidades retiradas mediante las operaciones observadas."]},{"id":"5.6-c3","type":"comprension","prompt":"¿Qué habría que medir para evaluar su efecto neto?","options":["Solo el presupuesto gastado, tomando cada euro de gasto como una unidad neta retirada.","El cambio del total en circulación frente a lo que habría ocurrido sin el programa, incluidas reposiciones.","Solo el número de unidades retiradas, suponiendo idéntico el comportamiento de proveedores con y sin programa."]},{"id":"5.6-c4","type":"comprension","prompt":"¿Por qué es relevante el horizonte de evaluación?","options":["Porque el número de unidades adquiridas hoy fija de forma irreversible el total de todos los años siguientes.","Porque la capacidad de reaccionar de los proveedores siempre desaparece conforme transcurre el tiempo.","La oferta suele poder ajustarse más con el paso del tiempo."]},{"id":"5.6-c5","type":"comprension","prompt":"¿Qué distinción exige el caso de la compra de la libertad?","options":["Equiparar cada liberación individual con una reducción permanente idéntica de la esclavitud total.","Distinguir el beneficio concreto para la persona liberada del efecto agregado sobre el número de personas esclavizadas.","Tomar el precio pagado por cada persona como medida directa del número total de personas que quedan esclavizadas."]},{"id":"5.6-d","type":"desarrollo","prompt":"Explica por qué contar las compras de un programa no basta para evaluar el cambio agregado que persigue."}]},{"id":"5.6.1","title":"Foro 14: Aplicaciones de la elasticidad de la oferta I","note":"Las preguntas para los foros se presentan juntas en 5.6. El archivo no identifica un enunciado individual para este foro."},{"id":"5.6.1.1","title":"Respuesta al foro: Aplicaciones de la elasticidad de la oferta I","note":"Sin contenido en los archivos adjuntos."},{"id":"5.6.2","title":"Foro 15: Aplicaciones de la elasticidad de la oferta II","note":"Las preguntas para los foros se presentan juntas en 5.6. El archivo no identifica un enunciado individual para este foro."},{"id":"5.6.2.1","title":"Respuesta al foro: Aplicaciones de la elasticidad de la oferta II","note":"Sin contenido en los archivos adjuntos."},{"id":"5.7","title":"Usando la elasticidad para analizar los procesos de mercado","ideas":["Para un desplazamiento pequeño de la demanda, el cambio porcentual aproximado del precio es d/(|Ed| + Es), con d el aumento porcentual de cantidad demandada al precio inicial, |Ed| la magnitud de la elasticidad precio de demanda y Es la de oferta. Si la oferta se expande un s por ciento al precio inicial, la variación del precio es aproximadamente −s/(|Ed| + Es). Una contracción invierte el signo.","El profesor expresa las magnitudes como cocientes y sitúa el rango orientativo en desplazamientos del 10 % o menores. En ambos casos se trata de predicciones locales con las demás condiciones constantes. Los cambios en preferencias pueden alterar las propias curvas."],"source":"65","page":56,"questions":[{"id":"5.7-c1","type":"comprension","prompt":"¿Qué representa el numerador en un desplazamiento de demanda?","options":["La variación porcentual final del precio de equilibrio.","La variación porcentual de la demanda al precio inicial, no la variación de la cantidad de equilibrio.","La suma de los cambios absolutos del precio y la cantidad intercambiada."]},{"id":"5.7-c2","type":"comprension","prompt":"¿Qué elasticidades se suman en el denominador?","options":["La elasticidad precio de demanda con signo negativo más la de oferta, de modo que dos magnitudes iguales se cancelan.","La magnitud positiva de la elasticidad precio de demanda y la elasticidad precio de oferta.","La elasticidad renta y la elasticidad cruzada de los consumidores."]},{"id":"5.7-c3","type":"comprension","prompt":"¿Qué resultado da un aumento de demanda del 6 % si las elasticidades suman 2?","options":["Una bajada aproximada del 3 %.","Una subida aproximada del precio del 3 %.","Una subida aproximada del 12 %."]},{"id":"5.7-c4","type":"comprension","prompt":"¿Y si lo que aumenta un 6 % es la oferta?","options":["Una subida aproximada del 3 %.","Una bajada aproximada del precio del 3 % con el mismo denominador.","Una bajada aproximada del 12 %."]},{"id":"5.7-c5","type":"comprension","prompt":"¿Por qué se desaconseja extrapolar la fórmula a grandes cambios?","options":["Porque la aproximación funciona únicamente si los cambios de precio son superiores al 100 %.","Presupone una aproximación local y pueden cambiar elasticidades, preferencias u otras condiciones.","Porque una variación grande del precio nunca puede modificar la cantidad ofrecida ni la demandada."]},{"id":"5.7-d","type":"desarrollo","prompt":"Justifica el signo y la magnitud del ajuste del precio ante un pequeño desplazamiento de oferta o demanda."}]}]},{"number":6,"title":"El rol de los precios","items":[{"id":"6.0","title":"Introducción","note":"La introducción presenta las cuestiones que se desarrollan en los apartados siguientes."},{"id":"6.1","title":"Los procesos de mercado conectan el mundo","ideas":["La rosa de San Valentín ilustra la división internacional del trabajo. Se cultiva, corta y clasifica en Kenia por color, tamaño y categoría. La cadena de frío enlaza camiones con vuelos de Nairobi a los Países Bajos, la subasta de lotes con distribuidores y estos con la floristería final. Cada retraso puede depreciar una flor perecedera.","El curso cita más de 50.000 toneladas anuales de rosas cultivadas en Kenia y alrededor de veinte millones de flores diarias llegadas al mercado neerlandés como órdenes de magnitud de su relato. Agricultores, transportistas, fabricantes de abono y compradores especializados cooperan sin conocerse ni dominar toda la cadena. Sus ingresos dependen de atender bien su parte."],"source":"66–67","page":57,"questions":[{"id":"6.1-c1","type":"comprension","prompt":"¿Qué etapas sigue la rosa desde la plantación hasta la subasta?","options":["Cultivo en Países Bajos, refrigeración en Nairobi y traslado final a una subasta en Kenia.","Cultivo, recolección, clasificación, transporte refrigerado por carretera y vuelo desde Nairobi al mercado neerlandés.","Cultivo en Nairobi, venta al público en Kenia y subasta europea antes de la recolección."]},{"id":"6.1-c2","type":"comprension","prompt":"¿Por qué el tiempo de transporte tiene valor económico?","options":["La rosa se marchita y pierde valor para el consumidor si llega tarde o deteriorada.","Porque prolongar el trayecto aumenta siempre la calidad y el precio de la flor.","Porque una rosa recién cortada conserva el mismo valor con independencia del plazo y de la conservación."]},{"id":"6.1-c3","type":"comprension","prompt":"¿Qué función cumplen los compradores especializados?","options":["Pujan por lotes concretos que prevén distribuir y vender después.","Fijan el coste de producir cada rosa en la plantación antes de que se planten los tallos.","Reparten los lotes sin considerar el destino comercial ni pujar por ellos."]},{"id":"6.1-c4","type":"comprension","prompt":"¿Qué actividad contribuye sin tocar directamente la rosa?","options":["La fabricación y distribución del abono utilizado en la plantación, por ejemplo.","La clasificación manual de cada rosa recién cortada.","El corte directo de los tallos durante la recolección."]},{"id":"6.1-c5","type":"comprension","prompt":"¿Cómo coopera cada agente con consumidores a quienes desconoce?","options":["Mediante una orden individual de cada consumidor a todos los proveedores de insumos de la cadena.","Al prestar un servicio que la siguiente etapa valora y por el que está dispuesta a pagar.","Conociendo personalmente las preferencias de cada comprador final antes de colaborar."]},{"id":"6.1-d","type":"desarrollo","prompt":"Reconstruye la cadena de una rosa y explica cómo se coordinan decisiones especializadas a miles de kilómetros."}]},{"id":"6.2","title":"Los procesos de mercado están conectados","ideas":["Los mercados están interconectados porque los productos de un sector son costes o insumos de otro. El encarecimiento del petróleo en los años setenta elevó los costes de calefacción de los invernaderos estadounidenses de rosas. Con costes más altos, sus productores ofrecían menos a cada precio.","El impacto se transmite desde la energía al cultivo y a la localización de la producción. También afecta al transporte de las rosas que se importan. Por ello hay que comparar el coste total de las distintas formas de abastecer al cliente, con atención a la intensidad en energía de cada etapa."],"source":"67","page":58,"questions":[{"id":"6.2-c1","type":"comprension","prompt":"¿Qué factor conectó petróleo y rosas en el ejemplo?","options":["El uso de pétalos como materia prima para fabricar el combustible.","El petróleo como sustituto directo de las rosas en los ramos de los consumidores.","El combustible empleado para calentar los invernaderos estadounidenses."]},{"id":"6.2-c2","type":"comprension","prompt":"¿Qué ocurrió con el coste de producir rosas en aquellos invernaderos?","options":["Bajó, porque el aumento del precio del combustible abarató mantener la temperatura.","Permaneció necesariamente igual, ya que la calefacción no formaba parte de sus costes.","Subió al encarecerse la calefacción."]},{"id":"6.2-c3","type":"comprension","prompt":"¿En qué sentido cambió la curva de oferta estadounidense?","options":["No se desplazó; el encarecimiento del insumo solo movió a los consumidores sobre su demanda de rosas.","Se desplazó hacia la izquierda al poder ofrecerse menos a cada precio.","A la derecha, porque cada unidad de combustible más cara permitía ofrecer más flores al mismo precio."]},{"id":"6.2-c4","type":"comprension","prompt":"¿Por qué la distancia de Kenia no resuelve por sí sola la comparación?","options":["Porque basta con elegir el país más cercano, aunque la diferencia en calefacción supere con creces el transporte.","Hay que comparar el coste de transportar con el ahorro en calefacción y el resto de costes.","Porque la distancia no genera ningún coste de transporte ni de conservación en este mercado."]},{"id":"6.2-c5","type":"comprension","prompt":"¿Por qué un cambio energético puede afectar a un consumidor de flores?","options":["Porque el gasto en combustible y el precio de cada ramo deben aumentar por ley en idéntico porcentaje.","Modifica los costes de obtención y la oferta del producto final.","Porque los consumidores de flores pagan directamente toda la factura de cada invernadero aunque no compren ninguna rosa."]},{"id":"6.2-d","type":"desarrollo","prompt":"Explica cómo un cambio en el precio de un insumo puede modificar la geografía de un mercado."}]},{"id":"6.3","title":"Emprendimiento","ideas":["La función empresarial consiste en detectar oportunidades o desajustes y ensayar soluciones bajo incertidumbre. Una señal de precios hace visible un problema, pero alguien debe imaginar la alternativa, compararla con las existentes y arriesgar recursos para ponerla en práctica.","En la explicación de las rosas, un posible pionero compara el coste total de producir en Kenia y transportar la flor con el de mantener invernaderos en Estados Unidos. El profesor presenta ese pionero como reconstrucción hipotética de un proceso espontáneo. Un resultado rentable atrae imitadores y difunde la nueva forma de abastecimiento."],"source":"67–68","page":59,"questions":[{"id":"6.3-c1","type":"comprension","prompt":"¿Qué desajuste abre la oportunidad empresarial del ejemplo?","options":["El encarecimiento de la producción estadounidense al aumentar el coste de la calefacción.","Un abaratamiento de la calefacción estadounidense que hizo necesariamente más rentable trasladar el cultivo al extranjero.","La desaparición de la demanda mundial de rosas y la consiguiente imposibilidad de vender cualquier flor."]},{"id":"6.3-c2","type":"comprension","prompt":"¿Qué dos costes no debe olvidar quien estudia producir en Kenia?","options":["Solo la calefacción estadounidense y el coste total de construir todos los aeropuertos europeos.","Los costes locales de cultivo y los de trasladar y conservar la flor hasta su destino.","Solo el precio de venta en destino y la facturación de la subasta, tratándolos como costes de cultivo."]},{"id":"6.3-c3","type":"comprension","prompt":"¿Qué diferencia el cálculo empresarial de una garantía de éxito?","options":["El cálculo fija por contrato la demanda futura de todos los consumidores.","Se apoya en previsiones sobre costes, ventas y condiciones futuras que pueden fallar.","Una previsión rentable elimina la posibilidad de pérdidas aunque cambien costes y preferencias."]},{"id":"6.3-c4","type":"comprension","prompt":"¿Qué papel desempeña la imitación?","options":["Evita que soluciones rentables se difundan porque solo su primer creador puede aplicarlas.","Garantiza al primer innovador beneficios ilimitados aunque entren competidores.","Extiende una solución que otros han comprobado rentable."]},{"id":"6.3-c5","type":"comprension","prompt":"¿Qué aporta la creatividad al ajuste?","options":["Convierte cualquier incremento de costes en beneficios seguros sin cambiar la producción.","Descubre una combinación productiva que la subida del precio por sí sola no especificaba.","Permite deducir automáticamente del nuevo precio un único método de producción universal."]},{"id":"6.3-d","type":"desarrollo","prompt":"Describe cómo una señal de precios se convierte en una nueva ruta de suministro mediante la acción empresarial."}]},{"id":"6.3.1","title":"Cine: Tucker: The Man and His Dream","note":"Sin contenido en los archivos adjuntos."},{"id":"6.4","title":"Resolviendo el gran problema económico","ideas":["El problema económico consiste en emplear medios limitados con usos alternativos para satisfacer fines de muchas personas. Cuando el petróleo escasea, reducir todos sus usos por igual ignora que algunos se valoran más o tienen peores sustitutos. Entre febrero y mayo de 2022 el profesor sitúa la subida del petróleo por encima del 30 %. Contrapone sustituir asfalto por hormigón con reservar combustible para el transporte.","Un planificador necesitaría conocer usos, preferencias, sustitutos y sustitutos de los sustitutos, que cambian continuamente. La explicación de Hayek destaca la economía de conocimiento: basta que el precio comunique mayor escasez para que interesados dispersos ajusten decisiones. La señal también crea el incentivo a economizar.","Para el cálculo marginal de beneficios y costes, la clase destaca propiedad privada, libertad empresarial y precios de mercado. Contrasta esta coordinación con las restricciones estadounidenses a las gasolineras dominicales en la crisis de 1973–1974 y con la planificación a gran escala soviética o china."],"source":"68–71","page":60,"questions":[{"id":"6.4-c1","type":"comprension","prompt":"¿Por qué no se propone un recorte porcentual idéntico para todos los usos del petróleo?","options":["Los fines tienen valoraciones distintas y las posibilidades de sustitución varían entre usos.","Porque cada uso tiene idéntico valor y existe el mismo sustituto para todos.","Porque todo uso de petróleo puede abandonarse inmediatamente y sin coste."]},{"id":"6.4-c2","type":"comprension","prompt":"¿Qué ejemplo libera petróleo para el transporte?","options":["Sustituir hormigón por asfalto derivado del petróleo, manteniendo iguales los demás usos.","Aumentar el uso de petróleo en pavimentación para disponer a la vez de más combustible sin ampliar suministros.","Sustituir el asfalto derivado del petróleo por hormigón donde resulte económicamente conveniente."]},{"id":"6.4-c3","type":"comprension","prompt":"¿Qué tendría que conocer un planificador para reproducir todas las decisiones?","options":["Solo la cantidad total de petróleo extraído, prescindiendo de preferencias y alternativas.","Los usos alternativos, sus valoraciones, los sustitutos y sus alternativas en multitud de lugares y momentos.","Una media anual de precios internacionales, suficiente para determinar cada uso local futuro."]},{"id":"6.4-c4","type":"comprension","prompt":"¿Qué información transmite el precio a quien ignora el origen del shock?","options":["En qué yacimiento concreto se produjo la perturbación y durante cuántos días durará con certeza.","Que el recurso se ha vuelto relativamente más costoso y merece reconsiderar su uso.","Que es necesario seguir usando exactamente la misma cantidad del recurso en cada tarea."]},{"id":"6.4-c5","type":"comprension","prompt":"¿Qué tres condiciones destaca el profesor para el cálculo económico?","options":["Derechos de propiedad privada, libertad de iniciativa empresarial y precios de mercado.","Una sola empresa pública, salarios idénticos y cantidades de producción fijadas para todos los mercados.","Precios administrativos uniformes, prohibición de la iniciativa individual y ausencia de propiedad transferible."]},{"id":"6.4-d","type":"desarrollo","prompt":"Explica cómo una subida del petróleo permite coordinar usos dispersos sin que cada participante conozca el origen de la escasez."}]},{"id":"6.5","title":"Los precios son señales, incentivos y predicciones","ideas":["Los precios actúan como señales de escasez y valoración relativa. Al modificar costes y retornos esperados inducen cambios de conducta. Un gas más caro anima a reducir horas de calefacción, instalar alternativas como paneles fotovoltaicos, explorar otros yacimientos y atraer nuevos productores. Los precios de la vivienda atrajeron personas de otros oficios a la construcción en el ejemplo español del curso.","Los precios también incorporan expectativas. Si se anticipa inflación y los participantes esperan que aumente la demanda de oro, sus compras actuales pueden elevar ya su cotización. El precio refleja el resultado de apuestas y decisiones presentes sobre un futuro incierto."],"source":"71–72","page":61,"questions":[{"id":"6.5-c1","type":"comprension","prompt":"¿Qué señala un aumento de precio a un consumidor?","options":["Que el coste de oportunidad de comprar el bien ha disminuido aunque todo lo demás permanezca igual.","Que puede comprar más unidades con el mismo dinero sin reducir otros gastos.","Que el bien resulta más costoso en relación con otros usos de sus recursos."]},{"id":"6.5-c2","type":"comprension","prompt":"¿Qué dos respuestas domésticas ilustra la subida del gas?","options":["Moderar el uso de calefacción y considerar una tecnología sustitutiva.","Usar más calefacción y descartar cualquier sustitución porque el gas es ahora más barato.","Interpretar la subida como aumento de los ingresos del hogar y duplicar automáticamente el consumo."]},{"id":"6.5-c3","type":"comprension","prompt":"¿Qué oportunidades observa el productor de gas?","options":["Invertir en exploración, ampliar suministros o desarrollar sustitutos rentables.","Mantener fija toda decisión de inversión porque el precio solo transmite información a los consumidores.","Abandonar toda exploración porque los mayores precios reducen necesariamente el ingreso por unidad."]},{"id":"6.5-c4","type":"comprension","prompt":"¿Cómo ilustra la construcción española el traslado de recursos?","options":["Los recursos permanecieron inmóviles entre sectores pese a los cambios de ingresos esperados.","La subida de precios obligó a todos los trabajadores de la construcción a abandonar el sector.","La subida de precios y los ingresos esperados atrajeron trabajadores y empresarios procedentes de otros sectores."]},{"id":"6.5-c5","type":"comprension","prompt":"¿Cómo puede una expectativa de inflación influir en el oro antes de materializarse?","options":["Las expectativas no pueden influir en ninguna compra hasta que se publique la inflación realizada.","Una mayor demanda esperada reduce por necesidad la demanda presente aunque los compradores quieran anticiparse.","Quienes anticipan mayor demanda compran hoy, lo que puede elevar el precio presente."]},{"id":"6.5-d","type":"desarrollo","prompt":"Distingue señal, incentivo y expectativa mediante decisiones de consumo y de inversión."}]},{"id":"6.5.1","title":"Foro 16: Precios","note":"Sin contenido en los archivos adjuntos."},{"id":"6.6","title":"La importancia de la especulación económica","ideas":["Especular económicamente es intentar ganar anticipando cambios de precio. Si se espera aumento de población en Sevilla, comprar y reservar suelo hoy reduce la oferta disponible para oficinas u otros usos presentes. Al ofrecerlo para viviendas cuando llegue la nueva demanda, aumenta la oferta futura y modera el precio frente al escenario sin reserva. El aumento actual y la moderación futura comparan escenarios para la misma fecha.","El beneficio depende del acierto de la previsión. La clase contrapone esta especulación económica o autónoma con la política o exógena: adquirir suelo por conocer su próxima reclasificación administrativa difiere de anticipar una escasez residencial. En el segundo caso de reclasificación, el privilegio de información o decisión puede generar corrupción y nuevas intervenciones pueden crear nuevas ocasiones de privilegio."],"source":"72–74","page":62,"questions":[{"id":"6.6-c1","type":"comprension","prompt":"¿Qué expectativa motiva la reserva de suelo en Sevilla?","options":["Que aumente la población y se valore más espacio para viviendas en un par de años.","Que la población ya haya caído a cero y los precios estén fijados por contrato durante dos años.","Que la demanda residencial desaparezca y el suelo futuro pierda toda utilidad."]},{"id":"6.6-c2","type":"comprension","prompt":"¿Qué ocurre hoy con la oferta de suelo para otros usos?","options":["Se mantiene por definición, puesto que reservar una parcela nunca modifica su disponibilidad en el mercado.","Se reduce porque una parte se reserva para su posible utilización posterior.","Aumenta porque el mismo solar puede venderse hoy para otro uso y seguir íntegro en reserva."]},{"id":"6.6-c3","type":"comprension","prompt":"¿Con qué se compara la moderación futura del precio?","options":["Con el precio histórico al que se compró el terreno, sin atender a qué habría sucedido sin la reserva.","Con el precio que habría entonces si el suelo ya estuviera comprometido en usos alternativos.","Con el precio de una vivienda construida hoy en otra ciudad, tomado como único escenario alternativo."]},{"id":"6.6-c4","type":"comprension","prompt":"¿Qué riesgo asume quien anticipa una demanda residencial mayor?","options":["Que la expansión no ocurra y el precio de venta no cubra la compra y la espera.","Ninguno, dado que una demanda futura prevista equivale a una promesa firme de compra.","Que las expectativas acertadas le garanticen una pérdida determinada de antemano."]},{"id":"6.6-c5","type":"comprension","prompt":"¿Qué caracteriza la especulación política en el ejemplo?","options":["La oportunidad depende de una reclasificación administrativa conocida o esperada por el comprador.","Una simple previsión de crecimiento demográfico en un mercado sin cambios administrativos.","El coste físico de almacenar suelo, con independencia de cualquier decisión pública sobre su uso."]},{"id":"6.6-d","type":"desarrollo","prompt":"Compara la reserva de suelo ante una previsión demográfica con la compra basada en una recalificación privilegiada."}],"figure":{"src":"assets/figuras/6.6.svg","alt":"Reservar suelo cambia su disponibilidad en dos fechas Ejemplo de Sevilla Hoy Reserva para viviendas futuras Menos suelo disponible para otros usos. Presión al alza sobre el precio actual. Dentro de dos años Si llega la población prevista Más suelo disponible para viviendas. Menor precio que sin esa reserva. En cada fecha se comparan dos escenarios: con reserva y sin reserva de suelo."}},{"id":"6.6.1","title":"Foro 17: Precios y desastres naturales","note":"Sin contenido en los archivos adjuntos."},{"id":"6.6.2","title":"Foro 18: Precios y recursos naturales","note":"Sin contenido en los archivos adjuntos."},{"id":"Respuesta a los foros 16, 17 y 18","title":"Respuesta a los foros 16, 17 y 18: El rol de los precios","note":"Sin contenido en los archivos adjuntos."},{"id":"6.7","title":"Los precios máximos o precios techo","ideas":["Un precio máximo o techo prohíbe vender por encima del importe legal. Para determinar si altera el mercado hay que compararlo con el precio que igualaría las cantidades ofrecida y demandada. Si el techo queda por encima, el precio de equilibrio sigue siendo legal. Si queda por debajo, impide alcanzar ese equilibrio mediante una subida del precio.","Al techo vinculante se ofrecen menos unidades de las que se desean comprar. La escasez relativa existe siempre que los medios tienen usos alternativos. El desabastecimiento del ejemplo es la diferencia positiva entre la cantidad demandada y la ofrecida a ese precio concreto."],"source":"74–75","page":63,"questions":[{"id":"6.7-c1","type":"comprension","prompt":"¿Qué operaciones restringe un techo de precios?","options":["Las ventas a precios inferiores al máximo legal.","Solo las ventas que se realizan exactamente al máximo legal.","Las ventas por encima del máximo legal."]},{"id":"6.7-c2","type":"comprension","prompt":"¿Qué ocurre con un techo de 12 € si el equilibrio es 10 €?","options":["El precio de equilibrio sigue siendo legal y el techo no vincula en esas condiciones.","Se impone un precio obligatorio de 12 € y surge exceso de oferta en todo caso.","Queda prohibido vender a 10 €, porque está por debajo del techo."]},{"id":"6.7-c3","type":"comprension","prompt":"¿Y si el techo se fija en 8 €?","options":["Se forma un excedente físico porque los vendedores ofrecen más al precio reducido.","Se permite seguir comerciando a 10 € porque el techo solo prohíbe precios inferiores a 8 €.","Restringe las ventas al precio de equilibrio de 10 € y genera exceso de demanda con las curvas habituales."]},{"id":"6.7-c4","type":"comprension","prompt":"¿Cómo se mide el desabastecimiento al precio máximo?","options":["Como precio de equilibrio menos máximo legal, expresado en unidades físicas.","Como cantidad demandada menos cantidad ofrecida a ese precio.","Como cantidad ofrecida menos cantidad demandada al máximo."]},{"id":"6.7-c5","type":"comprension","prompt":"¿En qué se distingue del concepto general de escasez?","options":["La escasez relativa solo existe cuando una autoridad impone un precio máximo.","El desabastecimiento mide la escasez de todos los recursos de la economía cualquiera que sea el precio del bien.","El desabastecimiento es un desajuste a un precio concreto. La escasez relativa describe la limitación de medios frente a sus posibles usos."]},{"id":"6.7-d","type":"desarrollo","prompt":"Explica cómo comprobar si un precio máximo modifica los intercambios en un mercado competitivo."}],"figure":{"src":"assets/figuras/6.7.svg","alt":"El precio máximo y la cantidad que falta Precio Cantidad D O E Qo Qd Escasez: Qd − Qo Al precio máximo (línea discontinua), la cantidad demandada, Qd, supera la ofrecida, Qo. La distancia horizontal entre los puntos mide el desabastecimiento. Esquema · D: demanda · O: oferta"}},{"id":"6.8","title":"Consecuencias de los precios máximos o precios techo","ideas":["Un techo vinculante genera desabastecimiento, reduce los intercambios y pierde el excedente de acuerdos mutuamente ventajosos. Si las unidades se adjudican por cola, sorteo o cupo administrativo, pueden llegar a personas que las valoran menos y quedar excluidas otras que las valoran más. Esa pérdida de asignación se añade a la pérdida por producir o vender menos unidades.","Pueden aparecer ventas informales por encima del máximo y medidas públicas de racionamiento o control de la producción. A largo plazo pueden retirarse más proveedores, invertirse menos y deteriorarse la calidad. Los ejemplos son pisos de alquiler mal mantenidos y alimentos cuya calidad se rebaja para abaratar su coste."],"source":"74–77","page":64,"questions":[{"id":"6.8-c1","type":"comprension","prompt":"¿Qué dos cambios de cantidad producen el desabastecimiento?","options":["Aumentan las unidades que se ofrecen y permanecen fijas las que desean los compradores.","Disminuyen las unidades deseadas y aumentan las ofrecidas por el mero descenso del precio.","Aumentan las unidades que los compradores desean y disminuyen las que los vendedores ofrecen al techo."]},{"id":"6.8-c2","type":"comprension","prompt":"¿De dónde procede la pérdida irrecuperable por menor cantidad?","options":["Del valor íntegro de las ventas registradas después del control, aun si todas generasen ganancias mutuas.","De intercambios que habrían producido valor superior a su coste y dejan de realizarse.","De todo el dinero que cambia de manos en las unidades que siguen vendiéndose, aunque nadie deje de intercambiar."]},{"id":"6.8-c3","type":"comprension","prompt":"¿Qué pérdida puede añadir una cola incluso con la misma cantidad vendida?","options":["La cola aumenta el excedente obligatoriamente porque cada minuto de espera crea una unidad adicional del bien.","Algunas unidades se asignan a quien llegó antes y no a quien más las valora.","Ninguna, pues vender la misma cantidad siempre garantiza la asignación a quienes más la valoran."]},{"id":"6.8-c4","type":"comprension","prompt":"¿Qué incentiva la aparición de un mercado negro?","options":["Una oferta ilimitada al precio máximo, con todos los compradores plenamente satisfechos.","Hay compradores insatisfechos dispuestos a pagar más y proveedores dispuestos a vender por encima del máximo.","La imposibilidad de que ningún comprador valore el bien por encima del máximo."]},{"id":"6.8-c5","type":"comprension","prompt":"¿Por qué se deteriora una vivienda regulada en el ejemplo?","options":["La ley de control eleva físicamente el desgaste de los materiales incluso si el mantenimiento no varía.","La menor rentabilidad reduce el incentivo del propietario para gastar en conservación o seguir alquilando.","La menor renta percibida hace automáticamente más rentable invertir en todas las mejoras posibles."]},{"id":"6.8-d","type":"desarrollo","prompt":"Explica cómo un tope de alquiler puede afectar a la cantidad disponible, a quién consigue vivienda y a su mantenimiento."}]},{"id":"6.8.1","title":"Cine: Friends","note":"Sin contenido en los archivos adjuntos."},{"id":"6.9","title":"Argumentos a favor de los precios máximos","ideas":["Un argumento favorable a los máximos pretende proteger a hogares que no pueden pagar calefacción o vivienda. El profesor compara el control general con cheques dirigidos a quienes necesitan ayuda. Los cheques elevan la demanda efectiva y pueden estimular la cantidad ofrecida y los precios. Si se generalizan, parte del beneficio puede quedar en los vendedores, como ilustra con los vuelos de Canarias.","El segundo argumento invoca el monopolio. La clase diferencia el privilegio legal que limita la entrada de la posición conseguida por bajos costes y precios competitivos. Para el primer supuesto propone revisar la barrera regulatoria. Para el segundo pide examinar si existe una ineficiencia y advierte que las intervenciones pueden sostener productores menos eficientes."],"source":"77–78","page":65,"questions":[{"id":"6.9-c1","type":"comprension","prompt":"¿Qué problema distributivo motiva el máximo de alquileres?","options":["La imposibilidad de que los propietarios elijan qué modelo de calefacción instalar.","La dificultad de hogares con poca renta para costear una vivienda.","El exceso de ingresos de los inquilinos con mayor disponibilidad de viviendas."]},{"id":"6.9-c2","type":"comprension","prompt":"¿Qué permite focalizar un cheque que un techo general no distingue?","options":["Un precio idéntico por vivienda para todos los hogares, con independencia de su situación.","La ayuda según la situación económica del destinatario.","La ayuda según la antigüedad del edificio sin considerar quién recibe el cheque."]},{"id":"6.9-c3","type":"comprension","prompt":"¿Por qué podría el vendedor captar parte de la ayuda?","options":["Porque cobrar la ayuda obliga a los compradores a reducir la demanda en exactamente su importe.","Porque Hacienda entrega necesariamente el importe íntegro de todo cheque al propietario.","La demanda con más poder de compra puede elevar los precios y sus ingresos."]},{"id":"6.9-c4","type":"comprension","prompt":"¿Qué distinción hace la clase entre dos orígenes del proveedor único?","options":["Distingue empresas por tener más o menos empleados, sin atender a cómo se protegió o ganó la posición.","Distingue solo entre empresas nacionales y extranjeras, atribuyendo el monopolio al domicilio de cada una.","Privilegio legal de entrada frente a éxito competitivo por costes bajos."]},{"id":"6.9-c5","type":"comprension","prompt":"¿Qué medida plantea examinar primero en un monopolio protegido por ley?","options":["Atribuir la exclusividad a menores costes sin examinar las normas de entrada.","Endurecer las barreras legales para impedir que aparezcan posibles competidores.","Eliminar o revisar la regulación que concede el privilegio."]},{"id":"6.9-d","type":"desarrollo","prompt":"Compara la ayuda directa y el precio máximo como instrumentos para facilitar el acceso a la vivienda según la clase."}]},{"id":"6.9.1","title":"John Stossel: Control de precios en NYC","note":"Sin contenido en los archivos adjuntos."},{"id":"6.10","title":"¿Controles de precios universales?","ideas":["Un sistema de precios administrados generalizados sustituye los precios que surgirían de transacciones libres por importes fijados. Para replicar la coordinación, la autoridad tendría que conocer continuamente el precio compatible con los planes de compra y venta de cada bien. Una cifra fijada inferior al equilibrio opera como techo y una superior como suelo.","En la crítica de la clase a la planificación central, la multiplicación de faltantes y excedentes perturba la asignación entre sectores y periodos. Al desaparecer referencias de mercado, también se dificulta el cálculo que permitiría detectar usos alternativos de los recursos y ajustar los planes."],"source":"78","page":66,"questions":[{"id":"6.10-c1","type":"comprension","prompt":"¿Qué información necesitaría la autoridad para igualar todos los precios de coordinación?","options":["Los precios de equilibrio de cada bien en cada momento, dependientes de preferencias, costes y disponibilidades.","Solo el número de tipos de productos, sin datos de costes, preferencias o disponibilidad.","Únicamente el índice de precios del año pasado para fijar indefinidamente todos los precios futuros."]},{"id":"6.10-c2","type":"comprension","prompt":"¿Cómo actúa una cifra fija por debajo del precio de equilibrio?","options":["Como un suelo vinculante que deja unidades ofrecidas sin comprador.","Como un techo vinculante que genera exceso de demanda.","Como un precio libre que garantiza la coordinación aunque difiera del equilibrio."]},{"id":"6.10-c3","type":"comprension","prompt":"¿Cómo actúa una cifra fija por encima del precio de equilibrio?","options":["Como un techo vinculante que deja compradores sin unidades.","Como un suelo vinculante que genera exceso de oferta.","Como un precio de coordinación, porque toda cifra oficialmente fijada iguala cantidades."]},{"id":"6.10-c4","type":"comprension","prompt":"¿Por qué se propaga el desajuste a otros sectores?","options":["Porque todos los bienes son perfectos sustitutos y tienen siempre idéntico precio.","Muchos bienes son factores para otros productos y sus precios guían decisiones de producción y sustitución.","Porque el precio fijado revela automáticamente y sin error el valor de todos los insumos relacionados."]},{"id":"6.10-c5","type":"comprension","prompt":"¿Qué dimensión temporal se pierde según el argumento del curso?","options":["Solo la fecha contable de cada venta, que pasaría a ser imposible de anotar.","Las señales con que las personas coordinan el uso actual de recursos frente a usos esperados futuros.","La duración física pasada de los bienes, que desaparece al fijar un precio."]},{"id":"6.10-d","type":"desarrollo","prompt":"Explica por qué fijar todos los precios plantea un problema distinto del cálculo en un solo mercado."}]},{"id":"6.10.1","title":"Foro 19: Precios máximos y controles de precios universales","note":"Sin contenido en los archivos adjuntos."},{"id":"6.11","title":"Los precios mínimos o precios suelo","ideas":["El precio mínimo o suelo prohíbe vender por debajo de la cifra legal. El profesor menciona un mínimo de un euro por kilo de manzanas y una gráfica con equilibrio de aproximadamente 5,50 € y suelo de 8 €. El salario mínimo y ciertos precios agrícolas se presentan como ejemplos de esta figura.","Solo vincula cuando impide que se alcance el precio de coordinación. Por encima del equilibrio, la cantidad ofrecida supera a la demandada con las curvas habituales. Por debajo del equilibrio permite comerciar al precio que iguala cantidades."],"source":"78–79","page":67,"questions":[{"id":"6.11-c1","type":"comprension","prompt":"¿Qué prohíbe la norma que fija un precio mínimo?","options":["Formalizar ventas por encima del importe fijado.","Formalizar ventas exactamente al precio mínimo.","Formalizar ventas por debajo del importe fijado."]},{"id":"6.11-c2","type":"comprension","prompt":"¿Es legal vender manzanas a 1,20 €/kg con un suelo de 1 €/kg?","options":["No, porque un suelo de 1 € constituye el precio máximo permitido.","Sí. La venta supera el mínimo.","No, porque solo se permite cobrar exactamente 1 €/kg."]},{"id":"6.11-c3","type":"comprension","prompt":"¿Por qué vincula un suelo de 8 € si el equilibrio es 5,50 €?","options":["Porque obliga a demandar más unidades a 8 € de las que se demandarían a 5,50 €.","Porque impide vender al precio que coordinaría oferta y demanda.","Porque permite vender a 5,50 € y sanciona todos los precios por encima de 8 €."]},{"id":"6.11-c4","type":"comprension","prompt":"¿Qué ocurre con un suelo de 4 € en ese mismo ejemplo?","options":["La norma obliga a reducir todas las ventas a 4 €, por debajo del equilibrio.","El suelo prohíbe vender a 5,50 € y genera desabastecimiento como un techo.","El intercambio a 5,50 € sigue permitido."]},{"id":"6.11-c5","type":"comprension","prompt":"¿Qué tienen en común un suelo agrícola y un salario mínimo en el modelo?","options":["Ambos garantizan la venta de cualquier cantidad que los proveedores ofrezcan al precio regulado.","Ambos impiden cobrar por encima de un máximo.","Fijan un límite inferior al precio del bien o del servicio laboral intercambiado."]},{"id":"6.11-d","type":"desarrollo","prompt":"Describe cómo identificar un suelo vinculante en un gráfico y qué participantes quedan sin poder ejecutar sus planes."}],"figure":{"src":"assets/figuras/6.11.svg","alt":"El precio mínimo y las unidades que quedan sin vender Precio Cantidad D O E Qd Qo Excedente: Qo − Qd Al precio mínimo (línea discontinua), la cantidad ofrecida, Qo, supera la demandada, Qd. La distancia horizontal entre los puntos mide las unidades sin comprador. Ejemplo de clase: equilibrio ≈ 5,50 € y suelo de 8 €. Esquema · D: demanda · O: oferta"}},{"id":"6.12","title":"Consecuencias de los precios mínimos o precios suelo","ideas":["Un suelo vinculante deja unidades ofrecidas sin comprador. La cantidad intercambiada queda limitada por la demanda y se pierde excedente al desaparecer operaciones con beneficio conjunto. Si los pedidos se reparten entre productores sin seleccionar los menores costes, pueden utilizarse más recursos para la misma cantidad. Esta mala asignación añade otra pérdida.","El profesor también considera el mercado informal por debajo del mínimo, la compra pública, el subsidio, la distribución o la destrucción de excedentes. A largo plazo una oferta más elástica puede agrandar el exceso de oferta. Al impedir las rebajas, la competencia puede desplazarse a mejoras de calidad cuyo coste supera el valor que el comprador les atribuye."],"source":"79–81","page":68,"questions":[{"id":"6.12-c1","type":"comprension","prompt":"¿Cómo se mide el excedente sin vender al suelo?","options":["Como cantidad demandada menos cantidad ofrecida al mínimo.","Como la diferencia entre el precio mínimo y el de equilibrio expresada directamente en unidades sin vender.","Como cantidad ofrecida menos cantidad demandada al precio mínimo."]},{"id":"6.12-c2","type":"comprension","prompt":"¿Por qué la mala selección de productores puede aumentar la pérdida?","options":["Un proveedor de alto coste puede obtener la venta mientras uno de menor coste queda fuera.","Porque todos los productores tienen costes idénticos, de modo que la identidad del adjudicatario determina por sí sola una pérdida adicional.","Porque elegir al proveedor de menor coste siempre aumenta los recursos necesarios para la misma producción."]},{"id":"6.12-c3","type":"comprension","prompt":"¿Qué puede hacer la administración con las existencias?","options":["Está obligada a comprar la totalidad del excedente y a conservarlo indefinidamente en todos los casos.","Comprarlas, subsidiarlas, repartirlas o destruirlas, según los casos descritos.","El suelo obliga automáticamente a los compradores privados a adquirir todas las existencias, sin que pueda quedar excedente."]},{"id":"6.12-c4","type":"comprension","prompt":"¿Qué incentivo puede originar ventas informales?","options":["Vendedores sin cliente están dispuestos a aceptar un precio inferior al mínimo y algunos compradores los buscarían.","Un exceso de demanda al precio mínimo que hace que todos los compradores quieran pagar todavía más.","La obligación automática del Estado de comprar a todos al mínimo, aunque en el ejemplo no exista tal garantía."]},{"id":"6.12-c5","type":"comprension","prompt":"¿Cuándo es ineficiente mejorar la calidad para competir?","options":["Cuando el coste de la mejora supera lo que los compradores valoran y se emplean recursos con mejores usos.","Solo cuando la mejora sea gratuita y todos los compradores la valoren positivamente.","Siempre que atraiga a un comprador, aun cuando su disposición a pagar por la mejora supere ampliamente el coste."]},{"id":"6.12-d","type":"desarrollo","prompt":"Explica cómo un precio mínimo puede aumentar las existencias y los costes incluso si los consumidores compran menos."}]},{"id":"6.12.1","title":"Foro 20: Precios mínimos","note":"Sin contenido en los archivos adjuntos."}]},{"number":7,"title":"Cuando no funcionan los precios: Las externalidades","items":[{"id":"7.0","title":"Introducción","ideas":["El módulo parte de una pregunta sobre la coordinación económica. Aunque compradores y vendedores se pongan de acuerdo, queda por averiguar si han tenido en cuenta a todas las personas afectadas. El análisis compara lo que el precio comunica a las partes con los costes y beneficios que experimenta el conjunto de la sociedad.","Para valorar el alcance del resultado competitivo, el profesor propone examinar cuatro condiciones. Ha de existir un mercado, debe haber competencia, el precio debe recoger la información relevante y debe ser posible excluir a quienes no paguen. Cada condición orienta hacia un problema diferente."],"source":"82–83","page":69,"questions":[{"id":"7.0-c1","type":"comprension","prompt":"¿Qué pregunta añade el análisis social al acuerdo entre comprador y vendedor?","options":["Si el precio pactado basta para que el vendedor recupere sus costes fijos.","Pregunta si la producción o el consumo afectan a terceros cuyos costes o beneficios quedan fuera del acuerdo.","Si comprador y vendedor obtienen ganancias privadas de idéntico valor."]},{"id":"7.0-c2","type":"comprension","prompt":"¿Qué papel cumple la existencia de un mercado?","options":["Establece una valoración única del bien para todas las personas que lo compran.","Garantiza que cualquier precio anunciado iguale las cantidades ofrecidas y demandadas.","Proporciona un ámbito de intercambio mediante el que pueden coordinarse los planes de compradores y vendedores."]},{"id":"7.0-c3","type":"comprension","prompt":"¿Qué puede ocurrir con la oferta cuando falta competencia?","options":["Quien tiene poder de mercado puede restringir artificialmente la cantidad ofrecida.","La empresa que fija el precio está obligada a ampliar la producción hasta agotar su capacidad.","El proveedor con poder de mercado debe vender todas las unidades que resulten rentables al precio competitivo."]},{"id":"7.0-c4","type":"comprension","prompt":"¿Por qué interesa saber qué información transmite un precio?","options":["Porque conocer el precio basta para calcular cuánto gana cada persona con la transacción.","Porque las decisiones de producción y consumo pueden omitir una parte del valor o del coste de cada unidad.","Porque el precio permite sumar directamente las utilidades totales de todas las personas afectadas."]},{"id":"7.0-c5","type":"comprension","prompt":"¿Qué dificultad anticipa la imposibilidad de excluir a quien no paga?","options":["Nadie que reciba el beneficio tendrá motivo para utilizar el servicio.","El productor puede tener dificultades para financiar una oferta que beneficia también a personas que eluden contribuir.","El coste de producir una unidad adicional pasa necesariamente a cero."]},{"id":"7.0-d","type":"desarrollo","prompt":"Explica cómo examinarías la eficiencia de un intercambio que beneficia a sus dos participantes."}]},{"id":"7.1","title":"La eficiencia y los fallos de mercado","ideas":["La eficiencia de Pareto se alcanza cuando ninguna persona puede mejorar sin que alguna otra empeore. En el intercambio, se han agotado los cambios de manos mutuamente ventajosos. En la producción, obtener más de un bien exige reducir la producción de otro. La eficiencia económica requiere ambas dimensiones y una producción ajustada a las valoraciones marginales de los consumidores.","En el esquema competitivo, los compradores igualan al precio su disposición marginal a pagar y los vendedores igualan al precio su coste marginal de oportunidad. El primer teorema del bienestar vincula este equilibrio con la eficiencia bajo determinadas hipótesis. Son condiciones suficientes. Su incumplimiento impide invocar la garantía del teorema, aunque un resultado concreto aún puede ser eficiente.","El curso asocia la ausencia de mercados con mercados incompletos y selección adversa, la falta de competencia con monopolios y oligopolios, los precios que omiten información con externalidades y asimetrías informativas, y la falta de exclusión con bienes públicos y recursos comunes."],"source":"82–83","page":70,"questions":[{"id":"7.1-c1","type":"comprension","prompt":"¿Qué cambio excluiría la eficiencia de Pareto?","options":["Un cambio que aumente la igualdad de renta aunque reduzca el bienestar de algún afectado.","Una transferencia que beneficie a una persona a costa de perjudicar a otra.","Una reasignación factible que mejore la situación de al menos una persona sin perjudicar a otra."]},{"id":"7.1-c2","type":"comprension","prompt":"¿Qué intercambio revela ineficiencia en la distribución actual?","options":["Uno que iguale los patrimonios aunque perjudique a una de las partes.","Uno que aumente el ingreso monetario del vendedor pese a reducir la utilidad del comprador.","Un intercambio todavía posible que aumente la utilidad de una parte sin disminuir la de las demás."]},{"id":"7.1-c3","type":"comprension","prompt":"¿Cómo se reconoce una posibilidad de mejora productiva?","options":["Se eleva el valor monetario de la producción subiendo los precios con cantidades constantes.","Es factible obtener más de un bien manteniendo la producción de los demás.","Se produce más del bien con mayor precio aunque eso obligue a producir menos de otro."]},{"id":"7.1-c4","type":"comprension","prompt":"¿Qué dos magnitudes coordina el precio competitivo en el margen?","options":["El coste medio de la industria y la renta media de quienes compran el producto.","La disposición a pagar por la última unidad y su coste marginal de oportunidad, bajo los supuestos del modelo.","La utilidad total de los consumidores y el coste fijo de todas las empresas."]},{"id":"7.1-c5","type":"comprension","prompt":"¿Qué implica que las hipótesis del primer teorema sean suficientes?","options":["Que el teorema garantiza eficiencia con cualquier conjunto de hipótesis.","Con ellas puede concluirse eficiencia. Si alguna falla, debe analizarse el caso porque la eficiencia deja de estar garantizada.","Que, si falta una hipótesis, se demuestra por sí sola la ineficiencia del mercado."]},{"id":"7.1-d","type":"desarrollo","prompt":"Explica el primer teorema del bienestar y qué puede concluirse cuando aparece un monopolio o un coste externo."}]},{"id":"7.2","title":"Qué es una externalidad y por qué son ineficientes","ideas":["Una externalidad es un beneficio o un coste que la decisión de consumir o producir impone a terceros y que queda fuera del precio. En consumo, una vacuna beneficia a otras personas y la música alta puede perjudicar a vecinos. En producción, la investigación y el desarrollo (I+D) benefician a otros innovadores y la contaminación perjudica a quienes la sufren.","Excedente social = excedente del consumidor + excedente del productor + saldo de los efectos sobre terceros. La cantidad eficiente maximiza esa suma. En el ejemplo sin efectos externos, la unidad 50 vale 20 € para el comprador y cuesta 5 € producirla. A 12 €, genera 8 € de excedente del consumidor y 7 € del productor. En la unidad 110, ambas valoraciones marginales coinciden en 12 €.","Con un daño externo, algunas unidades rentables para las partes imponen una pérdida neta al conjunto. Con un beneficio externo, pueden quedar sin intercambiar unidades que aumentarían el excedente social."],"source":"83–85","page":71,"questions":[{"id":"7.2-c1","type":"comprension","prompt":"¿Qué convierte un efecto sobre terceros en una externalidad en el modelo del curso?","options":["Que la producción tenga un coste que el productor ya asume íntegramente al decidir.","Que el precio suba para otros consumidores porque aumenta la demanda, sin ningún efecto adicional fuera del mercado.","Que constituya un coste o beneficio del consumo o de la producción que no se incorpore al cálculo mediante el precio."]},{"id":"7.2-c2","type":"comprension","prompt":"¿Cómo se clasifican una vacuna y la música que molesta al vecino?","options":["Son externalidades de consumo, negativa la protección por vacunación y positiva la molestia por ruido.","Son externalidades de consumo. La protección de terceros es positiva y la molestia por ruido es negativa.","Ambas son externalidades negativas de producción porque los dos bienes cuestan recursos."]},{"id":"7.2-c3","type":"comprension","prompt":"¿Qué diferencia hay entre la I+D y las emisiones de una fábrica?","options":["Los dos efectos son costes externos de producción, incluso cuando los terceros aprovechan gratuitamente los conocimientos.","Ambas surgen en la producción. Los conocimientos que aprovechan terceros aportan beneficios y las emisiones pueden imponer daños.","Ambas son externalidades del consumo, negativas en la investigación y positivas en las emisiones."]},{"id":"7.2-c4","type":"comprension","prompt":"¿Cómo se distribuye la ganancia privada de la unidad 50 a 12 €?","options":["El comprador gana 20 € y el vendedor 12 €, con una ganancia conjunta de 32 €.","El comprador gana 20 − 12 = 8 € y el vendedor gana 12 − 5 = 7 €. La ganancia conjunta es 15 €.","El comprador gana 7 € y el vendedor 8 €, con una ganancia conjunta de 15 €."]},{"id":"7.2-c5","type":"comprension","prompt":"¿Qué habría que añadir a esos 15 € para evaluar esa unidad socialmente?","options":["Los beneficios marginales sobre terceros y, con signo negativo, los costes marginales que soporten.","Los ingresos totales de la empresa por todas las unidades vendidas.","El precio de 12 € otra vez, porque es un beneficio adicional para el conjunto social."]},{"id":"7.2-d","type":"desarrollo","prompt":"Utiliza la unidad 50 del ejemplo para explicar por qué una transacción voluntaria puede ser socialmente ineficiente."}]},{"id":"7.3","title":"Los costes externos o externalidades negativas","ideas":["Un coste externo separa el cálculo privado del social. En producción, coste marginal social = coste marginal privado + daño marginal externo. El ejemplo de los antibióticos parte de un cruce privado de oferta y demanda a 10 €. Al incorporar el coste externo, la curva social queda por encima de la oferta privada y su cruce con la demanda determina una cantidad menor. La transcripción no cuantifica ese daño.","En el consumo de música alta, el ajuste se representa por el lado de la demanda. Beneficio marginal social del consumo = beneficio marginal privado − molestia marginal a terceros. Esa demanda social queda por debajo de la privada. En ambos gráficos las unidades entre la cantidad socialmente eficiente y la privada reducen el excedente social."],"source":"85–86","page":72,"questions":[{"id":"7.3-c1","type":"comprension","prompt":"¿Qué magnitud se suma a la oferta privada al analizar un daño de producción?","options":["El beneficio marginal privado de quien compra el bien.","El daño marginal externo, que se suma al coste marginal privado.","El daño externo total de todas las unidades, sumado al coste de cada unidad individual."]},{"id":"7.3-c2","type":"comprension","prompt":"¿Qué representa el precio de 10 € del ejemplo de los antibióticos?","options":["El coste marginal externo de cada unidad de antibiótico.","El impuesto corrector que garantiza por sí mismo la cantidad eficiente.","El equilibrio privado antes del ajuste por el daño externo. Ese precio, por sí solo, no cuantifica el daño."]},{"id":"7.3-c3","type":"comprension","prompt":"¿Cómo se obtiene gráficamente la cantidad eficiente en el ejemplo de producción?","options":["Se cruza la curva de coste marginal social con la demanda, suponiendo que esta recoge el beneficio marginal social.","Se cruzan la oferta privada y la demanda privada sin incorporar el daño externo.","Se busca la cantidad donde el coste medio privado corta al coste medio social."]},{"id":"7.3-c4","type":"comprension","prompt":"¿Qué curva se ajusta para representar la molestia ocasionada por la música alta?","options":["La oferta se desplaza hacia abajo en el valor de la molestia al vecino.","La demanda. A la valoración marginal de quien escucha se resta el perjuicio marginal ocasionado a terceros.","La demanda social se obtiene sumando al disfrute del oyente el importe positivo del daño al vecino."]},{"id":"7.3-c5","type":"comprension","prompt":"¿Por qué las últimas unidades intercambiadas pueden reducir el bienestar?","options":["Porque el excedente del vendedor de la última unidad es siempre negativo en el equilibrio privado.","Porque su precio es mayor que cero aunque el beneficio marginal social exceda su coste.","En esas unidades el coste marginal social supera al beneficio marginal social, a pesar de que sus participantes aún encuentren conveniente comerciar."]},{"id":"7.3-d","type":"desarrollo","prompt":"Compara los gráficos de los antibióticos y la música alta y explica por qué ambos conducen a una cantidad eficiente menor."}],"figure":{"src":"assets/figuras/7.3.svg","alt":"El daño externo reduce la cantidad eficiente Antibióticos Valor o coste marginal (€/unidad) Q social Q privada Cantidad 10 Coste marginal privado Coste marginal social (incluye el daño) Beneficio marginal Se intercambian unidades cuyo coste social supera el beneficio. El área sombreada indica la pérdida de excedente. Esquema sin escala de cantidades."}},{"id":"7.3.1","title":"Cine: After Life","note":"Sin contenido en los archivos adjuntos."},{"id":"7.4","title":"Los beneficios externos o externalidades positivas","ideas":["Una externalidad positiva aparece cuando terceros reciben beneficios que quedan fuera de la decisión privada. La vacunación aporta protección a personas distintas de la vacunada. En producción, la I+D puede generar conocimientos que otros aprovechan. En estos ejemplos, el incentivo privado conduce a realizar menos actividad que la socialmente eficiente.","Para las vacunas, beneficio marginal social = beneficio marginal privado + beneficio marginal externo. En el gráfico de clase, la oferta y la demanda privadas se cruzan a 10 €. La curva de valor social se sitúa por encima de la demanda privada. Su cruce con la oferta da una cantidad eficiente mayor mientras el beneficio externo marginal sea positivo y se mantengan las demás condiciones."],"source":"86","page":73,"questions":[{"id":"7.4-c1","type":"comprension","prompt":"¿Quién recibe el beneficio externo en el caso de una vacuna?","options":["Quien se vacuna, en la parte de protección que recibe personalmente.","La farmacia, por el importe íntegro que cobra al vender la vacuna.","Personas distintas de la vacunada cuya exposición al contagio disminuye."]},{"id":"7.4-c2","type":"comprension","prompt":"¿Qué efecto de la I+D puede quedar fuera del cálculo empresarial?","options":["El valor del conocimiento que otras personas o empresas pueden aprovechar sin remunerar íntegramente al innovador.","El salario pactado que la empresa ya registra como coste de investigación.","Los ingresos por licencias que terceros ya pagan íntegramente al innovador."]},{"id":"7.4-c3","type":"comprension","prompt":"¿Cómo se construye la curva de valor social de la vacunación?","options":["Se resta el beneficio marginal externo de la disposición privada a pagar.","Se añade a cada unidad el beneficio total de todas las vacunas ya administradas.","Se añade a la disposición marginal privada a pagar el beneficio marginal para terceros en cada cantidad."]},{"id":"7.4-c4","type":"comprension","prompt":"¿Dónde se encuentra la cantidad eficiente en el gráfico de vacunas?","options":["En el cruce de la oferta con la curva de valor marginal social, a la derecha del equilibrio privado del ejemplo.","En el equilibrio privado, porque el propio precio incorpora toda protección frente al contagio.","A la izquierda del equilibrio privado, donde se administran menos dosis por el beneficio externo."]},{"id":"7.4-c5","type":"comprension","prompt":"¿Qué información falta para calcular cuántas vacunas adicionales convendría administrar?","options":["Solo la suma del ingreso de los fabricantes y el precio privado de 10 €.","Solo el gasto total en vacunas que ya han realizado los pacientes.","El tamaño del beneficio externo en el margen y las curvas relevantes de coste y valoración. El precio privado de 10 € resulta insuficiente."]},{"id":"7.4-d","type":"desarrollo","prompt":"Explica por qué maximizar los excedentes de pacientes y proveedores puede dejar sin administrar vacunas socialmente valiosas."}],"figure":{"src":"assets/figuras/7.4.svg","alt":"El beneficio externo eleva la cantidad eficiente Vacunación Valor o coste marginal (€/unidad) Q social Q privada Cantidad 10 Beneficio marginal privado Beneficio marginal social (incluye a terceros) Coste marginal Quedan sin intercambiar unidades cuyo beneficio social supera al coste. El área sombreada indica la ganancia que se pierde. Esquema sin escala de cantidades."}},{"id":"7.5","title":"Soluciones de mercado al problema de las externalidades","ideas":["El curso distingue cuatro vías. La adjudicación de derechos aclara quién puede usar un recurso o impedir una invasión. Con un derecho definido sobre la vivienda, por ejemplo, el vecino puede impedir el ruido o negociar una compensación por tolerarlo. Internalizar significa hacer que quien decide tenga en cuenta los costes y beneficios que recaían en otros.","En el teorema de Coase, derechos claramente definidos y costes de transacción suficientemente bajos permiten negociar una asignación eficiente. Identificar al causante, localizar a los afectados y cerrar el acuerdo cuesta recursos. Un vertido que va de una fábrica a una propiedad identificada facilita negociar. Miles de vehículos y víctimas dispersas de la contaminación urbana multiplican esos costes.","Los contratos de aseguramiento condicionan cada aportación a que se alcance un umbral colectivo. El curso ilustra el mecanismo con financiación colectiva de investigación y Kickstarter. Por último, la innovación puede reducir el daño o volver rentable su reducción. El profesor relaciona el aire urbano más limpio con la tecnología de los coches y la desindustrialización. Cita la caída de unos 250 a cero días anuales de aire insalubre en Chicago en la comparación de 1973 a 1996."],"source":"87–89","page":74,"questions":[{"id":"7.5-c1","type":"comprension","prompt":"¿Qué cambia para dos vecinos cuando se define quién puede impedir el ruido?","options":["Queda identificado el titular que puede exigir el cese o negociar el permiso y la compensación.","Los dos vecinos quedan obligados a acordar una compensación igual al valor de sus viviendas.","Se impone automáticamente el mismo nivel de ruido sea cual sea el coste de reducirlo."]},{"id":"7.5-c2","type":"comprension","prompt":"¿Qué dos condiciones destaca el teorema de Coase?","options":["Igualdad de ingresos entre las partes y un precio máximo fijado por la autoridad.","Propiedad pública del recurso y costes de negociación suficientemente altos.","Derechos de propiedad claramente delimitados y costes de negociación suficientemente bajos."]},{"id":"7.5-c3","type":"comprension","prompt":"¿Por qué es más fácil negociar un vertido entre dos fincas que la contaminación del tráfico urbano?","options":["Porque en dos fincas el daño de cualquier vertido es siempre despreciable.","Con dos partes identificadas cuesta menos determinar quién negocia y cerrar el acuerdo. En la ciudad hay numerosos emisores y afectados difíciles de identificar.","Porque ser propietario de una finca implica aceptar gratuitamente cualquier vertido de la finca vecina."]},{"id":"7.5-c4","type":"comprension","prompt":"¿Qué compromete al financiador en un contrato de aseguramiento?","options":["Su aportación se hace efectiva si se alcanza el umbral pactado de financiación colectiva.","Debe aportar aunque el proyecto no alcance la financiación mínima prevista.","Solo se compromete si el proyecto ya ha distribuido beneficios a todos sus financiadores."]},{"id":"7.5-c5","type":"comprension","prompt":"¿Cómo puede una innovación reducir una externalidad sin negociar con cada afectado?","options":["Basta con patentar la tecnología para que los terceros perjudicados reciban compensación.","Una tecnología que reduzca emisiones por unidad puede disminuir el daño durante la actividad ordinaria de productores y usuarios.","El abaratamiento del producto hace desaparecer por definición todo daño por unidad."]},{"id":"7.5-d","type":"desarrollo","prompt":"Compara la negociación de un vertido con la financiación colectiva de una investigación. ¿Qué obstáculo intenta superar cada mecanismo?"}]},{"id":"7.6","title":"Soluciones de gobierno al problema de las externalidades","ideas":["Los instrumentos pigouvianos corrigen el incentivo marginal de la actividad. En el modelo, el impuesto por unidad debe reflejar el daño marginal externo en la cantidad eficiente, y el subsidio por unidad, el beneficio marginal externo en esa cantidad. Ejemplos del curso son gravar la contaminación y subvencionar la I+D. Ambos instrumentos dejan margen para que los afectados ajusten cantidades.","El control directo impone cantidades, límites o conductas. El profesor contrapone la prohibición de música a mucho volumen después de las once de la noche al mandato de vacunación. El primer caso pretende reducir un coste externo y el segundo ampliar un beneficio externo.","La elección y el diseño de la intervención plantean un problema de información y otro de incentivos. Estimar cuánto daño evita una reducción adicional o cuánto beneficio genera una unidad más es difícil. Un grupo de interés también puede lograr que la regulación o la transferencia se diseñe en su favor. El profesor advierte que el coste del remedio puede superar el de la situación inicial."],"source":"89–90","page":75,"questions":[{"id":"7.6-c1","type":"comprension","prompt":"¿Cómo debería fijarse un impuesto pigouviano por unidad en el modelo?","options":["Para inducir la cantidad eficiente, debería reflejar el daño marginal externo en esa cantidad.","Para igualar la recaudación total con toda la facturación del productor.","Para igualar el impuesto al daño total del sector por cada unidad vendida."]},{"id":"7.6-c2","type":"comprension","prompt":"¿Qué magnitud guiaría el subsidio corrector a la investigación?","options":["El ingreso total del investigador por las licencias que ya cobra.","El coste fijo completo del laboratorio, repetido como subvención por cada unidad.","El beneficio marginal que la investigación proporciona a terceros y que no remunera el mercado en la cantidad eficiente."]},{"id":"7.6-c3","type":"comprension","prompt":"¿Qué distingue el control directo de un impuesto por unidad?","options":["El impuesto fija la cantidad exacta que debe producir cada empresa y el control solo fija el precio.","Ambos instrumentos fijan la misma cantidad a cada individuo con independencia de sus costes.","El control prescribe o prohíbe una conducta o cantidad. El impuesto modifica el coste de decidirla."]},{"id":"7.6-c4","type":"comprension","prompt":"¿Por qué prohibir ruido nocturno y exigir vacunación representan sentidos opuestos de intervención?","options":["La prohibición reduce una conducta con costes para otros. La obligación promueve otra que puede generar beneficios para terceros.","El ruido causa beneficios externos y la vacunación causa daños externos, por lo que se invierte el signo de las dos medidas.","Ambas medidas reducen el consumo de la actividad regulada por el mismo mecanismo."]},{"id":"7.6-c5","type":"comprension","prompt":"¿Qué problema de incentivos se añade al de calcular el daño externo?","options":["Quienes deciden la política pueden favorecer a grupos organizados y alejar el instrumento de su objetivo corrector.","Que la autoridad no conozca cuántas unidades se producirán, aunque sus incentivos estén perfectamente alineados.","Que falten mediciones del perjuicio por unidad, incluso con completa coincidencia de intereses."]},{"id":"7.6-d","type":"desarrollo","prompt":"Compara un impuesto a la contaminación con un límite directo y explica qué necesita saber y qué incentivos afronta la autoridad."}]},{"id":"7.6.1","title":"Foro 21: Soluciones de gobierno al problema de las externalidades","note":"Sin contenido en los archivos adjuntos."},{"id":"7.6.1.2","title":"Vídeo respuesta foro: Soluciones de gobierno al problema de las externalidades","note":"Sin contenido en los archivos adjuntos."}]},{"number":8,"title":"Bienes públicos y la tragedia de los comunes","items":[{"id":"8.0","title":"Introducción","note":"Presentación del tema en la p. 91. El marco conceptual se desarrolla en 8.1."},{"id":"8.1","title":"Los tipos de bienes","ideas":["La rivalidad en consumo pregunta si utilizar una unidad reduce la posibilidad de que otra persona la use. La exclusión pregunta si se puede impedir el acceso a quien no cumple una condición, por ejemplo el pago. Son dos propiedades independientes que permiten clasificar el bien según sus condiciones de acceso y uso.","Un pantalón es rival y excluible (bien privado). Una suscripción de música permite escuchar simultáneamente y restringir el acceso (bien club). El atún en un océano de libre pesca es rival y difícil de excluir (recurso común). La defensa de una ciudad protege simultáneamente a sus habitantes y es difícil excluir selectivamente a quien no haya pagado (bien público)."],"source":"91–92","page":76,"questions":[{"id":"8.1-c1","type":"comprension","prompt":"¿Qué observación permite reconocer la rivalidad de una unidad?","options":["Que el propietario pueda identificar a todos los usuarios que han pagado.","Que se pueda exigir una contraseña para acceder al servicio.","Que su uso por una persona reduce la cantidad disponible o la posibilidad de uso para otra."]},{"id":"8.1-c2","type":"comprension","prompt":"¿Cómo se comprueba la exclusión en el ejemplo de la música digital?","options":["El prestador puede condicionar el acceso al pago o a una cuenta autorizada.","Midiendo el coste marginal de transmitir una copia más de la canción.","Contando cuántas personas pueden escuchar la misma pista simultáneamente."]},{"id":"8.1-c3","type":"comprension","prompt":"¿Por qué un atún en un caladero abierto se clasifica como recurso común?","options":["Porque el propietario asigna cada atún a un comprador antes de que se capture y excluye al resto.","Porque capturarlo deja intacta la disponibilidad de ese mismo pez para los demás.","La captura de un pescador reduce las existencias para los demás y, en el ejemplo, es difícil impedir el acceso a la pesca."]},{"id":"8.1-c4","type":"comprension","prompt":"¿Por qué la defensa de una ciudad se presenta como bien público?","options":["Porque es fácil retirar la defensa a quien no pague y cada residente consume una unidad independiente.","Porque cualquier servicio prestado por el Estado es público con independencia de sus propiedades de uso.","Puede proteger a numerosos habitantes simultáneamente y resulta impracticable retirar la protección a habitantes concretos por falta de pago."]},{"id":"8.1-c5","type":"comprension","prompt":"¿Qué propiedad comparten unos pantalones y una suscripción digital, y en cuál difieren?","options":["Ambos son rivales y solo la suscripción permite excluir a usuarios.","En ambos casos se puede excluir a quien no paga. Solo los pantalones son rivales en el uso considerado.","Ninguno es excluible y solo la suscripción es rival."]},{"id":"8.1-d","type":"desarrollo","prompt":"Compara un caladero abierto y un servicio de música por suscripción a partir de las dos dimensiones de la clasificación."}],"table":[["Consumo","Exclusión posible","Exclusión difícil"],["Rival","Bien privado · pantalones","Recurso común · caladero"],["No rival","Bien club · música de pago","Bien público · defensa"]]},{"id":"8.2","title":"Los bienes privados versus los bienes públicos","ideas":["La posibilidad de excluir a quien no paga facilita que la venta de bienes privados financie su provisión. Los bienes públicos combinan consumo no rival y exclusión difícil. El usuario adicional recibe el servicio aunque deje el coste a otros. El oportunista o polizón disfruta del beneficio sin contribuir.","Si muchas personas adoptan esa conducta, la suma recaudada puede ser insuficiente para prestar o mantener el servicio, aunque el conjunto de usuarios lo valore. El profesor cita los impuestos para financiar la defensa y las restricciones al intercambio de archivos para proteger la propiedad intelectual como respuestas públicas. Los impuestos financian colectivamente y la regulación limita determinados usos."],"source":"92","page":77,"questions":[{"id":"8.2-c1","type":"comprension","prompt":"¿Cómo facilita la exclusión que se ofrezca un bien privado?","options":["Permite vincular el acceso al pago y recuperar por las ventas los costes de provisión.","Hace que el uso por una persona deje automáticamente disponible la misma unidad para otra.","Elimina el coste de los recursos utilizados para producir cada unidad."]},{"id":"8.2-c2","type":"comprension","prompt":"¿Qué conducta caracteriza a un polizón?","options":["Utiliza o disfruta un bien financiado por otras personas y evita aportar a sus costes cuando puede hacerlo.","Paga por un servicio que finalmente decide no utilizar.","Financia un servicio utilizado por otras personas sin beneficiarse personalmente."]},{"id":"8.2-c3","type":"comprension","prompt":"¿Por qué puede deteriorarse un servicio colectivo que los ciudadanos valoran?","options":["La dificultad de excluir impide físicamente que varias personas lo utilicen al mismo tiempo.","La valoración compartida obliga a utilizar el servicio hasta que desaparece toda disposición a pagar.","Porque la dificultad de excluir reduce el incentivo individual a contribuir y los ingresos pueden quedar por debajo del coste de provisión o mantenimiento."]},{"id":"8.2-c4","type":"comprension","prompt":"¿Cómo altera la financiación tributaria el problema de la defensa?","options":["Distribuye obligatoriamente su financiación sin tener que retirar la protección a quien elegiría no pagar una aportación voluntaria.","El impuesto permite retirar físicamente la protección únicamente a los residentes que no pagan.","La defensa se vuelve rival porque cada contribuyente adquiere una porción separada de protección."]},{"id":"8.2-c5","type":"comprension","prompt":"¿Con qué finalidad introduce el curso el ejemplo de los sitios de intercambio de archivos?","options":["Para ilustrar un impuesto que calcula el daño marginal de cada descarga individual.","Para ilustrar una regulación que restringe usos y protege la propiedad intelectual cuando resulta difícil controlar el acceso.","Para demostrar que los archivos digitales se agotan al copiarlos repetidamente."]},{"id":"8.2-d","type":"desarrollo","prompt":"Explica por qué el disfrute simultáneo de un servicio no garantiza su financiación. Aplica el razonamiento a la defensa."}]},{"id":"8.3","title":"Bienes club","ideas":["Un servicio audiovisual por suscripción es excluible y admite muchos espectadores simultáneos. En el ejemplo histórico de clase, el abono de Amazon cuesta 4,99 € al mes y atender a un usuario adicional tiene coste cercano a cero. Un espectador dispuesto a pagar más que ese coste y menos que la cuota quedaría excluido. En ese sentido hay consumo potencial que se pierde.","También hay costes fijos de producción. Los ingresos por encima del coste marginal permiten financiar nuevos programas, diversidad e innovación. El profesor juzga limitada la ineficiencia de acceso frente a esas ventajas. La exclusión mediante suscripción puede convertir emisiones de acceso abierto en bienes club. La publicidad constituye otra vía para financiar el contenido sin exigir el pago directo de cada espectador. El curso menciona la televisión y plataformas como Meta, TikTok o Google."],"source":"92–93","page":78,"questions":[{"id":"8.3-c1","type":"comprension","prompt":"¿Qué dos propiedades presenta una serie con acceso por suscripción?","options":["Es rival porque solo se admite a abonados y es no excluible porque el vídeo es digital.","Es no rival y también no excluible, aunque el prestador pueda bloquear a las personas sin cuenta.","La plataforma puede excluir a quien no está abonado y un espectador adicional puede verla simultáneamente con los demás."]},{"id":"8.3-c2","type":"comprension","prompt":"¿Qué coste de atender al último usuario compara el profesor con los 4,99 €?","options":["El coste marginal, que en el ejemplo es cero o próximo a cero.","El coste medio que resulta de dividir toda la producción de la serie entre los abonados que ya la ven.","El coste fijo total de producir la temporada para el catálogo."]},{"id":"8.3-c3","type":"comprension","prompt":"¿Qué espectador queda fuera pese a que servirle generaría una ganancia inmediata?","options":["Quien ya paga la cuota porque la valora por encima de los 4,99 €.","Aquel cuya disposición a pagar supera el coste marginal de atenderlo y queda por debajo de la cuota.","Quien valora el servicio menos que el coste adicional de atenderlo."]},{"id":"8.3-c4","type":"comprension","prompt":"¿Qué función cumplen los ingresos por encima del coste marginal?","options":["Sirven exclusivamente para cubrir el coste variable del último usuario aunque éste sea cero.","Ayudan a recuperar costes fijos y a sostener la producción de contenidos, la variedad y la innovación.","Son íntegramente beneficios netos desde el primer abonado, con independencia de los costes fijos."]},{"id":"8.3-c5","type":"comprension","prompt":"¿Cómo cambia la financiación cuando se utiliza publicidad?","options":["El contenido deja de tener costes fijos porque el vídeo incluye anuncios.","Los anunciantes pagan por llegar a la audiencia y el prestador puede permitir el acceso sin cobrar directamente a cada usuario.","El anunciante paga a cada espectador el importe de la suscripción y el prestador no recibe ingresos."]},{"id":"8.3-d","type":"desarrollo","prompt":"¿Bastaría conocer el coste de un espectador adicional para fijar la cuota de una plataforma? Justifica tu respuesta con el ejemplo del curso."}]},{"id":"8.4","title":"Recursos comunes: la tragedia de los comunes y la tragedia de los anticomunes","ideas":["En la tragedia de los comunes, descrita por Garrett Hardin en 1968, cada usuario de un recurso rival de libre acceso capta el beneficio de una unidad adicional y reparte el deterioro con los demás. El uso individualmente razonable puede agotar el recurso aunque todos prefieran conservarlo. Ejemplos del curso son la pesca, las calles con atascos, la escasez de aparcamiento o una cancha de acceso libre que acaba deteriorada. Se proponen derechos de propiedad delimitados, reglas de uso o impuestos que limiten la presión.","En la tragedia de los anticomunes, asociada a Michael Heller (1998), la fragmentación de facultades de decisión impide acordar un uso viable. Aquí la pérdida proviene de la infrautilización. El profesor señala zonas turísticas obsoletas de Canarias en las que la rehabilitación exige coordinar a propietarios y autoridades urbanísticas. En una vivienda con diez herederos, intereses como alquilarla, venderla u ocuparla pueden dejarla vacía. El número y la distribución de los derechos importan tanto como su existencia."],"source":"93–95","page":79,"questions":[{"id":"8.4-c1","type":"comprension","prompt":"¿Qué incentivo explica la sobrepesca en un caladero de acceso libre?","options":["Cada pescador soporta íntegramente el coste de disminuir las capturas futuras de todos sus competidores.","Cada pescador conserva en exclusiva para el futuro todos los peces que decide dejar hoy en el mar.","Cada pescador recibe el beneficio de su propia captura y comparte con otros el coste de reducir la población de peces."]},{"id":"8.4-c2","type":"comprension","prompt":"¿Cómo pueden calles y canchas ilustrar la tragedia de los comunes?","options":["El uso adicional restaura el pavimento o la cancha y aumenta la capacidad de uso de los demás.","El uso sin límites puede congestionar las calles o acelerar el desgaste de las instalaciones hasta reducir su utilidad para todos.","Las dos instalaciones ilustran exclusivamente la infrautilización porque cualquier vecino tiene poder individual de veto."]},{"id":"8.4-c3","type":"comprension","prompt":"¿Qué instrumentos de limitación del uso plantea el curso?","options":["Repartir premios por volumen de extracción y suprimir las reglas sobre los usos del recurso.","Asignar derechos de propiedad, introducir reglas de acceso o utilización y aplicar impuestos que reduzcan el consumo excesivo.","Eliminar los límites de acceso y subvencionar cada unidad adicional que se extraiga."]},{"id":"8.4-c4","type":"comprension","prompt":"¿Qué diferencia al caso de los diez herederos de la sobrepesca?","options":["La vivienda queda infrautilizada porque varios titulares discrepan sobre su destino. La pesca se agota por exceso de uso bajo acceso libre.","En el caladero sobran vetos que impiden pescar y en la vivienda falta el derecho a excluir intrusos.","En ambos casos hay sobreutilización física porque cualquiera puede explotar libremente la vivienda heredada."]},{"id":"8.4-c5","type":"comprension","prompt":"¿Qué dos clases de acuerdo pueden dificultar la rehabilitación turística en Canarias?","options":["El acuerdo entre titulares de derechos fragmentados y la coordinación con las administraciones cuando se requiere modificar el planeamiento.","Un pacto entre turistas sobre su gasto diario y otro entre huéspedes sobre la ocupación de las camas.","El acuerdo sobre el tipo de cambio y la negociación de un impuesto estatal sobre divisas."]},{"id":"8.4-d","type":"desarrollo","prompt":"Compara el deterioro de una cancha abierta con el de una vivienda heredada que permanece vacía. Relaciona el diagnóstico con los derechos de uso."}],"figure":{"src":"assets/figuras/8.4.svg","alt":"Un recurso puede perder valor por exceso o por falta de uso Anticomunes Varios titulares pueden vetar el uso. Comunes Cada usuario puede extraer más. Infrautilización Uso eficiente Sobreutilización Diez herederos discrepan sobre el destino de una vivienda que permanece vacía. En un caladero abierto, cada pescador comparte con otros el coste de su captura."}},{"id":"8.4.1","title":"Foro 22: Tragedia de los comunes y de los anticomunes","note":"Sin contenido en los archivos adjuntos."},{"id":"8.4.2","title":"Solución foro: Tragedia de los comunes y de los anticomunes","note":"Sin contenido en los archivos adjuntos."}]},{"number":9,"title":"Fallos de gobierno: Causas y tipos","items":[{"id":"9.0","title":"Introducción","ideas":["La introducción pregunta si el gobierno puede corregir un fallo de mercado y propone evaluar sus propios fallos de coordinación. Examina las condiciones en que una decisión pública puede mejorar una asignación y las dificultades de llevarla a la práctica.","El profesor distribuye los mecanismos en dos familias. Bajo información sitúa el conocimiento imperfecto, la miopía política, los objetivos contradictorios y las consecuencias no deseadas. Bajo incentivos sitúa el interés electoral de los políticos, la captura por grupos organizados y los intereses propios de la burocracia."],"source":"96","page":80,"questions":[{"id":"9.0-c1","type":"comprension","prompt":"¿Qué comparación plantea el módulo tras estudiar los fallos de mercado?","options":["Comparar cualquier mercado real con una intervención ideal que conoce perfectamente todas las preferencias.","Comparar el resultado del mercado con el resultado alcanzable mediante una intervención pública, considerando las limitaciones de esta última.","Comparar dos mercados exclusivamente por la recaudación que aportan a la administración."]},{"id":"9.0-c2","type":"comprension","prompt":"¿Qué dos problemas generales ordenan el temario?","options":["Obtener información suficiente para coordinar los recursos y lograr que quienes deciden y ejecutan tengan incentivos adecuados.","Calcular costes fijos y variables de una empresa con información e incentivos ya resueltos.","Financiar exportaciones y ajustar el tipo de cambio de la moneda."]},{"id":"9.0-c3","type":"comprension","prompt":"¿En qué familia sitúa el profesor la dificultad de prever reacciones de los ciudadanos?","options":["En la burocratización, incluso cuando la reacción imprevista precede al diseño del procedimiento.","En los problemas de información, bajo las consecuencias inesperadas.","En la captura regulatoria, aunque el error se deba exclusivamente a falta de conocimiento."]},{"id":"9.0-c4","type":"comprension","prompt":"¿Qué actores aparecen en los tres mecanismos de incentivos?","options":["Importadores, exportadores y agentes de cambio que determinan el precio de las divisas.","Consumidores finales, proveedores de materias primas y bancos prestamistas.","Los políticos que buscan apoyo electoral, los grupos organizados que presionan y los agentes de la burocracia que ejecutan las decisiones."]},{"id":"9.0-c5","type":"comprension","prompt":"¿Por qué una política bien intencionada puede tener un resultado deficiente?","options":["Porque una intención favorable implica necesariamente trabajar con rendimientos marginales negativos.","Sus responsables pueden desconocer preferencias y reacciones, o la ejecución puede responder a incentivos distintos de los declarados.","Porque cualquier política que persiga un fin público es por definición ineficiente, con independencia de sus resultados."]},{"id":"9.0-d","type":"desarrollo","prompt":"Explica por qué identificar un fallo de mercado es solo el primer paso para valorar una intervención pública."}]},{"id":"9.1","title":"Los fallos de gobierno: un problema de información y de incentivos","ideas":["El problema de información consiste en descubrir qué producir y dónde y cuándo usar recursos escasos. El de incentivos consiste en que las personas tengan motivos para realizar la tarea que se les encomienda. Disponer de conocimiento y querer emplearlo para un fin dado son requisitos distintos.","El mapa del curso asocia información imperfecta con preferencias desconocidas, miopía con horizontes cortos, conflictos con la ausencia de una ordenación social consistente y consecuencias imprevistas con los efectos que escapan a la previsión. En el lado de los incentivos, los responsables pueden buscar votos, favorecer a los grupos que presionan o ver alteradas sus decisiones por quienes las ejecutan. En casos concretos varios mecanismos pueden operar simultáneamente."],"source":"96","page":81,"questions":[{"id":"9.1-c1","type":"comprension","prompt":"¿Qué pregunta productiva resume el problema de información?","options":["Qué bienes y servicios conviene producir y cómo asignarles los recursos disponibles según las preferencias y los costes.","¿Qué incentivo electoral tiene un político para permanecer en el cargo?","¿Qué premio por desempeño motivaría a quien debe ejecutar la decisión?"]},{"id":"9.1-c2","type":"comprension","prompt":"¿Qué pregunta práctica resume el problema de incentivos?","options":["¿Cuánto acero y cuánta madera hay almacenados en cada provincia?","¿Qué preferencias y ordenaciones de bienes desconocemos antes de producir?","Qué motiva a cada agente a esforzarse y actuar en la dirección que requiere el objetivo declarado."]},{"id":"9.1-c3","type":"comprension","prompt":"¿Por qué conocer las necesidades de los ciudadanos no garantiza satisfacerlas?","options":["El decisor puede obtener ventajas electorales o de otro tipo al elegir una política distinta de la aconsejada por esa información.","Porque las preferencias conocidas garantizan que el decisor obedecerá, pero los recursos dejan de ser escasos.","Porque saber qué necesitan los ciudadanos obliga al decisor a anteponer siempre esa necesidad a su interés."]},{"id":"9.1-c4","type":"comprension","prompt":"¿Cómo se distinguen un error de previsión y una captura regulatoria?","options":["En el primero se anticipan mal las consecuencias. En la captura, un grupo consigue orientar la norma hacia su propio interés.","El error de previsión nace de un privilegio normativo y la captura consiste en una estimación estadística desviada.","Son sinónimos: los dos términos describen solo un cálculo incorrecto de la demanda."]},{"id":"9.1-c5","type":"comprension","prompt":"¿Cómo puede una misma decisión involucrar ambos problemas?","options":["Una autoridad puede estimar mal las preferencias de la población y además favorecer en la medida a un sector con capacidad de presión.","Basta con que la misma estimación de costes sea errónea dos veces, aunque los incentivos estén alineados.","Solo si dos autoridades deciden por separado, ya que cada decisión individual puede tener un único problema."]},{"id":"9.1-d","type":"desarrollo","prompt":"Explica los dos problemas de coordinación utilizando la decisión de construir una escuela. Distingue qué tendría que conocer el decisor y qué podría moverle a actuar."}]},{"id":"9.2","title":"Información imperfecta","ideas":["El gobierno carece de un inventario completo de las preferencias individuales. En el argumento del curso, para muchos servicios públicos faltan precios de mercado de los productos, referencias comparables para todos los costes de los insumos, la finalidad de obtener beneficios y la presión competitiva que somete los planes a revisión. De ahí la dificultad de realizar cálculo económico sobre alternativas.","La escuela ilustra qué información se necesita incluso después de aprobar la finalidad educativa. Se debe decidir cuántos centros construir, dónde, con qué materiales, para cuántos alumnos y con qué plantilla. Una asignación equivocada puede consumir recursos cuyo valor en otros usos sea mayor. Conocer el coste presupuestario por sí solo no revela cómo valoran los usuarios las diferentes opciones."],"source":"97","page":82,"questions":[{"id":"9.2-c1","type":"comprension","prompt":"¿Qué conocimiento de los ciudadanos falta para decidir por ellos?","options":["Únicamente el domicilio fiscal de cada contribuyente, con independencia de qué alternativas valore.","Solo la renta total de la sociedad, que permite deducir una ordenación individual única.","El conjunto de sus preferencias, incluidas las alternativas que preferirían en distintas circunstancias y sus prioridades relativas."]},{"id":"9.2-c2","type":"comprension","prompt":"¿Qué señales pueden faltar al evaluar un servicio público sin ventas de mercado?","options":["Precios de sus prestaciones y referencias de mercado comparables para todos los recursos utilizados.","El recuento administrativo de plazas aunque ya esté registrado en el presupuesto.","El nombre del organismo que ejecuta el servicio aunque figure en su organigrama."]},{"id":"9.2-c3","type":"comprension","prompt":"¿Qué dos disciplinas empresariales añade el profesor a esas señales?","options":["La ausencia de pérdidas y la protección garantizada frente a nuevos participantes.","El reparto por cuotas electorales y el cumplimiento de un programa de partido.","La búsqueda de beneficios y la competencia, que proporcionan incentivos para revisar planes que no recuperan sus costes."]},{"id":"9.2-c4","type":"comprension","prompt":"¿Qué decisiones quedan abiertas una vez que se ha decidido construir escuelas?","options":["El número y la ubicación de centros, los materiales, las plazas de cada uno y la cantidad de profesores.","Únicamente el currículo escolar, porque el número y el tamaño de los centros se deducen del precio de los materiales.","Solo la fecha de la inauguración, porque la decisión de construir fija automáticamente plazas, personal y ubicación."]},{"id":"9.2-c5","type":"comprension","prompt":"¿Por qué el coste monetario de construir una escuela no resuelve el cálculo completo?","options":["Porque todos los usos alternativos de los recursos tienen el mismo valor cuando la escuela es pública.","Porque el coste de construcción permite saber por sí solo la utilidad total que obtendrá cada familia.","Indica parte de lo que cuesta la obra, pero falta comparar su valor para los usuarios con el de otras asignaciones posibles de esos recursos."]},{"id":"9.2-d","type":"desarrollo","prompt":"Explica el problema de cálculo que plantea elegir entre dos ubicaciones para una escuela pública."}]},{"id":"9.3","title":"La miopía de la política","ideas":["El horizonte electoral introduce un motivo para dar prioridad a resultados visibles antes de la próxima votación. La clase toma como referencia ciclos de unos cuatro años. Una decisión puede ser temporalmente inconsistente si el beneficio inmediato exige sacrificar fines de más largo alcance.","El ejemplo es contratar obras públicas para reducir el desempleo antes de las elecciones aceptando aumentos anuales de deuda. La disminución presente del paro y la carga que se traslada al futuro deben evaluarse conjuntamente. El calendario por sí solo no permite concluir que cualquier obra resulte ineficiente."],"source":"97","page":83,"questions":[{"id":"9.3-c1","type":"comprension","prompt":"¿Qué horizonte político utiliza el profesor para ilustrar la miopía?","options":["La vida útil de la obra, fijada en el ejemplo en cuarenta años.","El período de devengo de un impuesto, que en el ejemplo es un trimestre.","El período hasta las siguientes elecciones, que en el ejemplo ronda cuatro años."]},{"id":"9.3-c2","type":"comprension","prompt":"¿Por qué un gobernante puede preferir una obra de resultado rápido?","options":["Los votantes pueden observar antes de votar el empleo o la actividad que genera y premiarlo en las urnas.","Porque sus costes de financiación desaparecen cuando la obra se termina antes de votar.","Porque un proyecto de ejecución rápida tiene garantizada una utilidad social mayor que cualquier proyecto lento."]},{"id":"9.3-c3","type":"comprension","prompt":"¿Qué significa incoherencia intertemporal en este ejemplo?","options":["Que un euro actual y otro futuro tienen exactamente el mismo uso en cualquier circunstancia.","Que toda inversión de largo plazo se financia obligatoriamente con impuestos del año presente.","Que al escoger un resultado inmediato se sacrifican prioridades de largo plazo que también deberían guiar la asignación."]},{"id":"9.3-c4","type":"comprension","prompt":"¿Qué coste futuro destaca el caso de las obras públicas?","options":["El menor desembolso contable que se produce al sumar puestos de trabajo.","El aumento de deuda pública asociado a financiarlas y las cargas que ese endeudamiento compromete para ejercicios posteriores.","La pérdida del derecho a utilizar la infraestructura inmediatamente después de las elecciones."]},{"id":"9.3-c5","type":"comprension","prompt":"¿Qué dato adicional al empleo creado hace falta para juzgar un proyecto concreto?","options":["Su utilidad y costes a lo largo del tiempo, incluidas la financiación y las oportunidades que se sacrifican.","Solo el número de contratos firmados, aunque se desconozcan su coste y utilidad.","Solo cuántos votos se espera ganar mediante la inauguración de la obra."]},{"id":"9.3-d","type":"desarrollo","prompt":"Analiza una obra iniciada poco antes de unas elecciones que reduce el paro y aumenta la deuda. ¿Qué hace falta para valorar la decisión?"}],"figure":{"src":"assets/figuras/9.3.svg","alt":"El calendario electoral y el coste de una obra pública Decisión El gobierno contrata una obra pública. Antes de las elecciones La contratación puede reducir el desempleo visible. Ejercicios posteriores Si se financió con deuda, habrá que atender los pagos. Secuencia del ejemplo de clase"}},{"id":"9.4","title":"Conflictos de intereses","ideas":["Cuando todos los recursos son compartidos, una decisión mayoritaria sobre sus usos subordina parte de los fines individuales a los de un subconjunto de la sociedad. ¿Cómo agregar preferencias distintas en una ordenación social coherente? El curso invoca el teorema de imposibilidad de Arrow. Para tres o más opciones, una regla general de agregación ordinal no puede reunir a la vez dominio no restringido, unanimidad de Pareto, ausencia de dictador e independencia de alternativas irrelevantes y garantizar una ordenación social coherente.","Dominio no restringido admite cualquier combinación de ordenaciones individuales. Pareto respeta una preferencia unánime. No dictadura impide imponer sistemáticamente el orden de una persona. Independencia exige que la comparación social entre dos alternativas dependa de cómo se ordenan entre sí. Sen muestra una tensión adicional entre el criterio de Pareto y un margen mínimo de decisión individual sobre ciertos asuntos. El profesor conecta estas dificultades con objetivos políticos contradictorios, como gravar el consumo de tabaco y subvencionar su producción."],"source":"97–98","page":84,"questions":[{"id":"9.4-c1","type":"comprension","prompt":"¿Qué dificultad aparece al trasladar preferencias individuales a una preferencia colectiva?","options":["Que las preferencias individuales dejan de poder ordenarse cuando hay al menos tres opciones.","Que una ordenación social coherente no puede satisfacer simultáneamente todas las condiciones de agregación que establece el teorema de Arrow.","Que basta conocer qué alternativa prefiere la persona con renta mediana para obtener el orden de toda la sociedad."]},{"id":"9.4-c2","type":"comprension","prompt":"¿Qué exigen el dominio no restringido y la ausencia de dictador?","options":["Admitir cualquier perfil de ordenaciones individuales y evitar que una sola persona determine siempre el resultado social.","Limitar los perfiles admisibles a los unánimes y dar un voto decisivo al candidato más votado.","Admitir solo preferencias idénticas y garantizar que el votante más informado decida todos los empates y desacuerdos."]},{"id":"9.4-c3","type":"comprension","prompt":"¿Qué significan unanimidad de Pareto e independencia de alternativas irrelevantes?","options":["Si todos prefieren A a B, la sociedad debe situar A por encima de B. La comparación colectiva entre A y B debe depender solo de cómo los individuos ordenan esas dos opciones entre sí.","Pareto concede veto individual sobre toda comparación y la independencia obliga a elegir por sorteo.","Pareto exige igualar los ingresos y la independencia exige contar los votos favorables a todas las demás alternativas."]},{"id":"9.4-c4","type":"comprension","prompt":"¿Qué tensión destaca el resultado de Sen tal como se introduce en clase?","options":["La dificultad de garantizar a la vez el criterio de Pareto y un ámbito mínimo de decisión individual para todos los perfiles de preferencias.","La incompatibilidad entre celebrar elecciones periódicas y proteger el sufragio universal.","La imposibilidad de que una decisión económica respete simultáneamente cualquier contrato privado y cualquier presupuesto equilibrado."]},{"id":"9.4-c5","type":"comprension","prompt":"¿Por qué el ejemplo del tabaco ilustra objetivos públicos contradictorios?","options":["Porque se aplican dos instrumentos que impiden simultáneamente producir y consumir tabaco.","Porque ambas medidas subvencionan por igual al consumidor y al productor de tabaco.","Gravar el consumo busca desincentivarlo, mientras que subvencionar la producción favorece la actividad del sector que lo suministra."]},{"id":"9.4-d","type":"desarrollo","prompt":"Relaciona el problema de agregar preferencias con las dos políticas sobre el tabaco, distinguiendo el teorema formal de su ilustración política."}]},{"id":"9.5","title":"Consecuencias inesperadas","ideas":["La clase distingue lo que sabemos que sabemos, las lagunas que reconocemos, lo que sabemos sin ser conscientes de ello y aquello que ni siquiera sabemos que ignoramos. Esta última categoría dificulta la previsión. Además, los ciudadanos reaccionan a las normas y esas respuestas cambian el resultado de la política.","Si la autoridad sube un impuesto esperando mayor recaudación, puede producirse más evasión o una reducción de los ingresos sujetos al gravamen. Recaudación = tipo × base efectivamente gravada, en el ejemplo simplificado de un tipo proporcional. El efecto final depende de cuánto cambie la base. Podría aumentar menos de lo esperado o incluso caer."],"source":"98","page":85,"questions":[{"id":"9.5-c1","type":"comprension","prompt":"¿Qué distingue una laguna reconocida de una desconocida por el propio decisor?","options":["La diferencia depende del coste oficial del dato y no de que el decisor sea consciente de su ausencia.","En la laguna reconocida se conoce la respuesta exacta y en la desconocida solo falta publicarla.","En la primera se sabe qué información falta. En la segunda se ignora incluso que hay algo relevante por averiguar."]},{"id":"9.5-c2","type":"comprension","prompt":"¿Por qué la reacción de los afectados importa para valorar una medida?","options":["Porque una vez aprobada una norma el resultado económico coincide por definición con su objetivo declarado.","Porque las personas mantienen siempre fijas las cantidades aunque cambien los incentivos.","Porque ajustan su conducta ante el cambio de incentivos y alteran el resultado que se esperaba manteniéndola constante."]},{"id":"9.5-c3","type":"comprension","prompt":"¿Qué dos reacciones menciona el profesor ante una subida de impuestos?","options":["Aumentar los ingresos declarados para reducir el impuesto y desplazar hacia adelante el calendario electoral.","Aumentar la evasión fiscal o reducir voluntariamente los ingresos sujetos al gravamen.","Mantener obligatoriamente fija la base y exigir una devolución igual al aumento del tipo."]},{"id":"9.5-c4","type":"comprension","prompt":"¿Cómo se expresa la recaudación en el ejemplo de un impuesto proporcional?","options":["Como el producto del tipo por la base efectivamente gravada.","Dividiendo la base efectiva por el tipo impositivo.","Multiplicando la cuota por unidad por la base del año anterior, incluso si cambia la base actual."]},{"id":"9.5-c5","type":"comprension","prompt":"¿En qué circunstancia recaudaría menos la administración después de elevar el tipo?","options":["Si la base gravada se reduce lo suficiente para que el nuevo producto del tipo por la base sea menor que el anterior.","Si la base permanece constante y aumenta el tipo positivo que se aplica.","Si la base gravada aumenta y también aumenta el tipo aplicado sobre ella."]},{"id":"9.5-d","type":"desarrollo","prompt":"Reconstruye la previsión que puede fallar cuando se eleva un tipo impositivo para recaudar más. Explica por qué el signo del resultado queda abierto."}]},{"id":"9.6","title":"El propio interés","ideas":["El profesor aplica el análisis marginal al político. Permanecer en el cargo o alcanzarlo proporciona un beneficio personal o partidista. En el modelo presentado, las medidas se seleccionan también por el efecto esperado sobre los votos y la probabilidad de reelección.","Prometer una subvención, aumentar las contrataciones públicas o aprobar una regulación que proteja a un oligopolio puede movilizar a grupos beneficiados. El curso describe estas acciones como formas indirectas de comprar apoyo político. Evaluar el mecanismo exige distinguir la conveniencia electoral de la utilidad de la misma medida para quienes soportan su coste."],"source":"99","page":86,"questions":[{"id":"9.6-c1","type":"comprension","prompt":"¿Qué objetivo se atribuye al político en el modelo del vídeo?","options":["Alcanzar o conservar el poder aumentando los votos y su probabilidad de reelección.","Mantener invariable el número de votantes que participan, sea cual sea el respaldo obtenido.","Maximizar el excedente total aunque pierda sus posibilidades de ocupar el cargo, por definición del modelo."]},{"id":"9.6-c2","type":"comprension","prompt":"¿Cómo se aplica el análisis marginal a una decisión política?","options":["Se comparan las ventajas y los costes adicionales de la medida, incluidos apoyos electorales ganados y perdidos.","Comparando los costes medios de gobiernos anteriores sin considerar los efectos adicionales de la decisión.","Sumando todos los votos de la elección anterior sin estimar qué cambia al aprobar una medida."]},{"id":"9.6-c3","type":"comprension","prompt":"¿Por qué una subvención puede generar apoyo electoral?","options":["Porque al concederse una ayuda se extinguen automáticamente todos los costes fiscales para los votantes.","Porque los beneficiarios están legalmente obligados a votar por quien haya aprobado la transferencia.","Los beneficiarios anticipan una transferencia y pueden apoyar a quien promete aprobarla o mantenerla."]},{"id":"9.6-c4","type":"comprension","prompt":"Además de subvenciones, ¿qué instrumentos menciona el profesor?","options":["El trueque entre particulares y los acuerdos de intercambio de divisas entre empresas.","La fijación del tipo de cambio por los turistas y la eliminación de toda regulación sectorial.","La contratación de nuevos funcionarios y las regulaciones que protegen a empresas oligopólicas."]},{"id":"9.6-c5","type":"comprension","prompt":"¿Cómo podría diferir la valoración del político de la de otros ciudadanos?","options":["El político valora el apoyo recibido, mientras otros ciudadanos pueden asumir costes sin obtener una ventaja equivalente.","El político soporta siempre en su patrimonio la totalidad del coste presupuestario y los ciudadanos nunca lo pagan.","Todos asignan el mismo valor al beneficio político de ganar un voto, aunque no participen en la candidatura."]},{"id":"9.6-d","type":"desarrollo","prompt":"Analiza una promesa de subvención desde el interés propio del candidato y desde la perspectiva de los ciudadanos afectados."}]},{"id":"9.7","title":"La captura de rentas","ideas":["Una licencia, subvención, barrera de entrada o disposición tributaria puede elevar los ingresos de algunos agentes a costa de otros. La captura de rentas consiste en emplear recursos para conseguir ese trato privilegiado por vía política. Si los intereses del grupo orientan las decisiones del regulador encargado de supervisarlo, se habla de captura regulatoria.","La influencia puede ejercerse por vías legales o ilegales. El ejemplo de clase es la normativa bancaria diseñada conforme a los intereses de entidades establecidas. Si dificulta la entrada de competidores, preserva una ventaja para los bancos existentes y altera las opciones disponibles para clientes y aspirantes."],"source":"99","page":87,"questions":[{"id":"9.7-c1","type":"comprension","prompt":"¿Qué hace que una decisión normativa tenga valor económico para un grupo?","options":["Que toda norma se publique con un coste de impresión mayor que cero, aunque no cambie las oportunidades del grupo.","Puede conceder una transferencia, rebajarle cargas o restringir la competencia, elevando así sus ventajas esperadas.","Que se atribuya el mismo valor privado a cualquier norma, incluso a dos que afectan al grupo en sentidos opuestos."]},{"id":"9.7-c2","type":"comprension","prompt":"¿Qué instrumentos menciona el curso al explicar la captura de rentas?","options":["Mejoras del diseño y de la atención al cliente financiadas íntegramente con ventas competitivas.","Permutas voluntarias entre vecinos y acuerdos privados de especialización sin intervención de la autoridad.","Subvenciones, licencias, barreras de entrada e impuestos que redistribuyen costes y ventajas entre agentes."]},{"id":"9.7-c3","type":"comprension","prompt":"¿Cómo se diferencia obtener una renta política de ganar clientes mediante una mejora del producto?","options":["La renta deriva del privilegio conseguido de la autoridad. La mejora del producto busca ingresos al ofrecer algo que los compradores valoran más.","Las dos nacen necesariamente de una reducción comprobada del coste productivo de la empresa.","La renta política procede de servir mejor al comprador y la mejora del producto requiere una licencia exclusiva estatal."]},{"id":"9.7-c4","type":"comprension","prompt":"¿Requiere toda presión de un grupo de interés un pago ilegal?","options":["Ninguna presión política puede implicar un pago ilegal, porque todos los grupos deben estar registrados.","No. El curso contempla tanto actuaciones legales de presión como prácticas ilegales.","Sí. Por definición solo existe presión política si se prueba un soborno."]},{"id":"9.7-c5","type":"comprension","prompt":"¿Qué indicio de captura presenta el ejemplo bancario?","options":["La reducción de costes de un banco que le permite competir mejor sin trato normativo diferencial.","La entrada libre de nuevos bancos por eliminación de los privilegios de los establecidos.","Una regulación adaptada a las entidades ya establecidas que restringe la entrada o la competencia en su favor."]},{"id":"9.7-d","type":"desarrollo","prompt":"Explica por qué un banco ya instalado podría dedicar recursos a influir en una norma de entrada y qué efectos tendría para otros agentes."}]},{"id":"9.8","title":"La burocratización","ideas":["Quien decide una política y quien la ejecuta pueden tener prioridades diferentes. En términos de agencia, el responsable político delega en funcionarios que conocen mejor la aplicación cotidiana. Pueden aplicar una medida de forma distinta a la prevista, bloquearla u ocultar o presentar selectivamente la información de ejecución.","El profesor utiliza las protestas de médicos de Madrid de 2014 contra la privatización de la gestión hospitalaria para ilustrar el poder de los ejecutores de oponerse a una política. La asimetría informativa dificulta supervisar sus actuaciones. Una respuesta es multiplicar controles y procedimientos internos. Estos consumen tiempo y recursos, aumentan el coste de transacción de decidir y ejecutar y pueden generar burocratización."],"source":"99–100","page":88,"questions":[{"id":"9.8-c1","type":"comprension","prompt":"¿Quién delega y quién actúa como agente en el ejemplo del curso?","options":["Los responsables políticos delegan la ejecución en funcionarios o empleados públicos que actúan como agentes.","Los clientes de empresas privadas delegan la aprobación del presupuesto en los proveedores.","Los empleados públicos delegan en los votantes la ejecución cotidiana de los programas."]},{"id":"9.8-c2","type":"comprension","prompt":"¿Qué ventaja informativa suele tener el ejecutor?","options":["Recibe una copia del programa electoral y por esa sola razón conoce menos de la aplicación que cualquier votante.","Conoce con más detalle las condiciones reales de aplicación y puede controlar parte de la información que recibe el responsable político.","Puede conocer de manera perfecta todas las preferencias futuras de los ciudadanos."]},{"id":"9.8-c3","type":"comprension","prompt":"¿Qué vías de desviación de la política se describen?","options":["Cumplir exactamente la orden y transmitir todos los resultados fielmente en el plazo previsto.","Bloquear su aplicación, ejecutarla de forma distinta a lo previsto u ocultar o seleccionar la información que se transmite.","Aumentar la competencia entre empresas mediante decisiones privadas ajenas a la aplicación de la política."]},{"id":"9.8-c4","type":"comprension","prompt":"¿Qué función tienen las protestas sanitarias madrileñas de 2014 en la exposición?","options":["Probar que el nivel de coste sanitario identifica por sí solo la mejor modalidad de gestión.","Ilustran, en la interpretación del profesor, la capacidad de quienes ejecutan un servicio para oponerse a una decisión sobre su gestión.","Medir el daño marginal de la congestión urbana para calcular un peaje."]},{"id":"9.8-c5","type":"comprension","prompt":"¿Cómo pueden los esfuerzos de supervisión favorecer la burocratización?","options":["Eliminan todo procedimiento interno porque los supervisores sustituyen a todos los ejecutores.","Reducen los costes de tramitación a cero en cuanto se introduce una comprobación por escrito.","Añaden procedimientos y comprobaciones internas que consumen recursos y elevan los costes de tramitar cada decisión."]},{"id":"9.8-d","type":"desarrollo","prompt":"Explica por qué aumentar los procedimientos internos puede mejorar la supervisión y, al mismo tiempo, encarecer la ejecución de una política."}]},{"id":"9.9","title":"Foro 23: Fallos de gobierno","note":"Sin contenido en los archivos adjuntos."},{"id":"9.9.1","title":"Solución foro: Fallos de gobierno","note":"Sin contenido en los archivos adjuntos."}]},{"number":10,"title":"Fallos de gobierno: Los problemas de la democracia","items":[{"id":"10.0","title":"Introducción","ideas":["La elección pública (Public Choice) aplica el razonamiento económico al comportamiento político. Pregunta qué incentivos tienen los votantes, los cargos electos, los empleados públicos y los grupos de interés, qué saben y cómo interactúan. El dilema que plantea el profesor es por qué persisten políticas que, en los modelos estudiados, reducen las ganancias del intercambio.","Una medida puede resultar beneficiosa para quienes deciden o se organizan para promoverla aunque tenga un coste agregado. Distinguir esa explicación causal de una valoración ética permite analizar por separado qué consecuencias tiene la medida, quién la apoya y qué objetivos considera deseables."],"source":"111","page":89,"questions":[{"id":"10.0-c1","type":"comprension","prompt":"¿Cuál es el objeto de la elección pública?","options":["La determinación del precio de los bienes privados sin considerar las instituciones colectivas.","El comportamiento de los participantes en las decisiones colectivas, estudiado con las herramientas de la economía.","El diseño de la papeleta electoral mediante criterios exclusivos de técnica jurídica."]},{"id":"10.0-c2","type":"comprension","prompt":"¿Qué cuatro grupos examina la introducción?","options":["Proveedores, mayoristas, minoristas y compradores finales.","Votantes, políticos, empleados públicos y grupos de interés.","Importadores, exportadores, accionistas y acreedores."]},{"id":"10.0-c3","type":"comprension","prompt":"¿Cómo se formula el problema de la alineación de intereses?","options":["Se pregunta qué reglas hacen que perseguir objetivos propios conduzca a resultados que también beneficien a otras personas.","Se pregunta cómo obligar a todos los individuos a compartir exactamente las mismas preferencias.","Se pregunta qué volumen de votos transforma automáticamente cualquier objetivo privado en bienestar social."]},{"id":"10.0-c4","type":"comprension","prompt":"¿Por qué puede persistir un control de precios costoso?","options":["Porque una vez aprobado, cualquier control de precios elimina todas las pérdidas de intercambio.","Porque el coste total desaparece si el control se aprueba por mayoría absoluta.","Quienes obtienen ventajas electorales o materiales pueden tener incentivos para mantenerlo aunque otras personas soporten pérdidas."]},{"id":"10.0-c5","type":"comprension","prompt":"¿Qué pregunta añadiría un juicio ético al análisis de incentivos?","options":["Preguntaría si el objetivo o la distribución del resultado son deseables, aun conociendo las consecuencias económicas de la política.","Qué porcentaje de beneficiarios participará en las próximas elecciones.","Cuánto gana en votos el grupo que recibe una ventaja regulatoria."]},{"id":"10.0-d","type":"desarrollo","prompt":"Explica cómo abordaría la elección pública la permanencia de una medida que reduce las ganancias del intercambio."}]},{"id":"10.1","title":"No existe el interés público","ideas":["Una preferencia individual puede ser transitiva. Si una persona prefiere A a B y B a C, también prefiere A a C. En la paradoja de Condorcet, tres votantes ordenan las opciones de forma transitiva: A > B > C, B > C > A y C > A > B. Sin embargo, en comparaciones de dos en dos, A vence a B, B vence a C y C vence a A, siempre por dos votos contra uno.","El resultado final puede depender del orden de las votaciones. El teorema de imposibilidad de Arrow es más general: con tres o más alternativas no existe una regla de agregación que, para todos los perfiles, satisfaga simultáneamente ciertas condiciones de equidad y coherencia. La clase cuestiona que la suma de votos revele una voluntad colectiva única."],"source":"111–112","page":90,"questions":[{"id":"10.1-c1","type":"comprension","prompt":"¿Qué significa que una ordenación sea transitiva?","options":["Si A se prefiere a B y B a C, entonces A se prefiere a C.","Si A se prefiere a B y B a C, entonces C debe preferirse a A.","Si A se prefiere a B, B debe preferirse también a A con la misma intensidad."]},{"id":"10.1-c2","type":"comprension","prompt":"¿Quiénes sostienen la mayoría a favor de A frente a B?","options":["Los votantes primero y segundo, porque el segundo coloca A antes que B.","Los votantes primero y tercero. Ambos colocan A por delante de B.","Los votantes segundo y tercero, porque el primero coloca B antes que A."]},{"id":"10.1-c3","type":"comprension","prompt":"¿Qué opción vence a A y con qué votos?","options":["C vence a A por los votos segundo y tercero.","B vence a A con los votos primero y tercero.","C vence a A con los votos primero y segundo."]},{"id":"10.1-c4","type":"comprension","prompt":"Si primero se vota entre A y B, ¿qué opción gana al enfrentarse después a C?","options":["A vence a B, pero C vence después a A. El resultado final es C.","A, porque ganar la primera votación obliga a conservar la mayoría en la segunda.","B, porque se enfrenta a C pese a haber perdido la primera votación."]},{"id":"10.1-c5","type":"comprension","prompt":"¿Qué relación hay entre el ejemplo y el teorema de Arrow?","options":["El ciclo ilustra un problema concreto de la regla mayoritaria. Arrow demuestra una incompatibilidad más general entre propiedades exigibles a una regla de agregación.","El ejemplo prueba que todas las elecciones con tres opciones terminan siempre en un ciclo.","El ciclo demuestra que ninguna persona puede tener preferencias individuales transitivas."]},{"id":"10.1-d","type":"desarrollo","prompt":"Reconstruye el ciclo de Condorcet y explica cómo puede influir quien fija el orden de votación."}],"figure":{"src":"assets/figuras/10.1.svg","alt":"La paradoja de Condorcet en tres votaciones Orden de preferencias de cada votante Votante 1 A > B > C Votante 2 B > C > A Votante 3 C > A > B A B C 1 y 3 1 y 2 2 y 3 Cada flecha va del ganador al perdedor (2 votos a 1)."}},{"id":"10.2","title":"Es racional ser ignorante en las decisiones públicas","ideas":["La ignorancia racional surge cuando el tiempo y el esfuerzo necesarios para informarse superan el beneficio privado esperado de hacerlo. En una elección multitudinaria, la probabilidad de que un voto cambie el resultado suele ser pequeña. La persona puede abstenerse, recurrir a indicios baratos o votar con información incompleta. El mismo razonamiento sirve para urbanismo, pensiones o regulación financiera.","La clase ilustra la diferencia entre importancia pública e incentivo individual con cifras históricas estadounidenses. En 2010, según los ejemplos citados, el 34 % identificaba qué presidente aprobó el rescate bancario de 2008 y el 39 % situaba correctamente la defensa como la mayor partida de gasto discrecional. También menciona el desconocimiento de los candidatos al Congreso, del peso presupuestario de la seguridad social y de la relación entre la URSS y la OTAN en 1964."],"source":"112–113","page":91,"questions":[{"id":"10.2-c1","type":"comprension","prompt":"¿Qué coste tiene obtener información política fiable?","options":["Exige buscar fuentes, estudiarlas, contrastarlas y renunciar a otros usos del tiempo.","Exclusivamente la tasa obligatoria por consultar el programa electoral en la mesa de votación.","Ninguno cuando la información se publica gratis, cualquiera que sea el tiempo de preparación."]},{"id":"10.2-c2","type":"comprension","prompt":"¿Qué reduce el beneficio privado de informarse en una elección muy concurrida?","options":["La escasa probabilidad de que el voto individual cambie la política elegida.","El hecho de que cada voto determine con certeza el resultado colectivo.","La disminución del precio de consultar la información electoral, manteniendo todo lo demás constante."]},{"id":"10.2-c3","type":"comprension","prompt":"¿Por qué puede ser racional usar la opinión de familiares como atajo?","options":["Porque la opinión de un familiar garantiza acertar incluso si contradice toda fuente fiable.","Porque compartir opiniones en familia aumenta el peso legal del voto en el recuento.","Porque reduce el coste de búsqueda incluso si el resultado informativo es menos preciso."]},{"id":"10.2-c4","type":"comprension","prompt":"¿Qué ilustra la comparación entre estudiar urbanismo tres años y consultar la prensa?","options":["Que el coste de oportunidad del tiempo dedicado a estudiar urbanismo es cero en período electoral.","Que quien no dedica tres años al urbanismo pierde legalmente el derecho a votar sobre ese asunto.","Que el coste de especializarse para tomar una sola decisión electoral puede superar con mucho el beneficio individual esperado."]},{"id":"10.2-c5","type":"comprension","prompt":"¿Qué miden el 34 % y el 39 % citados en clase?","options":["Son porcentajes de ciudadanos que contestaron correctamente dos cuestiones distintas en 2010: la autoría presidencial del rescate bancario y el peso de la defensa en el gasto discrecional.","El gasto en defensa y el gasto en rescates como porcentajes del presupuesto federal de 2010.","El porcentaje de votantes que se abstuvo en 2008 y la proporción que votó por un rescate en referéndum."]},{"id":"10.2-d","type":"desarrollo","prompt":"Explica por qué una política muy importante para la sociedad puede recibir poca atención racional de cada votante."}]},{"id":"10.3","title":"Los votantes son generalmente irracionales","ideas":["La irracionalidad racional, asociada a Bryan Caplan, describe la aceptación de creencias sesgadas cuando sostenerlas tiene poco coste privado. Se distingue de la ignorancia racional porque un votante puede disponer de información y aun así desatenderla. La clase plantea una elección hipotética entre tecnologías energéticas para ilustrar la diferencia entre conocer una comparación y votar conforme a ella.","Se distinguen cuatro sesgos: antimercado (infravalorar la coordinación del mercado), antiextranjero (infravalorar los beneficios de intercambiar con extranjeros), favorable a preservar trabajo por sí mismo (infravalorar el ahorro de mano de obra) y pesimista (exagerar la gravedad de los problemas o infravalorar los avances). Los errores ocurren también en compras privadas, pero en decisiones colectivas parte de sus consecuencias recae sobre terceros."],"source":"113","page":92,"questions":[{"id":"10.3-c1","type":"comprension","prompt":"¿En qué difiere la irracionalidad racional de la ignorancia racional?","options":["En la primera se mantiene una creencia sesgada incluso teniendo información pertinente. En la segunda se elige invertir poco en obtener información.","Ambas describen exclusivamente una imposibilidad física de acceder a la información.","La primera consiste en no recabar datos y la segunda en ignorar pruebas que ya se conocen por apego a una creencia."]},{"id":"10.3-c2","type":"comprension","prompt":"¿Cómo clasificarías la creencia de que comprar productos extranjeros siempre empobrece al comprador nacional?","options":["Como ignorancia sobre el precio exacto, aunque se sostenga que el intercambio siempre perjudica a cualquier precio.","Como sesgo favorable al ahorro de trabajo, puesto que la creencia compara horas de producción.","Como sesgo antiextranjero, porque descuenta las posibles ganancias de comerciar."]},{"id":"10.3-c3","type":"comprension","prompt":"¿Qué beneficio pasa por alto el sesgo favorable a preservar empleo por sí mismo?","options":["Que ahorrar trabajo en una tarea libera tiempo y personas para otros fines.","Que las técnicas de producción más lentas maximizan la renta porque ocupan a más trabajadores.","Que todo aumento del empleo es una ganancia neta con independencia de qué se produzca."]},{"id":"10.3-c4","type":"comprension","prompt":"¿En qué se distinguen los sesgos pesimista y antimercado?","options":["El pesimista subestima exclusivamente el comercio exterior y el antimercado solo exagera los riesgos climatológicos.","El sesgo pesimista infravalora los problemas económicos y el antimercado exagera los beneficios de los mercados.","El primero exagera los problemas o infravalora los avances generales. El segundo subestima específicamente los beneficios del mecanismo de mercado."]},{"id":"10.3-c5","type":"comprension","prompt":"¿Por qué cambia el coste del error al pasar de comprar a votar?","options":["La probabilidad de que una decisión individual cambie el resultado colectivo es siempre uno.","El votante paga siempre el coste íntegro de su error individual y el comprador lo reparte entre toda la población.","El comprador suele experimentar de forma directa las consecuencias de su decisión. En una votación la influencia individual es pequeña y el resultado se aplica a muchos."]},{"id":"10.3-d","type":"desarrollo","prompt":"Compara a quien desconoce las alternativas energéticas con quien las conoce y vota según una creencia previa."}]},{"id":"10.4","title":"La democracia está controlada por grupos organizados","ideas":["Cuando la supervisión ciudadana es costosa, los actores organizados pueden influir de forma sostenida. Los políticos obtienen apoyo con propaganda y medidas de efecto visible antes de las elecciones. Los grupos de presión usan contactos y recursos para conseguir favores regulatorios. Los burócratas influyen desde la administración mediante la información y el margen de decisión que les proporciona su puesto.","La captura del regulador ocurre cuando éste sirve a los intereses particulares que debería supervisar. La renta obtenida mediante un privilegio ayuda a explicar por qué un grupo dedica recursos a la influencia política. Los beneficios concentrados favorecen la organización, mientras que para cada ciudadano puede resultar costoso supervisar un perjuicio disperso."],"source":"114","page":93,"questions":[{"id":"10.4-c1","type":"comprension","prompt":"¿Cómo aprovecha un político la miopía electoral?","options":["Puede ofrecer beneficios visibles a corto plazo aunque los costes aparezcan después de las elecciones.","Adelantando los costes públicos y ocultando todas las ventajas hasta después de las elecciones para hacerlas más visibles hoy.","Presentando a los votantes solo beneficios que podrán observar varias décadas después de votar, para obtener una recompensa inmediata verificable."]},{"id":"10.4-c2","type":"comprension","prompt":"¿Qué busca un grupo de presión al influir sobre el regulador?","options":["Reemplazar la regulación por una mejora puramente técnica en la fábrica sin alterar decisión pública alguna.","Una regla, excepción o privilegio que le reporte beneficios.","Que desaparezca cualquier posibilidad de que una norma afecte al grupo, incluso las excepciones que le beneficiarían."]},{"id":"10.4-c3","type":"comprension","prompt":"¿Cómo puede influir un burócrata sin presentarse a elecciones?","options":["Participando desde dentro en el diseño o ejecución de las decisiones mediante información y atribuciones poco supervisadas.","Reasignando por sí mismo los votos emitidos a quien prometa apoyar su departamento.","Ejerciendo exclusivamente el derecho a aprobar leyes reservado a todos los funcionarios por el hecho de serlo."]},{"id":"10.4-c4","type":"comprension","prompt":"¿Por qué una ventaja concentrada incentiva la organización?","options":["Porque cualquier grupo pequeño representa por definición a toda la población perjudicada.","Porque la concentración reduce a cero la ventaja que obtiene cada miembro del grupo.","Porque cada beneficiario tiene mucho en juego y puede obtener un rendimiento considerable del esfuerzo colectivo."]},{"id":"10.4-c5","type":"comprension","prompt":"¿Cómo se relacionan captura del regulador y captura de rentas?","options":["La primera da influencia sobre quien fija o aplica la regla. La segunda es la búsqueda del beneficio que produce el privilegio obtenido.","Son términos sin relación, porque las reglas que aplica el regulador nunca alteran el valor de un privilegio.","La captura de rentas consiste en mejorar la producción y la captura del regulador consiste en atraer clientes con innovaciones."]},{"id":"10.4-d","type":"desarrollo","prompt":"Explica por qué un privilegio para un grupo pequeño podría sobrevivir en un régimen de sufragio amplio."}]},{"id":"10.5","title":"¿Produce la democracia buenos resultados?","ideas":["La sesión distingue la calidad de cada decisión colectiva de los resultados observados a largo plazo. En la comparación histórica mostrada para 2007, Nueva Zelanda y Estados Unidos presentan niveles de vida mayores que Uruguay y Eslovenia, y el material compara también los casos de Congo y Níger. Se observa una asociación entre democracia, libertad económica y nivel de vida. Esa comparación por sí sola no identifica el efecto causal de cada institución.","La explicación propuesta destaca libertad de expresión, pensamiento y asociación, prensa libre, descentralización del poder y propiedad privada. Estas instituciones permiten crítica y control, y hacen posible crear y conservar riqueza. Amartya Sen vincula la prevención de hambrunas con democracias que funcionan y cuentan con prensa y oposición. Aun en democracias con instituciones inclusivas pueden aparecer élites extractivas."],"source":"114–115","page":94,"questions":[{"id":"10.5-c1","type":"comprension","prompt":"¿Qué tres variables relaciona la comparación presentada en clase?","options":["El tipo de interés, el nivel de endeudamiento y la recaudación fiscal.","La participación en las elecciones, el número de partidos y el tamaño del parlamento.","La democracia, la libertad económica y el nivel de vida."]},{"id":"10.5-c2","type":"comprension","prompt":"¿Qué permite afirmar la comparación entre países de 2007?","options":["Que hay una asociación en los casos mostrados. Por sí sola no cuantifica una causa independiente de las diferencias de renta.","Que se ha medido el efecto causal aislado del voto manteniendo constantes todas las demás instituciones.","Que todos los países democráticos tienen exactamente el mismo nivel de renta."]},{"id":"10.5-c3","type":"comprension","prompt":"¿Qué papel desempeñan la prensa y la oposición ante una crisis alimentaria?","options":["La prensa modifica directamente las existencias de alimentos al publicar información sobre una crisis.","Pueden hacer visibles los daños y aumentar el coste político de ignorarlos, favoreciendo una respuesta pública.","La oposición garantiza por ley un aumento instantáneo de la cosecha cuando solicita un debate."]},{"id":"10.5-c4","type":"comprension","prompt":"¿Qué instituciones se añaden al voto en la explicación del profesor?","options":["Libertades de expresión, pensamiento y asociación, descentralización del poder, propiedad privada y libertad de prensa.","El control universal de precios y la eliminación de derechos de propiedad privada.","La censura de la crítica, la centralización del poder y la prohibición de asociaciones."]},{"id":"10.5-c5","type":"comprension","prompt":"¿Cómo pueden coexistir inclusión y extracción?","options":["Un marco general de derechos puede favorecer la prosperidad y permitir a la vez que grupos concretos consigan privilegios.","La inclusión elimina por definición cualquier privilegio sectorial dentro de la democracia.","La existencia de un grupo privilegiado demuestra que todos los derechos de todos los ciudadanos han desaparecido."]},{"id":"10.5-d","type":"desarrollo","prompt":"Concilia los fallos de la democracia explicados en el módulo con la prosperidad observada en varias democracias."}]},{"id":"10.6","title":"Foro 24: Irracionalidad democrática o irracionalidad racional","note":"Sin contenido en los archivos adjuntos."},{"id":"10.6.1","title":"Solución foro: Irracionalidad democrática o irracionalidad racional","note":"Sin contenido en los archivos adjuntos."}]},{"number":11,"title":"Intervencionismo: Impuestos, subsidios y proteccionismo","items":[{"id":"11.0","title":"Introducción","ideas":["La introducción plantea dos problemas distintos. En los cigarrillos, interesa averiguar si el coste del impuesto recae sobre los fumadores o sobre las tabaqueras. En el agua subvencionada al cultivo de algodón en California, interesa identificar qué parte del coste público corresponde a una pérdida de eficiencia. La introducción no aporta datos para cuantificar el segundo caso.","Conviene empezar cada problema con el precio y la cantidad que habría sin intervención. Después se distingue qué parte cambia de manos, qué cantidades se dejan de intercambiar o se intercambian de más y quién puede ajustar su conducta con mayor facilidad."],"source":"101","page":95,"questions":[{"id":"11.0-c1","type":"comprension","prompt":"¿Qué dos casos abren la sesión?","options":["El impuesto sobre los cigarrillos y el subsidio al agua utilizada por los productores de algodón en California.","La subvención al consumo de cigarrillos y el impuesto sobre el agua para riego del algodón.","El precio máximo de los cigarrillos y el arancel al algodón procedente de California."]},{"id":"11.0-c2","type":"comprension","prompt":"¿Qué pregunta plantea el caso del tabaco?","options":["Qué tipo de tabaco permite obtener la máxima producción por hectárea.","Cuál es el coste medio de fabricar una cajetilla antes de introducir el gravamen.","Quién acaba soportando el impuesto entre fumadores y tabaqueras."]},{"id":"11.0-c3","type":"comprension","prompt":"¿Qué magnitud interesa en el caso del agua?","options":["La suma pagada al regante, que constituye íntegramente pérdida irrecuperable por definición.","La pérdida irrecuperable ocasionada por inducir un uso del agua cuyo coste de oportunidad supera su beneficio.","El precio de venta de todo el algodón estadounidense como medida exacta de la pérdida del agua subvencionada."]},{"id":"11.0-c4","type":"comprension","prompt":"¿Qué sirve de referencia para medir el cambio?","options":["El precio máximo anunciado por el ministerio, aunque no sea vinculante.","La cantidad producida por otro sector con preferencias y costes diferentes.","El precio, la producción y el consumo que resultarían en el mismo mercado sin esa intervención."]},{"id":"11.0-c5","type":"comprension","prompt":"¿Por qué el desembolso público no basta para cuantificar la pérdida de eficiencia?","options":["Parte del gasto es una transferencia. Hay que valorar también cómo cambian las cantidades y el beneficio y coste marginales de las unidades afectadas.","Porque una subvención no puede modificar las cantidades y solo habría que añadir los gastos contables de la administración.","Porque cualquier transferencia pública constituye en sí misma una pérdida irrecuperable de igual importe."]},{"id":"11.0-d","type":"desarrollo","prompt":"Compara las preguntas que abren la sesión y explica qué información necesitarías para responderlas."}]},{"id":"11.1","title":"¿Qué es un impuesto?","ideas":["Un impuesto sobre un bien es un pago obligatorio asociado a una operación gravada. Un impuesto específico, por ejemplo un euro por kilogramo, separa dos precios. Si Pc es lo que paga el comprador, Pv lo que conserva el vendedor y t el impuesto unitario, se cumple Pc − Pv = t. Se aplica tanto si el vendedor ingresa el impuesto en Hacienda como si lo hace el comprador.","Hay tres preguntas diferentes: quién cumple la obligación legal, quién soporta la carga económica después del ajuste de precios y qué ocurre con el excedente total. En el modelo competitivo de la clase, la recaudación transfiere parte del excedente al Estado y la reducción de la cantidad intercambiada elimina ganancias del comercio."],"source":"101","page":96,"questions":[{"id":"11.1-c1","type":"comprension","prompt":"¿Qué diferencia un impuesto específico de un pago voluntario?","options":["La obligación surge por realizar la operación gravada y su importe se expresa por unidad física.","El contribuyente puede elegir pagar según el valor subjetivo que atribuye al servicio público.","Su importe se fija necesariamente como un porcentaje del precio de venta del bien."]},{"id":"11.1-c2","type":"comprension","prompt":"¿Qué relación une los dos precios con un impuesto de un euro por kilogramo?","options":["Por cada kilogramo, el comprador paga un euro más de lo que conserva el vendedor.","El vendedor conserva un euro más por kilogramo de lo que paga el comprador.","El precio bruto que paga el comprador coincide con el ingreso neto del vendedor por kilogramo."]},{"id":"11.1-c3","type":"comprension","prompt":"¿Qué significa incidencia legal?","options":["La proporción de carga económica que soporta finalmente el comprador.","Identifica a la persona obligada a ingresar el dinero en Hacienda.","La cantidad de intercambios mutuamente ventajosos que se pierden."]},{"id":"11.1-c4","type":"comprension","prompt":"¿De qué depende la incidencia económica según el curso?","options":["Exclusivamente del lado del mercado al que la ley obliga a ingresar el dinero.","Solo del número absoluto de compradores respecto del número de empresas.","De cómo responden compradores y vendedores, en especial de las elasticidades relativas de oferta y demanda."]},{"id":"11.1-c5","type":"comprension","prompt":"¿Cómo se calcula lo recaudado con un impuesto específico?","options":["Multiplicando el precio total pagado por el cliente por la cantidad vendida después de gravarla.","Multiplicando el impuesto unitario por la cantidad que efectivamente se negocia tras introducirlo.","Multiplicando el impuesto unitario por las unidades que dejan de venderse."]},{"id":"11.1-d","type":"desarrollo","prompt":"Explica a un comprador por qué hace falta distinguir el recibo de Hacienda del coste económico del impuesto."}]},{"id":"11.2","title":"El coste de los impuestos","ideas":["Antes del impuesto, las unidades se intercambian mientras el valor marginal para el comprador cubra el coste marginal de producirlas. Con una cuña fiscal disminuyen los excedentes de comprador y vendedor. Una parte se convierte en recaudación, R = t × Q con impuesto. El resto es la pérdida irrecuperable por intercambios que habrían beneficiado a ambas partes. Con rectas de oferta y demanda, el área triangular es ½ × t × (Q inicial − Q con impuesto).","En el primer ejemplo se pasa de 500 kg a 1,50 €/kg a 400 kg con precios de 2,10 € y 1,10 €. La cuña es 1 €, el Estado ingresa 400 € y, con rectas, se pierden 50 € de excedente total. Para un mismo impuesto, una respuesta mayor de las cantidades aumenta la pérdida. La curva de Laffer recuerda que elevar el tipo puede acabar reduciendo la recaudación al contraer su base. El curso añade que el rendimiento social del gasto posterior depende de cómo se empleen los fondos y destaca dificultades de información e incentivos."],"source":"101–104","page":97,"questions":[{"id":"11.2-c1","type":"comprension","prompt":"¿En cuánto varía el precio para cada parte en el ejemplo de los 500 kg?","options":["El comprador paga 0,60 € más y el vendedor recibe 0,40 € menos por kilogramo respecto de los 1,50 € iniciales.","El comprador paga 1 € más y el vendedor conserva exactamente los 1,50 € anteriores por kilogramo.","El comprador paga 0,40 € más y el vendedor recibe 0,60 € menos por kilogramo."]},{"id":"11.2-c2","type":"comprension","prompt":"¿Cuánto recauda el Estado tras caer las ventas a 400 kg?","options":["100 €, aplicando el impuesto solo a la reducción de ventas.","400 €, resultado de multiplicar 1 €/kg por 400 kg.","500 €, aplicando el impuesto a los 500 kg intercambiados antes de gravarlos."]},{"id":"11.2-c3","type":"comprension","prompt":"¿Qué área mide la pérdida irrecuperable en el ejemplo lineal?","options":["El triángulo entre oferta y demanda correspondiente a las 100 unidades perdidas. Su área es ½ × 1 × 100 = 50 €.","El rectángulo de base 100 y altura 1, de 100 €, porque todas las unidades excluidas tenían una ganancia de 1 €.","El rectángulo de recaudación sobre las 400 unidades vendidas, de 400 €."]},{"id":"11.2-c4","type":"comprension","prompt":"¿Por qué, a igualdad de condiciones, una demanda más elástica agranda la pérdida?","options":["Porque una demanda más elástica implica que ninguna compra cambia con el precio.","Porque la misma intervención aparta del mercado más unidades cuyo valor para el comprador superaba su coste de producción.","Porque convierte por definición cada euro recaudado en un euro de pérdida irrecuperable."]},{"id":"11.2-c5","type":"comprension","prompt":"¿Cómo puede aumentar el tipo y caer la recaudación?","options":["Si el tipo y la cantidad gravada aumentaran simultáneamente, la recaudación caería por la forma de la curva de Laffer.","Si el número de unidades permaneciera constante, la recaudación caería al elevarse el tipo.","Si la cantidad gravada disminuye proporcionalmente más de lo que aumenta el tipo, el producto de ambos cae. Es el tramo descendente de la curva de Laffer."]},{"id":"11.2-d","type":"desarrollo","prompt":"Distingue con los datos de la clase el coste para los participantes, el ingreso fiscal y la pérdida para el conjunto."}],"figure":{"src":"assets/figuras/11.2.svg","alt":"Impuesto al plátano: 100 kg dejan de intercambiarse Precio (€/kg) Cantidad de plátanos (kg) 1,10 1,50 2,10 400 500 Oferta Demanda Antes: 500 kg a 1,50 €/kg. Con impuesto: el comprador paga 2,10 €/kg y el vendedor recibe 1,10 €/kg. Recaudación: 1 €/kg × 400 kg = 400 €. Triángulo de pérdida ½ × 100 kg × 1 €/kg = 50 €."}},{"id":"11.3","title":"¿Quién paga los impuestos?","ideas":["Gravar al vendedor eleva la oferta inversa en el importe del impuesto cuando el eje muestra el precio bruto. Gravar al comprador reduce en ese importe la demanda inversa cuando el eje muestra el precio neto. Las dos representaciones producen la misma cuña y la misma cantidad. La parte menos elástica tiene menos alternativas para evitar el impuesto y acaba soportando una fracción mayor.","En el segundo ejemplo, el precio inicial es 3 € y la cantidad 260. Un impuesto de 1 € deja Pc = 3,70 €, Pv = 2,70 € y la cantidad en 200. Los compradores soportan 0,70 € por unidad y los vendedores 0,30 €. La clase propone aplicar el criterio a fumadores y tabaqueras. El reparto depende de las elasticidades relativas en el horizonte estudiado."],"source":"104–106","page":98,"questions":[{"id":"11.3-c1","type":"comprension","prompt":"¿Qué curva se desplaza si el impuesto por unidad se exige al vendedor?","options":["La oferta expresada en términos del precio que paga el comprador se desplaza hacia arriba por el importe del impuesto.","La oferta expresada en términos del precio bruto se desplaza hacia abajo por el importe del impuesto.","La demanda bruta aumenta porque el vendedor se encarga de ingresar el impuesto."]},{"id":"11.3-c2","type":"comprension","prompt":"¿Qué cambia si se exige al comprador?","options":["El comprador absorbe necesariamente el euro completo y el precio neto del vendedor permanece fijo.","La disposición a pagar al vendedor aumenta en un euro y desaparece la cuña entre ambos precios.","La disposición a pagar al vendedor, una vez deducido el impuesto, baja en su importe. La cantidad final y la cuña son las mismas."]},{"id":"11.3-c3","type":"comprension","prompt":"¿Qué fracción de la carga por unidad asumen los compradores en el segundo ejemplo?","options":["El 30 %, porque el vendedor recibe 0,30 € menos por unidad.","El 100 %, porque el comprador desembolsa el precio final del producto.","El 70 %, ya que pagan 0,70 € más de una cuña total de 1 €."]},{"id":"11.3-c4","type":"comprension","prompt":"¿Qué cantidades se intercambian antes y después y cuánto se recauda?","options":["Se pasa de 260 a 200 unidades y se recaudan 260 €, al gravarse también las ventas que se pierden.","Se pasa de 200 a 260 unidades y se recaudan 60 €, por el incremento de las ventas.","Se pasa de 260 a 200 unidades. A un euro por unidad, la recaudación es de 200 €."]},{"id":"11.3-c5","type":"comprension","prompt":"¿Qué condición haría recaer más carga sobre los fumadores?","options":["Que Hacienda exigiera el ingreso a los fumadores, con independencia de toda reacción de las cantidades al precio.","Que la demanda de cigarrillos fuese perfectamente elástica y la oferta relativamente rígida.","Que la demanda de cigarrillos sea menos elástica que la oferta en el plazo considerado, lo que dificultaría a los consumidores reducir sus compras."]},{"id":"11.3-d","type":"desarrollo","prompt":"Un fumador sostiene que subir el impuesto solo perjudica a la empresa que lo ingresa. Evalúa su argumento con el ejemplo numérico."}],"figure":{"src":"assets/figuras/11.3.svg","alt":"Quién soporta el impuesto de 1 € por unidad Carga por unidad vendida 0,70 € 0,30 € Comprador · 70 % Vendedor · 30 % La carga se mide respecto al precio previo de 3 €. La cantidad vendida pasa de 260 a 200 unidades. Precio de compra 3,00 € → 3,70 € Ingreso neto del vendedor 3,00 € → 2,70 €"}},{"id":"11.4","title":"¿Qué son los subsidios?","ideas":["Un subsidio unitario es una ayuda pública vinculada a la cantidad comprada o vendida. Si s es la ayuda, Pv − Pc = s: el productor recibe más de lo que desembolsa el consumidor. Las elasticidades determinan quién capta el beneficio económico. La persona a la que la administración transfiere la ayuda puede compartirla indirectamente con la otra parte a través del precio.","Los contribuyentes financian el gasto s × Q con subsidio. En el mercado competitivo sin efectos externos del ejemplo, la expansión del comercio puede llevar a producir unidades cuyo coste marginal supera la disposición a pagar. Para calcular el efecto conjunto se resta el gasto fiscal del aumento de los excedentes privados."],"source":"106","page":99,"questions":[{"id":"11.4-c1","type":"comprension","prompt":"¿Por qué se describe el subsidio como un impuesto inverso?","options":["Porque el comprador paga más de lo que recibe el vendedor y el Estado se queda con la diferencia.","Porque devuelve a cada contribuyente exactamente lo que ingresó con cualquier impuesto anterior.","Porque abre una cuña en sentido contrario: el vendedor recibe más de lo que paga el comprador y el Estado cubre la diferencia."]},{"id":"11.4-c2","type":"comprension","prompt":"¿Qué determina el beneficiario económico de una ayuda unitaria?","options":["El lado del mercado con más participantes, aun cuando ambos tengan la misma elasticidad y difieran sus tamaños.","Exclusivamente el nombre de la persona que recibe la transferencia del gobierno.","La reacción de compradores y vendedores al precio y sus elasticidades relativas."]},{"id":"11.4-c3","type":"comprension","prompt":"¿Quién financia la diferencia entre los precios?","options":["Los productores mediante una deducción por el mismo importe sobre el precio neto que reciben.","El presupuesto público, financiado por los contribuyentes en el análisis del curso.","Los compradores mediante un recargo unitario igual a toda la ayuda sobre su precio final."]},{"id":"11.4-c4","type":"comprension","prompt":"¿Qué cantidad entra en la fórmula del gasto fiscal?","options":["Solo el aumento de la cantidad vendida respecto del equilibrio sin ayuda.","La cantidad vendida antes de la ayuda aunque las ventas aumenten después.","La cantidad total que se vende con la ayuda, multiplicada por la subvención unitaria."]},{"id":"11.4-c5","type":"comprension","prompt":"¿Qué riesgo de eficiencia presenta una expansión inducida por la ayuda?","options":["Que las últimas unidades cuesten más de producir que el valor que les asignan sus compradores.","Que desaparezca toda pérdida de eficiencia en cuanto el comprador pague un precio menor.","Que forzosamente deje de producirse la parte de las unidades cuyo valor supera al coste."]},{"id":"11.4-d","type":"desarrollo","prompt":"Explica por qué ingresar una subvención en la cuenta del productor no demuestra que éste capture todo el beneficio."}]},{"id":"11.5","title":"El coste de los subsidios","ideas":["En el ejemplo de los plátanos se pasa de 260 kg a 3 €/kg a 300 kg. El consumidor paga 2,70 € y el vendedor recibe 3,70 €. La ayuda es 1 €/kg, el gasto público 300 € y, con rectas, la pérdida de eficiencia es ½ × 1 × (300 − 260) = 20 €. Esta vez la pérdida procede de unidades adicionales que cuestan más de lo que valen para sus compradores.","El lado menos elástico, que soportaría más carga bajo un impuesto, también tiende a recibir más beneficio de un subsidio. Según el ejemplo canario, los compradores pueden cambiar de origen del plátano o de fruta con más facilidad que los productores pueden cambiar de cultivo a corto plazo. La oferta relativamente inelástica permite que los productores capten una parte mayor."],"source":"106–107","page":100,"questions":[{"id":"11.5-c1","type":"comprension","prompt":"¿Cuánto gana cada parte por unidad respecto al precio inicial de 3 €?","options":["El comprador ahorra 1 € y el productor conserva exactamente 3 € por kilogramo.","El comprador ahorra 0,70 € y el productor recibe 0,30 € adicionales por kilogramo.","El comprador ahorra 0,30 € y el productor recibe 0,70 € adicionales por kilogramo."]},{"id":"11.5-c2","type":"comprension","prompt":"¿A cuánto asciende el gasto público si se venden 300 kg subvencionados?","options":["A 300 €, porque la brecha entre ambos precios es de 1 €/kg.","40 €, aplicando la ayuda solamente a los 40 kg adicionales.","260 €, aplicando la ayuda solamente a las ventas anteriores al subsidio."]},{"id":"11.5-c3","type":"comprension","prompt":"¿Qué área representa la pérdida en el ejemplo lineal?","options":["El rectángulo del gasto público de 300 €, íntegramente irrecuperable.","El triángulo entre el coste marginal y la disposición a pagar desde 260 hasta 300 kg, con área de 20 €.","Un triángulo cuya base son los 300 kg vendidos y cuya altura es la cuña, de 150 €."]},{"id":"11.5-c4","type":"comprension","prompt":"¿Qué opciones hacen relativamente elástica la demanda del plátano canario?","options":["La imposibilidad de encontrar en el mercado cualquier fruta que sustituya al plátano canario.","Las posibilidades de arrancar plataneras y cambiar inmediatamente de cultivo al otro extremo del archipiélago.","Comprar plátanos de otra procedencia o sustituirlos por otra fruta."]},{"id":"11.5-c5","type":"comprension","prompt":"¿Por qué importa la referencia al corto plazo?","options":["Porque las decisiones de compra y de cultivo tienen necesariamente la misma elasticidad en todos los plazos.","Porque un cultivo implantado ofrece a sus productores pocas posibilidades inmediatas de ajuste. En otro horizonte las elasticidades y el reparto pueden cambiar.","Porque a corto plazo los agricultores pueden cambiar instantáneamente de cultivo sin ningún coste."]},{"id":"11.5-d","type":"desarrollo","prompt":"Usa el ejemplo canario para explicar cómo una misma ayuda puede aumentar el excedente privado y reducir el excedente total."}],"figure":{"src":"assets/figuras/11.5.svg","alt":"Subsidio al plátano: 40 kg adicionales y 20 € de pérdida Precio (€/kg) Cantidad de plátanos (kg) 2,70 3,00 3,70 260 300 Oferta Demanda Antes: 260 kg a 3,00 €/kg. Con ayuda: el vendedor recibe 3,70 €/kg y el comprador paga 2,70 €/kg. Gasto público: 1 €/kg × 300 kg = 300 €. Triángulo de pérdida ½ × 40 kg × 1 €/kg = 20 €."}},{"id":"11.5.1","title":"Foro 25: Impuestos y subsidios","note":"La transcripción plantea el caso del tabaco en 11.3 y el del plátano en 11.5. No reproduce un foro independiente."},{"id":"Solución foro: Quién paga el impuesto","title":"Solución foro: Quién paga el impuesto","note":"Sin contenido en los archivos adjuntos."},{"id":"Solución foro: Impuestos y subsidios","title":"Solución foro: Impuestos y subsidios","note":"Sin contenido en los archivos adjuntos."},{"id":"11.6","title":"Analizando el comercio internacional con la oferta y la demanda","ideas":["La especialización por ventaja comparativa depende del coste de oportunidad. El comercio también permite intercambiar bienes valorados de forma diferente y aprovechar la división del trabajo y del conocimiento. El dinero reduce costes de transacción y los precios coordinan decisiones dispersas. En ausencia de comercio exterior, el cruce de la oferta y la demanda nacionales determina precio y cantidad.","En el ejemplo importador de los tomates, el precio mundial está por debajo del precio nacional en autarquía. A ese precio disminuye la producción interna, aumenta la cantidad demandada y la diferencia se importa: M = Qd interna − Qo interna. Los productores que ya no cubren su coste de oportunidad pueden dedicar sus recursos a otros usos."],"source":"107–108","page":101,"questions":[{"id":"11.6-c1","type":"comprension","prompt":"¿Qué magnitud permite identificar una ventaja comparativa?","options":["El precio nominal de la unidad en dos monedas distintas sin convertirlas ni valorar los usos alternativos.","La producción física total del país, sin atender a otros bienes que podría obtener con esos recursos.","El coste de oportunidad de producir una unidad medido en otros bienes sacrificados."]},{"id":"11.6-c2","type":"comprension","prompt":"¿Qué dos problemas resuelven el dinero y los precios en una economía especializada?","options":["El dinero elimina la escasez material y los precios eliminan toda diferencia de preferencias.","El dinero facilita los intercambios y reduce sus costes. Los precios transmiten información para coordinar planes productivos dispersos.","El dinero iguala las productividades físicas y los precios garantizan que todos produzcan el mismo bien."]},{"id":"11.6-c3","type":"comprension","prompt":"¿Dónde se obtiene el precio de los tomates en autarquía?","options":["En el cruce de las curvas nacionales de oferta y demanda.","En el cruce de la oferta mundial con la demanda de los importadores extranjeros.","Sumando al precio mundial cualquier coste arancelario aunque el país no comercie."]},{"id":"11.6-c4","type":"comprension","prompt":"¿Qué ocurre con las dos cantidades domésticas si llega un precio mundial inferior?","options":["Aumenta la cantidad producida en el país y disminuye su consumo doméstico.","Disminuyen tanto las compras domésticas como la producción nacional al bajar el precio.","Los consumidores aumentan sus compras y los productores nacionales reducen la cantidad que ofrecen."]},{"id":"11.6-c5","type":"comprension","prompt":"¿Cómo se obtienen las importaciones a partir del gráfico?","options":["Sumando la cantidad producida en el país a la que desean comprar sus consumidores.","Midiendo, al precio mundial, la distancia horizontal entre la cantidad demandada interna y la ofrecida por los productores nacionales.","Midiendo el desnivel vertical entre el precio nacional de autarquía y el mundial."]},{"id":"11.6-d","type":"desarrollo","prompt":"Explica cómo se pasa del equilibrio sin comercio a las importaciones de tomates y qué ocurre con los recursos nacionales."}],"figure":{"src":"assets/figuras/11.6.svg","alt":"Cómo leer las importaciones a un precio mundial dado Precio Cantidad doméstica Importaciones Qo Qd Oferta Demanda El cruce marca el precio sin comercio. La línea horizontal marca un precio mundial inferior. A ese precio, el país consume Qd y produce solo Qo. Importaciones = Qd − Qo Esquema del mercado importador de tomates."}},{"id":"11.7","title":"Analizando las tarifas o impuestos a la importación y exportación","ideas":["El desarrollo del profesor corresponde a un arancel específico sobre importaciones. En el modelo de país que toma el precio mundial como dado, el precio interno del bien importado aumenta desde P mundial hasta P mundial + arancel, mientras continúen las importaciones. La oferta exterior relevante para el comprador nacional aparece más arriba. El productor doméstico recibe el precio interno más alto.","A ese precio, los hogares compran menos y las empresas nacionales ofrecen más. La brecha entre ambas cantidades se estrecha. Los ingresos públicos son arancel por unidad × importaciones posteriores. En el título oficial figuran también las exportaciones, pero la transcripción no desarrolla un caso de gravamen a la exportación."],"source":"108–109","page":102,"questions":[{"id":"11.7-c1","type":"comprension","prompt":"¿Qué precio se eleva en el modelo de país tomador del precio mundial?","options":["El precio mundial que reciben todos los exportadores del mundo sube siempre exactamente en el valor del arancel.","El precio mundial sube, mientras el precio pagado por los consumidores nacionales se mantiene fijo.","El precio interior con el arancel. El precio mundial anterior al gravamen sirve de referencia."]},{"id":"11.7-c2","type":"comprension","prompt":"¿Por qué aumentan las ventas de productores nacionales?","options":["El precio interior más alto permite cubrir costes a productores que, al precio mundial, no podían competir.","Porque el arancel mejora automáticamente la tecnología y reduce en su importe el coste de cada productor local.","Porque se aplica una cuota mínima de compras nacionales por hogar igual al arancel."]},{"id":"11.7-c3","type":"comprension","prompt":"¿Por qué disminuye el consumo?","options":["Porque la producción doméstica aumenta y eso obliga a cada consumidor a disminuir su cantidad aun con un precio invariable.","Los compradores se mueven a lo largo de su demanda y renuncian a unidades cuyo valor no cubre el precio más alto.","Porque el arancel desplaza las preferencias hacia una cantidad menor a todos los precios, manteniéndose fijo el precio interno."]},{"id":"11.7-c4","type":"comprension","prompt":"¿Cómo se miden las importaciones después del arancel?","options":["Restando la producción interna inicial al consumo inicial de autarquía.","Se resta la oferta doméstica de la demanda doméstica, ambas evaluadas al precio con arancel.","Sumando producción y consumo domésticos, ambos evaluados al precio con arancel."]},{"id":"11.7-c5","type":"comprension","prompt":"¿Sobre qué unidades cobra el Estado el arancel?","options":["Solo sobre las unidades cuya importación deja de realizarse debido al aumento de precio.","Sobre todos los bienes vendidos dentro del país, tanto importados como de producción nacional.","Sobre las unidades que cruzan la frontera sujetas al gravamen. La producción nacional queda fuera de esa base."]},{"id":"11.7-d","type":"desarrollo","prompt":"Explica a partir de oferta y demanda por qué un arancel puede reducir las importaciones por dos vías a la vez."}]},{"id":"11.8","title":"El coste del proteccionismo","ideas":["En el ejemplo del curso, a 7 €/kg la producción nacional de tomates es cero porque los productores domésticos tienen costes superiores. Con la protección llega a 30 millones de kg al año. El área A ilustra la pérdida productiva: se dedican recursos nacionales a producir tomates con un coste superior al de obtenerlos en el mercado mundial.","El área B representa la pérdida de consumo. Algunas unidades tenían para los compradores un valor superior al coste mundial, pero inferior al precio con arancel, y dejan de adquirirse. Los beneficios de los productores protegidos y la recaudación pública son parte del reparto. La pérdida neta suma las distorsiones de producción y consumo. Las cifras de precio y cantidad indicadas por sí solas no permiten calcular en euros esas dos áreas."],"source":"109–110","page":103,"questions":[{"id":"11.8-c1","type":"comprension","prompt":"¿Por qué no se producían tomates en el país a 7 €/kg en el ejemplo?","options":["Porque ningún consumidor nacional estaba dispuesto a comprar tomates a 7 €/kg.","Porque una prohibición legal impedía cultivar tomates hasta implantar el arancel.","Porque ningún productor doméstico podía ofrecerlos con un coste igual o inferior al precio mundial."]},{"id":"11.8-c2","type":"comprension","prompt":"¿Cuál es el cambio observado en la producción doméstica tras imponer protección?","options":["Pasa de 30 millones de kg al año a cero.","Aumenta en siete millones de kg al año porque el precio mundial es de 7 €/kg.","Pasa de cero a 30 millones de kilogramos por año."]},{"id":"11.8-c3","type":"comprension","prompt":"¿Qué mide el área A?","options":["Los ingresos públicos por las importaciones que siguen realizándose después del arancel.","El exceso de coste de las unidades nacionales adicionales sobre el coste de obtenerlas del exterior.","El valor de los intercambios perdidos por la disminución del consumo interior, excluyendo el coste productivo adicional."]},{"id":"11.8-c4","type":"comprension","prompt":"¿Qué mide el área B?","options":["La ganancia que se pierde al dejar de consumir unidades cuyo valor marginal excedía el coste mundial.","La recaudación arancelaria sobre las unidades que todavía se importan.","El sobrecoste de producir dentro del país las unidades que antes se podían importar más baratas."]},{"id":"11.8-c5","type":"comprension","prompt":"¿Por qué la ganancia de los productores protegidos no prueba que aumente el bienestar nacional?","options":["Porque toda la ganancia privada se transfiere necesariamente a productores extranjeros.","Porque parte de esa ganancia se financia mediante el mayor precio pagado por los consumidores, y además se pierden recursos en producción y consumo.","Porque la ganancia individual del productor protegido ya incluye por definición todas las pérdidas de los consumidores nacionales."]},{"id":"11.8-d","type":"desarrollo","prompt":"Un productor celebra que el arancel haya creado una industria doméstica del tomate. Evalúa el resultado para el conjunto del país."}],"figure":{"src":"assets/figuras/11.8.svg","alt":"Dos pérdidas del arancel sobre el tomate Precio (€/kg) 7 € 7 € + t 0 30 Cantidad (millones de kg/año) A B Oferta Demanda A · Producción Producir 30 millones de kg dentro del país cuesta más que importarlos a 7 €/kg. B · Consumo Las compras perdidas valían más que el coste mundial de suministrarlas. Esquema. t representa el arancel por kg."}},{"id":"11.8.1","title":"Foro 26: Proteccionismo","note":"Sin contenido en los archivos adjuntos."},{"id":"11.8.2","title":"Solución foro: Proteccionismo","note":"Sin contenido en los archivos adjuntos."}]}];
